window.__D("text/torat-shmuel/c050",{"p":[[2000480384,"לזאת למה יאהב את ההארה יותר טוב שיאהב את העצם, וכמו כשנותנין לו תפוח מתוק יותר, או כששומע ניגון מתוק יותר וקול ערוב יותר וכן כשמקבל תענוג מהשכל ואומרים לו כשיש<sup data-n=\"3766\">98</sup> שכל עמוק יותר, וכמו\"כ כשיתבונן בהתבוננות הנ\"ל לא ירצה גם בבחי' כי הוא חייך כ\"א שיהי' לו אהבה ותשוקה לא\"ס עצומ\"ה לדבקה בו, והנה כמו עד\"מ אדם שנטה מהדרך ותועה במדבר וא\"י למצוא הדרך ואח\"כ בא א' והביא אותו על הדרך ה\"ה מתמלא תענוג ומחזיק טובה מאד להאדם ההוא, כמו\"כ כשהוא טרוד ומוטרד ברבות המח' הטורדות אותו ה\"ה כמדבר שממון, וכאשר מתבונן בהתבוננות הנ\"ל ה\"ה בא על הדרך צריך שיתמלא תענוג גדול מזה, אך הנה כתי' לכתך אחרי במדבר<sup data-n=\"3767\">99</sup> כמו במשל הנ\"ל כשהביא אותו על הדרך הישר לא זאת הכוונה שיחזיק לו טובה כ\"א שילך אח\"כ בדרך הישר, כמו\"כ כאן אחר ההתבוננות הנ\"ל צריך שיהי' אח\"כ ההילוך הליכות עולם לו<sup data-n=\"3768\">100</sup> וזהו ההילוך דתומ\"צ, וזהו ק\"ש דשחרית וערבית, אבל ק\"ש שעהמ\"ט הוא מס\"נ קרוב לפועל דבעת השינה הנפש מסתלק מן הגוף ועולה למעלה כמ\"ש בידך אפקיד רוחי<sup data-n=\"3769\">101</sup> ולכן בק\"ש שעהמ\"ט צריך לעשות חשבון צדק בנפשו<sup data-n=\"3770\">102</sup> בכל הדיבורים ומח' אשר לא לה' המה [וצ\"ל תחילה התשובה חרטה על העבר באמת ואח\"כ אפשר התשובה דוהרוח תשוב אל אלקים אשר נתנו ], וזהו התשובה והרוח תשוב אל אלקים אשר נתנו שהנפש עולה לשרשה ומקורה, ולכן אי' בכהאריז\"ל שבק\"ש שעהמ\"ט בכוונה<sup data-n=\"3771\">103</sup> מתקנים כמה פגמים.\n<b>וביאור</b> הענין הנה כתי' עולת שבת בשבתו על עולת התמיד<sup data-n=\"3772\">104</sup>, דהנה התפלה הו\"ע אהוי\"ר והם כנפים<sup data-n=\"3773\">105</sup> כנפי יונה וכמארז\"ל מה היונה כנפי' מגינות עלי' כך ישראל מצות מגינים עליהם<sup data-n=\"3774\">106</sup>, ואהבה מקור רמ\"ח מ\"ע ויראה מקור שס\"ה ל\"ת<sup data-n=\"3775\">107</sup>, וזהו כנפי יונה שהם כלים להרצון<sup data-n=\"3776\">108</sup> והם נק' גדפין לאורייתא דאורייתא בלא דחילא ורחימא לא פרחא לעילא<sup data-n=\"3777\">109</sup>, וזהו שבת<sup data-n=\"3778\">110</sup> שזהו הארת שבת שבששת יומין",[["3766","98","<b>ערוב. . כשיש</b>: כ\"ה בגוכתי\"ק."],["3767","99","<b>לכתך אחרי במדבר</b>: ירמי' ב, ב."],["3768","100","<b>הליכות עולם לו</b>: חבקוק ג, ו."],["3769","101","<b>בידך אפקיד רוחי</b>: תהלים לא, ו."],["3770","102","<b>בק\"ש שעהמ\"ט. . חשבון צדק בנפשו</b>: ראה זהר קרח קעח, א. (לעיל בחלק המאמרים) המשך יונתי כאן פכ\"ב ובהערה 549."],["3771","103","<b>בכהאריז\"ל שבק\"ש שעהמ\"ט בכוונה</b>: ראה פע\"ח שער ק\"ש שעהמ\"ט שט\"ז, פ\"ב. פ\"ה. פ\"ח ואילך. תניא פ\"ז יב, סע\"א."],["3772","104","<b>עולת שבת. . עולת התמיד</b>: נסמן לקמן בהערה 112."],["3773","105","<b>אהוי\"ר והם כנפים</b>: ראה תניא פ\"מ. פמ\"א ובמ\"מ הגהות והע\"ק שם ע' רסט. מאמרי אדה\"א בראשית ע' עה. וש\"נ."],["3774","106","<b>מה היונה. . מגינים עליהם</b>: ראה שבת מט, א."],["3775","107","<b>ואהבה. . רמ\"ח מ\"ע. . שס\"ה ל\"ת</b>: ראה תניא פ\"ד ובמ\"מ, הגהות והע\"ק לשם. של\"ה מאמר ג ומאמר ד נא, ב. מאמרי אדה\"א קונטרסים ע' פז. וש\"נ."],["3776","108","<b>כנפי יונה שהם כלים להרצון</b>: ראה (לעיל בחלק המאמרים) ריש המשך יונתי ובהערה 9."],["3777","109","<b>דאורייתא. . לא פרחא לעילא</b>: בתניא פל\"ט בתיקונים — ת\"ז ת\"י כה, ב."],["3778","110","<b>וזהו שבת</b>: בהצילום אינו ברור וכנראה נכתב: וזהו עולת שבת."]]],[2000480385,"דחול וזהו התפלה<sup data-n=\"3779\">111</sup> דששת יומין דחול שאז זמן העלי', ועולת שבת בשבתו<sup data-n=\"3780\">112</sup> הוא שהתפלה דימי החול מתעלה בתפלה דשבת, וכן השינה בשבת דשינה בשבת תענוג<sup data-n=\"3781\">113</sup> שהוא למעלה מהשינה דחול, דבשינה דחול הנשמה עולה ושואבת לה חיים<sup data-n=\"3782\">114</sup> מלמעלה שהוא התרחבות הנפש בהגוף אבל בשבת שינה בשבת תענוג שהוא למעלה מהתרחבות הנפש ולכן השינה דחול מתעלה בשינה דשבת, וכן התפילה דחול מתעלה בתפילה דשבת וזהו\"ע התשובה החזרת הנפש והרוח תשוב אלקי'<sup data-n=\"3783\">115</sup> אשר נתנו, עין לא ראתה אלקים זולתך, דכתי' זבחי אלקים רוח נשברה<sup data-n=\"3784\">116</sup> דכל הקרבנות הם קרבן לה' אבל לשם אלקי' אינו שייך קרבן<sup data-n=\"3785\">117</sup>, אבל רוח נשברה הוא קרבן לאלקים שעי\"ז יומשך הענג למטה דאם לעוברי רצונו כך<sup data-n=\"3786\">118</sup> נמשך ענג כ\"כ כ\"ש לעושי רצונו נמשך עונג העליון, וזהו יפה שעה בתשובה ומע\"ט שהתשו' הוא אעפ\"י שלא חטא והו\"ע השבת הנפש לבחי' אשר נתנו, וזהו עכשיו בנפיחה רק הארה אבל לע\"ל לאחר גמר הבירורים יהי' בנתינה וכמ\"ש ונתתי רוחי בכם וחייתם חיים וקיימים לעולם.",[["3779","111","<b>הארת שבת שבששת יומין. . התפלה</b>: ראה לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה סמכוני באשישות ובהערה 23."],["3780","112","<b>ועולת שבת בשבתו</b>: פינחס כח, י. ראה תו\"א תרומה פ, ב. לקו\"ת בהר מא, א."],["3781","113","<b>דשינה בשבת תענוג</b>: ראה של\"ה מסכת שבת קלד, ב. ילקוט ראובני ואתחנן עה\"פ (ד, יט) ופן תשא עיניך. שו\"ע אדה\"ז הל' שבת רסרפ\"א. סרצ\"ב, ב. סה\"מ תרל\"ו ח\"ב ע' שיב (ר\"ת שבת). לקו\"ש בהר כרך יב ע' 254. ובאג\"ק שלו חי\"ב ע' תמח."],["3782","114","<b>הנשמה עולה ושואבת לה חיים</b>: נסמן (לעיל בחלק המאמרים) המשך יונתי כאן הערה 490."],["3783","115","<b>תשוב אלקי'</b>: אוצ\"ל: תשוב אל אלקי'."],["3784","116","<b>זבחי אלקים רוח נשברה</b>: תהלים נא, יט. ראה גם אגה\"ת פ\"ז. תניא פי\"ז."],["3785","117","<b>קרבן לה'. . אלקי' אינו שייך קרבן</b>: ראה זהר משפטים דק\"ח ע\"א. ויקרא ה, א. (לעיל בחלק המאמרים) מאמר ד\"ה ביום השמיני עצרת ובהערה 17."],["3786","118","<b>דאם לעוברי רצונו כך</b>: ראה מכות בסופה. לקו\"ת בהעלותך לג, ד. שלח מז, א."]]],[2000480386,"<h3>כנשר יעיר קנו</h3>\n<b></b><b>ש\"פ האזינו תרמ\"א לפ\"ק</b>\nש\"פ האזינו\n<b>כנשר</b> יעיר קנו<sup data-n=\"3787\">1</sup> על גוזליו ירחף יפרוש כנפיו יקחהו ישאהו על אברתו<sup data-n=\"3788\">2</sup>, ופי' המפרשים<sup data-n=\"3789\">3</sup> דכל העופות נושאים בניהם בין רגליהם שמתיראים מפני העופות שמעופפים למעלה מהם אבל הנשר שדרך הנשר בשמים<sup data-n=\"3790\">4</sup> כמו שמים לרום<sup data-n=\"3791\">5</sup>,",[["3787","1","<b>כנשר יעיר קנו</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב — כנראה חלק — ממאמר ד\"ה זה שנדפס לעיל בחלק המאמרים. וש\"נ.\nהנחה אחרת ממאמר זה נדפסה לקמן בחלק ההנחות."],["3788","2","<b>כנשר יעיר. . ישאהו על אברתו</b>: האזינו לב, יא."],["3789","3","<b>ופי' המפרשים</b>: (לעיל בחלק המאמרים) בהמאמר כאן מציין לרש\"י (עה\"פ — ראה גם מכילתא יתרו יט, ד)."],["3790","4","<b>שדרך הנשר בשמים</b>: משלי ל, יט."],["3791","5","<b>שמים לרום</b>: משלי כה, ג."]]],[2000480387,"רק שמתיראה מחץ של בנ\"א לכן נושא את בניו על אברתו, אברתו גוף והוא נושאם למעלה מהגוף, והנמשל הוא דהגם דכתי' ועל דמות הכסא דמות כמראה אדם עליו מלמעלה<sup data-n=\"3792\">6</sup> מ\"מ אין לו דמות הגוף ואין לו גוף<sup data-n=\"3793\">7</sup> ומ\"ש זאת התורה אדם<sup data-n=\"3794\">8</sup> הוא דרמ\"ח פקודין רמ\"ח אברים דמלכא<sup data-n=\"3795\">9</sup> ושס\"ה ל\"ת שס\"ה גידים<sup data-n=\"3796\">10</sup>, וכמו האברים שהם כלים להחיות ובהם מתפשטים כוחות הנפש כמו\"כ מצות הם כלים להמשכת אלקות, וזהו אברתו שהוא הגוף, ישאהו על אברתו למעלה מרמ\"ח אברים כו' ולכאו' צ\"ל איך שייך למעלה ממצות, דאף שהם אברי\"ם דמלכא, מ\"מ ה\"ה רצה\"ע ומה שייך למעלה מרצה\"ע.\n<b>אך</b> הנה צ\"ל תחילה מ\"ש כנשר יעיר קנו דהנה נשר הו\"ע התעוררות רחמים<sup data-n=\"3797\">11</sup> זכור לעבדיך לאברהם יצחק ויעקב<sup data-n=\"3798\">12</sup> ונת\"ל דר\"ר שייך בד\"כ אפי' כשאכשור<sup data-n=\"3799\">13</sup> דרא<sup data-n=\"3800\">14</sup>, מכ\"ש מי שפגם, ומדת הרחמים הוא מדתו של יעקב<sup data-n=\"3801\">15</sup> שהי' מרכבה למדת הת\"ת<sup data-n=\"3802\">16</sup>, וכמ\"ש לולי אלקי אבי אברהם<sup data-n=\"3803\">17</sup> ופחד יצחק הי' לי שהי' בריח התיכון המחבר חו\"ג וגם קצה העליון וקצה התחתון<sup data-n=\"3804\">18</sup> לכן הי' נחלה בלי מצרים<sup data-n=\"3805\">19</sup>, והנה לכאו' ענין הרחמנות שייך על מי שחסר לו באיזה פרט, או שחסר לו הכלל, אבל מי שאינו חסר לו כלום (בל\"א דעם וואס איז זייער גוט) אינו שייך רחמנות, אך באמת אינו כן אלא אפי' על עולמות עליונים כל שנושא עליו שם עולם שייך עליו רחמים<sup data-n=\"3806\">20</sup>, דהנה כתי' מלכותך מל' כל עולמים<sup data-n=\"3807\">21</sup>, ופי' כל העולמים כל העולמות שנבראו הם מבחי' מל', אך אפ\"ל אותן שנבראו כבר אבל לא אותן שעדיין לא היו, אבל תי' כל הוא<sup data-n=\"3808\">23</sup>",[["3792","6","<b>ועל דמות הכסא. . מלמעלה</b>: יחזקאל א, כו."],["3793","7","<b>אין לו דמות. . גוף</b>: ע\"פ פיוט יגדל. ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה נעשה אדם ובהערה 31."],["3794","8","<b>זאת התורה אדם</b>: חוקת יט, יד. ראה זהר רע\"מ משפטים קיז, ב. צו כט, ב. תו\"א תרומה עט, ג. מאמרי אדה\"א דברים ח\"ד ע' א'שכז. וש\"נ."],["3795","9","<b>דרמ\"ח פקודין רמ\"ח אברים דמלכא</b>: ראה ת\"ז ת\"ל (עד, סע\"א). תניא רפכ\"ג. סידור שער החנוכה רפ, א. שע\"ת עב, ג הערה 17."],["3796","10","<b>ושס\"ה ל\"ת שס\"ה גידים</b>: ראה תרגום יוב\"ע בראשית א, כז. זהר וישלח קע, ב."],["3797","11","<b>נשר. . רחמים</b>: ראה לקו\"ת במדבר י, א. יא, ב. שה\"ש מט, ב. אוה\"ת האזינו ע' א'תרפה ואילך. קהלת יעקב מערכת נשר."],["3798","12","<b>זכור לעבדיך. . ויעקב</b>: ע\"פ עקב ט, כז."],["3799","13","<b>ונת\"ל דר\"ד. . כשאכשור דרא</b>: ראה לעיל (בחלק המאמרים) המשך יונתי פכ\"ד."],["3800","14","<b>כשאכשור דרא</b>: ע\"פ יבמות לט, ב. חולין צג, ב."],["3801","15","<b>הרחמים. . יעקב</b>: ראה לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול ובהערה 18."],["3802","16","<b>יעקב שהי' מרכבה למדת הת\"ת</b>: ראה לעיל שם ובהערה 16."],["3803","17","<b>לולי אלקי אבי אברהם</b>: ויצא לא, מב [בדילוג]. ראה לעיל שם ובהערה 109. תו\"א תולדות יז, ג."],["3804","18","<b>שהי' בריח התיכון. . וקצה התחתון</b>: ראה זהר בשלח נא, ב. תרומה קעה, ב. הנסמן במאמרי אדה\"א שמות ח\"א ע' יט. סה\"מ תרכ\"ט ע' קיז. וש\"נ. תרנ\"ג ע' רנח ואילך."],["3805","19","<b>נחלה בלי מצרים</b>: שבת קיח, סע\"א."],["3806","20","<b>עולמות עליונים. . רחמים</b>: ראה גם לקו\"ת במדבר ג, א. מאמרי אדה\"א דברים ח\"א ע' צג. וש\"נ. סה\"מ תרל\"ח ע' ח. וש\"נ."],["3807","21","<b>מלכותך מל' כל עולמים</b>: תהלים קמה, יג."],["3808","23","<b>הוא</b>: תיבת הוא נכפלה, נכתבה בסוף השורה ובהתחלת שורה הבאה."]]],[2000480388,"מספר חמישים<sup data-n=\"3809\">22</sup> וא\"כ כל עולמים פי' העולמים כמו שהם בחמישים וכולל אפי' העליות דנו\"ן אלפים יובלות<sup data-n=\"3810\">24</sup>, דשית אלפי שנין הוה עלמא<sup data-n=\"3811\">25</sup> וחד חרוב הוא שבוע ויש שנה ושמיטה ויובל<sup data-n=\"3812\">26</sup> ונו\"ן אלפים יובלות והכל הוא מבחי' מל' דמלך שמו נק' עליהם<sup data-n=\"3813\">27</sup> כמו השם שהוא הארה בעלמא כמו\"כ בחי' מל' הוא הארה בעלמא ומזה נתהווה הנו\"ן<sup data-n=\"3814\">28</sup> אלפים, דגם עתה ישנם בהעלם ואח\"כ יתגלה מהעלם אל הגילוי, וכמו העולם דעכשיו הי' תחילה בכלל ויצא לידי פרט כמו\"כ הנו\"ן אלפי' יובלות הם עתה בהעלם, וכ\"ז נתהווה מבחי' מל' ולכן אני הוי' לא שניתי<sup data-n=\"3815\">29</sup> שלא יש שום שינוי בין קודם הברי' לאחר הברי' אתה הוא קודם שנבה\"ע<sup data-n=\"3816\">30</sup> ואתה הוא לאחר שנבה\"ע הגם דקודם לזה לא הי' עולמות ואח\"כ נתהווה עולמות אך כלליות השתל' העולמות הוא משם והארה בעלמא שאינו נוגע לעצמיות ואין ההארה פועל שינוי בעצם, ואפי' עולמות הא\"ס שהם עולמות נעלים ונק' א\"ס מ\"מ מאחר שנק' עולם ה\"ה מעלים על אור הא\"ס שבתוכו, וכל העולם יש אין המהווה אותו, והאין אינו מושג דאל\"כ לא הי' מציאות העולם כמו שהוא, א\"כ ה\"ז הארה לבד, וע\"ז הנביא מתמה, אני ה' לא שניתי ואתם בנ\"י לא כליתם<sup data-n=\"3817\">31</sup> דמהתבוננותו איך שלא שניתי צ\"ל כלות הנפש ותשוקה לאלקות ואתם לא כליתם, והתירוץ הוא שהם בני יעקב עקב הלב מכל ואנוש הוא<sup data-n=\"3818\">32</sup> פי' חלוש וכמ\"ש עון עקבי יסובני<sup data-n=\"3819\">33</sup> אלו עבירות שאדם דש בעקביו<sup data-n=\"3820\">34</sup> ע\"צ ההרגל כי פנה אלי ערף<sup data-n=\"3821\">35</sup> כו' לכן לא כליתם.\n<b>וזהו</b> באדם למטה כמו\"כ בעולמות עליונים הם מעלימים כו' ובפרטיות העולמות הנה ע\"ס דאצי' אי' בעה\"ק הוא אינון ואינון הוא<sup data-n=\"3822\">36</sup>, אך מזה גופא מובן שהם העלם, דבא\"ס הפשוט אינו שייך לומר זה, אבל הע\"ס דאצי' לכאו' אינו כן ע\"ז אמר הוא אינון כו' וא\"כ אפי' ספי' ל' בהירות<sup data-n=\"3823\">37</sup> הכל לגבינו אבל לגבי א\"ס ה\"ז העלם, והנבראים דבי\"ע אפי' נבראים הגדולים כמו מלאך שבשליש עולם עומד<sup data-n=\"3824\">38</sup> ויש",[["3809","22","<b>כל. . חמישים</b>: ראה מאו\"א מערכת היכל אות יא. לקו\"ת מטות פה, ב ובהנסמן במ\"מ לשם. מאמרי אדה\"ז תקס\"ד ע' כז ואילך."],["3810","24","<b>דנו\"ן אלפים יובלות</b>: ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה בן פורת יוסף הא' ובהערה 20."],["3811","25","<b>דשית אלפי שנין הוה עלמא</b>: ראה ר\"ה לא, א. מאמרי אדה\"א בראשית ע' נג. וש\"נ."],["3812","26","<b>שבוע ויש שנה ושמיטה ויובל</b>: ראה גם לקמן (בחלק ההנחות) בהנחה כאן ובהערה 30."],["3813","27","<b>דמלך שמו נק' עליהם</b>: ראה פיוט אדון עולם. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ישקני ובהערה 16."],["3814","28","<b>הנו\"ן</b>: ממעל לתיבה זו נכתבה תיבת שמו( )."],["3815","29","<b>אני ה' לא שניתי</b>: מלאכי ג, ו. ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה צאינה וראינה ובהערה 82."],["3816","30","<b>אתה הוא קודם שנבה\"ע</b>: ראה תפלת השחר. של\"ה תולדות אדם ג, ב. מאמרי אדה\"ז על מארז\"ל ע' שלו."],["3817","31","<b>ואתם בנ\"י לא כליתם</b>: המשך הכתוב אני ה' לא שניתי. ראה תו\"א יתרו סז, א. לעיל (בחלק המאמרים) המשך יונתי ובהערה 663."],["3818","32","<b>עקב הלב מכל ואנוש הוא</b>: ירמי' יז, ט."],["3819","33","<b>עון עקבי יסובני</b>: תהלים מט, ו."],["3820","34","<b>עבירות שאדם דש בעקביו</b>: ראה של\"ה מס' תענית ר, ב. לקמן (בחלק ההנחות) בהנחה כאן ובהערה 37."],["3821","35","<b>כי פנה אלי ערף</b>: ירמי' ב, כז [ושם: פנו]. ראה גם לעיל הנחה ד\"ה אני לדודי הב' ובהערה 138."],["3822","36","<b>אי' בעה\"ק. . הוא אינון ואינון הוא</b>: ראה שם חלק היחוד פ\"ד. לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח הערה 102."],["3823","37","<b>ספי' ל' בהירות</b>: ראה לקו\"ת אמור לה, ב."],["3824","38","<b>מלאך שבשליש עולם עומד</b>: ראה ב\"ר פס\"ח, יב. חולין צא, ב. לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול הערה 44."]]],[2000480389,"מלאכים שאמרו קדוש פ\"א ועמדו ב\"א אלפים שנה בביטול כו' ועכשיו הם עומדים בביטול דקדוש פ\"ג<sup data-n=\"3825\">39</sup>, מ\"מ ה\"ה גוף ונפש וכמ\"ש עושה מלאכיו רוחות<sup data-n=\"3826\">40</sup> משרתיו אש לוהט רק שהם רק מב' יסודות הדקים מ\"מ ה\"ה גוף לכן אמרז\"ל שבקוהו למט\"ט<sup data-n=\"3827\">41</sup> שהוא ממלאכים הגבוהים וענשו אותו מצד הגוף, רק ששם אינו נק' גוף ונפש כ\"א אור וכלי אבל הכלי מסתיר על האור, והאדם שנשפל בעוה\"ז השפל והנבזה אפי' צדיק גמור שאין עליו שום לכלוך אפי' שום הרהור מ\"מ הרי חומר הגוף מעלים ומסתיר דאיזה מצוה שהוא עושה אלו יצויר שהנפש לבד יעשה אותו הרי הי' המצוה באופן אחר רק שאין במציאות כו' א\"כ הרי הגוף מסתיר ולכן משה כשעלה למרום<sup data-n=\"3828\">42</sup> הניח הגוף ביצי'<sup data-n=\"3829\">43</sup> מפני שהוא מסתיר רק אלי' עלה עם הגוף<sup data-n=\"3830\">44</sup> מפני שהי' משם ב\"ן<sup data-n=\"3831\">45</sup> שעיקר הזיכוך בחיצוניות לכן הי' יב\"ח בעיבור<sup data-n=\"3832\">46</sup> שהוא משם ב\"ן אבל משה רבן של כל הנביאים<sup data-n=\"3833\">47</sup> לא עלה עם הגוף הרי שהגוף מסתיר.\n<b>וע\"ז</b> אמר יערוף כמטר לקחי תזל כטל אמרתי<sup data-n=\"3834\">48</sup>, דהנה כתי' ואד יעלה מן הארץ<sup data-n=\"3835\">49</sup> שמלחות הארץ נעשים קיטורים ועננים והם שואבים לחלוחית ומזה יורדים גשמים כמו\"כ אדם יסודו מעפר<sup data-n=\"3836\">50</sup> וכמ\"ש ויצר כו' את האדם עפר<sup data-n=\"3837\">51</sup> כו' וה\"ז ארץ וצ\"ל ואד יעלה מן הארץ, אד הוא ל' שברון<sup data-n=\"3838\">52</sup> וכמאמר שברו הבריות את ערפם<sup data-n=\"3839\">53</sup> מיד הגשמים יורדים, העורף הוא כמ\"ש כי פנה אלי עורף ונת\"ל (ד\"ה יפה שעה א'<sup data-n=\"3840\">54</sup> כו') דלא מפני שהוא בועט ח\"ו ואינו רוצה לעשות המצוה, כ\"א ע\"ד הרגל בלא התבוננות דהגם שהנפש מחי' את הגוף מ\"מ אינם מאירים כחות הנפש כמו שהם וכמו מי שיש לו אבן יקר והוא טמון בתיבה ה\"ה מוסתר דכשהוא בזכוכית רואין",[["3825","39","<b>ויש מלאכים שאמרו קדוש פ\"א. . פ\"ג</b>: ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ישקני מנשיקות פיהו ובהערה 24."],["3826","40","<b>עושה מלאכיו רוחות</b>: תהלים קד, ד. ראה תו\"א בראשית ד, ב. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ואתה תצוה ובהערה 18."],["3827","41","<b>שבקוהו </b>[אוצ\"ל: אפקוהו]<b> למט\"ט</b>: חגיגה טו, א. ראה גם לקמן (בחלק ההנחות) בהנחה כאן ובהערה 51."],["3828","42","<b>משה כשעלה למרום</b>: שבת פח, ב. ב\"מ פו, ב."],["3829","43","<b>משה. . הניח הגוף ביצי'</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 14."],["3830","44","<b>אלי' עלה עם הגוף</b>: מלכים-ב ב, יא. ראה גם לעיל שם ובהערה 17."],["3831","45","<b>אלי'. . משם ב\"ן</b>: ראה פע\"ח שער הק\"ש ש\"ח, פ\"ח. לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 156."],["3832","46","<b>אלי'. . יב\"ח בעיבור</b>: ראה גם (בחלק המאמרים) בהמאמר כאן ובהערה 16."],["3833","47","<b>משה רבן של כל הנביאים</b>: שמו\"ר פכ\"א, ד."],["3834","48","<b>יערוף כמטר.. כטל אמרתי</b>: האזינו לב, ב."],["3835","49","<b>ואד יעלה מן הארץ</b>: בראשית ב, ו. ראה גם המשך וככה תרל\"ז פס\"ו. פלח הרמון שה\"ש ע' פ."],["3836","50","<b>אדם יסודו מעפר</b>: נוסח כי כשמך (תפלת מוסף לימים נוראים — קודם כתר)."],["3837","51","<b>ויצר כו' את האדם עפר</b>: בראשית ב, ז."],["3838","52","<b>אד הוא ל' שברון</b>: ראה ב\"ר פי\"ג, יב (ובמפרשים שם). ירושלמי תענית פ\"ב, ה\"א. מאמר ד\"ה כנשר יעיר קנו תשי\"ט."],["3839","53","<b>שברו הבריות את ערפם</b>: ב\"ר פי\"ג, יד. ראה גם (לעיל בחלק המאמרים) בהמאמר כאן הערה 20."],["3840","54","<b>ונת\"ל (ד\"ה יפה שעה א'</b>: ראה גם לעיל הנחה ד\"ה ובחודש השביעי בפנים סביב הערה 80."]]],[2000480390,"אותו דרך הזכוכית אבל כשהוא בתיבה מעצים גשמים ה\"ה מוסתר, כמו\"כ אף שהנפש מחי' את הגוף מ\"מ הגוף עושה את שלו אך כששברו הבריות את ערפם ה\"ז כמו חרישה שמרפה ארעא<sup data-n=\"3841\">55</sup> שמפרר אותה לחלקים דקים שלא יהי' גוש אחד הגם שנשאר מציאות העפר מ\"מ הוא מפרר ומרכך אותו, ואז פועלים הגשמים שיהי' הצמיחה וכמ\"ש כאשר ירד הגשם כו' והרוה<sup data-n=\"3842\">56</sup> את<sup data-n=\"3843\">57</sup> הארץ והולידה והצמיחה דכשהגשמים יורדים על ארץ קשה לא יהי' מזה צמיחות תבואות כ\"א דשאים ועשבים, אבל כשחורשין תחילה אז פועלים הגשמים שיהי' הצמיחה, וכמו\"כ ענין שברו הבריות כו' הוא כמו שברים קולות קצרות דתקיעה הוא קול פשוט ושברים הוא קולות קצרות היינו שמחלק את הקול, כמו\"כ שברו הבריות את ערפם היינו שמפרר ומחלק חלקי העפרות וגסות וקשיות הגוף ועי\"ז המטר יורד וזהו יערוף כמטר שע\"י יערוף נמשך מטר.\n<b>וענין</b> המטר אין כוונתו מטר גשמי אלא אור רוחני וממנו נמשך מטר גשמי ובד\"כ הו\"ע לימוד התורה וכמארז\"ל כד הוה צריכי עלמא למטרא<sup data-n=\"3844\">58</sup> ארשב\"י דרוש על פסוק מה טוב ומה נעים<sup data-n=\"3845\">59</sup> כו' וירדו גשמים ומה שייכות יש להם, אך שעי\"ז גרם למעלה יחודי' כו' ונמשך השפעה רוחניות למעלה ומזה ירדו גשמים למטה, וזהו כל אורה באליהו בן ברכאל<sup data-n=\"3846\">60</sup> בירידת גשמים הכתוב מדבר ולכאורה מה שייך אור לגשמים אך הנה אמרז\"ל כל המשתמש באור תורה<sup data-n=\"3847\">61</sup> אור תורה מחיהו ופרש\"י ע\"פ והי' אור הלבנה<sup data-n=\"3848\">62</sup> כאור החמה ואור החמה יהי' שבעתים כאור שבעת הימים שבעתים הוא זפ\"ז<sup data-n=\"3849\">63</sup> מ\"ט, ז\"פ מ\"ט שמ\"ג גשם וזהו בחי' ז\"ת דעתיקא<sup data-n=\"3850\">64</sup> שנתצמצם בכמה צמצומים עד שיהי' גשמים וזהו אור תורה מחיהו דגשמים הם חיים לעולם, תזל כטל אמרתי הוא טלא דנטיף מעתיקא<sup data-n=\"3851\">65</sup> שהוא למעלה ממ\"ש במ\"א שרש נש\"י שהם ממזלות דנוצר ונקה<sup data-n=\"3852\">66</sup> שהם שיורא טלא דבדולחא<sup data-n=\"3853\">67</sup> ולא כמו שנת\"ל (ד\"ה שובו ישראל<sup data-n=\"3854\">68</sup> כו') דשרשם הוא שאינו נכנס בפנימיות אלא ע\"פ פשוט מה שנשאר",[["3841","55","<b>חרישה שמרפה ארעא</b>: ראה מועד קטן ב, ב. לקו\"ת האזינו עה, ד. שה\"ש לח, ד. שע\"ת סג, ב ואילך. המשך מים רבים תרל\"ו פקכ\"ו."],["3842","56","<b>כאשר ירד. . והרוה</b>: ישעי' נה, י [ושם: כי אם הרוה — ראה מאמרי אדה\"א הנחות תקע\"ז ע' רכ. וש\"נ]."],["3843","57","<b>את</b>: תיבה זו נכפלה בגוכתי\"ק."],["3844","58","<b>כד הוה צריכי עלמא למטרא</b>: ראה זהר אחרי נט, ב. לקמן (בחלק ההנחות) בהנחה כאן ובהערה 59."],["3845","59","<b>מה טוב ומה נעים</b>: תהלים קלג, א."],["3846","60","<b>כל אורה באליהו בן ברכאל</b>: ראה ב\"ר ספכ\"ו. לעיל הנחה ד\"ה יונתי ובהערה 113."],["3847","61","<b>כל המשתמש באור תורה</b>: כתובות קיא, ב. ראה גם הנסמן בסה\"מ תרל\"ח ע' רצב."],["3848","62","<b>ופרש\"י ע\"פ והי' אור הלבנה</b>: ישעי' ל, כו. סה\"מ תרל\"ח ע' קס. וש\"נ. לעיל הנחה ד\"ה יונתי ובהערה 115."],["3849","63","<b>זפ\"ז</b>: אולי כ\"ה בגוכתי\"ק."],["3850","64","<b>גשם. . ז\"ת דעתיקא</b>: ראה גם לקמן (בחלק ההנחות) בהנחה כאן. המשך וככה תרל\"ז פס\"ז."],["3851","65","<b>טלא דנטיף מעתיקא</b>: ראה זהר בשלח סא, ב. סב, ב. יתרו פג, א. פח, א. אד\"ז האזינו רפח, א."],["3852","66","<b>שרש נש\"י. . דנוצר ונקה</b>: ראה לקו\"ת האזינו עג, ג. סה\"מ תרל\"ח ע' קג. וש\"נ. ע' שצז. לקמן (בחלק ההנחות) בהנחה כאן."],["3853","67","<b>שיורא טלא דבדולחא</b>: זהר ויקרא מט, א."],["3854","68","<b>שנת\"ל (ד\"ה שובו </b>[כנראה שצ\"ל: שובה]<b> ישראל</b>: סביבות הערה 45."]]],[2000480391,"מההשפעה, והגם שהם מגולגלתא דא\"א שלמעלה מאצי' דמחכ' דא\"א מתחיל עולם האצי' כמ\"ש הרמ\"ז<sup data-n=\"3855\">69</sup> אבל גולגלתא הוא למעלה מאצי', מ\"מ ה\"ז רק שערות וצמצומים ומפני ששרשם מגולגלתא לכן הם מטהרים טמא מת וכמ\"ש באגה\"ק<sup data-n=\"3856\">70</sup>, אבל עצם טלא דבדולחא הוא טל תחי'<sup data-n=\"3857\">71</sup> דשיורא טלא דבדולחא הוא רק דוחה טומאת המת, משא\"כ טל תחי' טל שעתיד להחיות בו את המתים<sup data-n=\"3858\">72</sup> ה\"ה פועל שהמת יהי' חי, והנה בחי' טל זה הוא בדרך מתנה ולא ע\"י עבודה אך מתנה נותנים למי ששוה<sup data-n=\"3859\">73</sup>, ובחי' זו יש ג\"כ בתורה וכמארז\"ל ג' שעות הראשונות הקב\"ה יושב ועוסק בתורה<sup data-n=\"3860\">74</sup> דכל היום כל הקורא בתורה הקב\"ה קורא ושונה כנגדו<sup data-n=\"3861\">75</sup> א\"כ צ\"ל קורא בתורה תחילה, אבל שלש שעות הראשונות עוסק בתורה מעצמו וזהו בחי' ג\"ר והוא בחי' טל, ותחילה צ\"ל יערוף כמטר דע\"י ששברו הבריות את ערפם נמשך בחי' מטר ואח\"כ נמשך בחי' טל.\n<b>והנה</b> אף שנמשך בחי' טל מ\"מ גשם הגוף הוא כמו שהי' אף ששיבר אותו מ\"מ נשאר חלק העפר ועז\"נ כנשר יעיר קנו הו\"ע התעוררות רחמים דגבי מ\"ת כתי' ואשא אתכם על כנפי נשרים<sup data-n=\"3862\">76</sup> ואביא אלי וצ\"ל דגבי מ\"ת אינו שייך חטא ועון שהרי הי' קודם מ\"ת<sup data-n=\"3863\">77</sup> א\"כ מהו\"ע ואשא אתכם על כנפי נשרים, אך מפני שבמצרים היו מושקעים במ\"ט דהיפוך<sup data-n=\"3864\">78</sup> ואח\"כ ביצ\"מ כתי' כי ברח העם<sup data-n=\"3865\">79</sup> שברחו מהרע ובחמשים יום קבלו תורה<sup data-n=\"3866\">80</sup> ויחן ישראל נגד ההר כולם כאיש אחד<sup data-n=\"3867\">81</sup> וכפה עליהם הר כגיגית<sup data-n=\"3868\">82</sup> בחי' אה\"ר לכן הי' צ\"ל כנפי נשרים שע\"י התעוררות יוכל לעלות גם דבר גשמי, וכמו\"כ בר\"ה ועשי\"ת ויוה\"כ צ\"ל התעוררות ר\"ר וזהו כל מי שאינו בוכה בר\"ה<sup data-n=\"3869\">83</sup> אין נשמתו שלימה, דשלמות הוא כמו עד\"מ שליח לעשות איזה",[["3855","69","<b>דמחכ' דא\"א מתחיל עולם האצי' כמ\"ש הרמ\"ז</b>: ראה זהר אמור פח, סע\"ב ובהרמ\"ז שם. סה\"מ תרל\"ב ח\"א ע' קפט. המשך תער\"ב ח\"א ע' תסג. ריש ע' תרכב. ח\"ב ע' תתקנו. ח\"ג ע' א'שפא. לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 71. ד\"ה שובה ישראל הב' על יד הערה 121."],["3856","70","<b>וכמ\"ש באגה\"ק</b>: סכ\"ח. ראה גם לקמן (בחלק ההנחות) בהנחה כאן ובהערה 75."],["3857","71","<b>טל תחי'</b>: ראה בהערה הבאה."],["3858","72","<b>טל שעתיד להחיות בו את המתים</b>: ראה שבת פח, ב."],["3859","73","<b>מתנה נותנים למי ששוה</b>: ראה מגילה כו, ב. גיטין נ, ב. ב\"מ טז, א. ב\"ב קנו, א."],["3860","74","<b>ג' שעות הראשונות. . ועוסק בתורה</b>: ראה ע\"ז ג, ב."],["3861","75","<b>כל הקורא. . ושונה כנגדו</b>: נסמן לעיל הנחה ד\"ה אני לדודי הב' הערה 78."],["3862","76","<b>ואשא אתכם על כנפי נשרים</b>: יתרו יט, ד [בדילוג]."],["3863","77","<b>חטא ועון שהרי הי' קודם מ\"ת</b>: ראה ערכין טו, א ואילך."],["3864","78","<b>שבמצרים היו מושקעים במ\"ט דהיפוך</b>: ראה ז\"ח יתרו לא, א. לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 387."],["3865","79","<b>כי ברח העם</b>: בשלח יד, ה. ראה תניא פל\"א."],["3866","80","<b>ובחמשים יום קבלו תורה</b>: ראה לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 1217."],["3867","81","<b>ויחן ישראל. . כאיש אחד</b>: ראה יתרו יט, ב וברש\"י שם. לקו\"ש יתרו כרך כא ע' 104."],["3868","82","<b>וכפה עליהם הר כגיגית</b>: שבת פח, א. ראה תו\"א מג\"א צח, ד. ש\"א ב, ב הערה 33."],["3869","83","<b>כל מי שאינו בוכה בר\"ה</b>: ראה פע\"ח שער השופר שכ\"ו, פ\"ה. לקו\"ש האזינו כרך ט ע' 206. מאמרי אדה\"א דברים ח\"א ע' שיט. וש\"נ. תו\"ח וישב ר, ג הערה 35."]]],[2000480392,"פעולה ואח\"כ כשבא להמשלח וא\"ל מה שפעל אז הוא השלימות, כמו\"כ החיות הוא שליח מהמשלח להחיות את הגוף והמכוון כמ\"ש אנכי עשיתי ארץ<sup data-n=\"3870\">84</sup> ואדם עלי' בראתי מה שאנכי מי שאנכי<sup data-n=\"3871\">85</sup> נשפל שיהי' ארץ הוא בשביל האדם, והאדם בשביל בראתי בגימ' תרי\"ג<sup data-n=\"3872\">86</sup> שעיקר המכוון בשביל תרי\"ג מצות<sup data-n=\"3873\">87</sup>, ואח\"כ בעת השינה עולה החיות למעלה לכן צ\"ל תחילה החשבון צדק בנפשו<sup data-n=\"3874\">88</sup> בינו לבין קונו והמחו\"ד אשר לא לה' המה צ\"ל חרטה גמורה, והמחו\"ד דקדושה צ\"ל חזרה לאלקות.\n<b>וכמו\"כ</b> ר\"ה הוא בכללות השנה שנמשך חיות על כלליות השנה, וכמו\"כ החזרה הוא ג\"כ בר\"ה ואז צ\"ל בכי' וע\"ד מים תחתונים בוכים<sup data-n=\"3875\">89</sup> כו' שאינם רע ח\"ו רק שעד שלא נבה\"ע הי' מים במים<sup data-n=\"3876\">90</sup> שמים העליונים לא היו בתכלית העילוי ומ\"ת בתכלית ההגשמה, וע\"י יהי' רקיע ויהי מבדיל<sup data-n=\"3877\">91</sup> נעשו מ\"ע בתכלית העילוי והרוחניות וכמארז\"ל כשתגיע לאבני שיש טהור א\"ת מים מים<sup data-n=\"3878\">92</sup>, ומ\"ת הם מקור כל תענוגים גשמים, דכשמברך על הדבר גשמי ה\"ה מעלה אותו, אבל אפ\"ל שיהי' ע\"ד בטן רשעים תחסר<sup data-n=\"3879\">93</sup>, לכן הם בוכים על עצם הירידה שהם מחיים דבר גשמי, כמו\"כ הנשמה היא חלק אלוקה ממעל<sup data-n=\"3880\">94</sup>, חלק ה' עמו<sup data-n=\"3881\">95</sup>, חלקי ה' אמרה נפשי<sup data-n=\"3882\">96</sup>, וירדה למטה בגוף שהוא דומם והמכוון כדי שיוכל לעלות כל דבר, אבל מ\"מ ה\"ה דומם וע\"ז צ\"ל הבכי' (ובפ\"א<sup data-n=\"3883\">97</sup> מ\"ת בוכי\"ם ע\"י הבכי' באים לבחי' ברוך כבוד ה' ממקומו<sup data-n=\"3884\">98</sup>, ובכי' שייך אפי' בצדיקים ג\"כ וכמ\"ש בבכי יבואו<sup data-n=\"3885\">99</sup> ובתחנונים אובילם אפי' צדיקים גמורים דכל עלי' הוא ע\"י בכי', וזהו כל מי כו') ומכ\"ש כשידע",[["3870","84","<b>אנכי עשיתי ארץ</b>: ישעי' מה, יב."],["3871","85","<b>שאנכי מי שאנכי</b>: ראה תניא מהדו\"ק ספמ\"ט. לקו\"ת להאריז\"ל תולדות כז, יט בשם הזהר. אבן עזרא תולדות שם. מאמרי אדה\"ז תקס\"ב ח\"א ע' יד. פרשיות התורה ח\"א ע' רט ובהנסמן במ\"מ לשם."],["3872","86","<b>בראתי בגימ' תרי\"ג</b>: ראה לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 1688."],["3873","87","<b>תרי\"ג מצות</b>: ראה מכות כג, סע\"ב. כללי המצות לר\"י גיקטיליא מערכת שש מאות [צפת תשנ\"ב ע' 208). לקו\"ש יתרו כרך כו ס\"ע 424 ואילך. אג\"ק שלו ח\"ג ע' רג."],["3874","88","<b>בעת השינה. . החשבון צדק בנפשו</b>: ראה גם זהר קרח קעח, א. (לעיל בחלק המאמרים) המשך יונתי פכ\"ב ובהערה 549."],["3875","89","<b>מים תחתונים בוכים</b>: ראה ת\"ז ת\"ה (יט, ב). לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח פי\"ט. וש\"נ."],["3876","90","<b>שעד שלא נבה\"ע הי' מים במים</b>: ראה (לעיל בחלק המאמרים) מאמר ד\"ה כמגדל דוד צוארך ובהערה 5."],["3877","91","<b>יהי' </b>[אולי כתוב: יהי] רקיע ויהי מבדיל: בראשית א, ו [בדילוג]. ראה לעיל שם ובהערה 13."],["3878","92","<b>כשתגיע. . מים מים</b>: ראה חגיגה יד, א."],["3879","93","<b>בטן רשעים תחסר</b>: משלי יג, כה [ושם: ובטן]."],["3880","94","<b>הנשמה היא חלק אלוקה ממעל</b>: איוב לא, ב. ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 395."],["3881","95","<b>חלק ה' עמו</b>: האזינו לב, ט."],["3882","96","<b>חלקי ה' אמרה נפשי</b>: איכה ג, כד."],["3883","97","<b>ובפ\"א</b>: ראה גם לעיל הנחה ד\"ה ואהבת את ה' אלקיך ובהערה 74."],["3884","98","<b>ברוך כבוד ה' ממקומו</b>: יחזקאל ג, יב. ראה גם לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח ספ\"ז. וש\"נ."],["3885","99","<b>בבכי יבואו</b>: ירמי' לא, ח."]]],[2000480393,"אינש בנפשו שפגם (בפ\"א כמו פגם הסכין שחסר במקום זה) במח' או דיבור ומכ\"ש בביטל ת\"ת דהי' בידו לעסוק ולא עסק וע\"ז צ\"ל תשובה חרטה ואינו שייך החזרה שה\"ז היפוך. וענין התשוב' אמר רבינו ז\"ל משל ע\"ז כמו א' ההולך לרחוץ בנהר וטבע ה\"ה מתחרט<sup data-n=\"3886\">100</sup> על מה שהלך לרחוץ, חרטה גמורה, כמו\"כ הנשמה שנתלבשה בגוף לעבוד וטרוד בטרדות הפרנסה ה\"ז מים רבים<sup data-n=\"3887\">101</sup>, ובאמת מים רבים לא יוכלו לכבות האהבה<sup data-n=\"3888\">102</sup> מוסתרת שיש בכאו\"א מישראל לכן אפי' קל שבקלים יש כח למס\"נ<sup data-n=\"3889\">103</sup>, אך אם ע\"י ה\"ה<sup data-n=\"3890\">104</sup> כאלו נכבה האהבה, דבאמת הוא הנותן לך כח לעשות חיל<sup data-n=\"3891\">105</sup> והוא מסבב הסיבה והפרנסה, אבל כשאינו מתבונן ותמיד הוא משומם בריבוי מח' הטורדות ער וועט פאר חאפין פאר ל יפין פאר טאן, וה\"ז שקר גמור מי פאר חאפט גאר ניט, וע\"ז צ\"ל תשובה וכשאינו שב עי\"ז עוברי בעמק הבכא<sup data-n=\"3892\">106</sup> מעין ישיתהו ויש ע\"ז ב\"פ א' שקאי על אותן שמצערים אותם בגיהנם<sup data-n=\"3893\">107</sup><sup data-n=\"3894\">108</sup>. . ומייסרים הנפש והם בוכים ונעשה מעינות מהדמעות, ופי' הב' שקאי על עולי רגלים<sup data-n=\"3895\">109</sup> שהיו עושין להם מעיינות לשתות, ולחבר ב' הפי' אפ\"ל דמהדמעות שבוכים על צער ויסורי הנפש נעשי' מעיינות בגיהנום והנה הדין ומשפט דגיהנום הוא לזכך להגוף<sup data-n=\"3896\">110</sup><sup data-n=\"3897\">111</sup> ).",[["3886","100","<b>התשוב' אמר רבינו ז\"ל משל. . בנהר וטבע ה\"ה מתחרט</b>: ראה גם לקמן (בחלק ההנחות) בהנחה כאן ובהערה 119."],["3887","101","<b>בטרדות הפרנסה ה\"ז מים רבים</b>: ראה הערה הבאה."],["3888","102","<b>מים רבים. . האהבה</b>: שה\"ש ח, ז [בדילוג]. ראה תו\"א ר\"פ נח."],["3889","103","<b>קל שבקלים יש כח למס\"נ</b>: ראה תניא פי\"ח. מאמרי אדה\"א הנחות תקע\"ז ע' קלד. וש\"נ. לקו\"ש חנוכה כרך ג ע' 818 בהערה. סה\"מ מלוקט ד' ע' קפח בהערה."],["3890","104","<b>ע\"י ה\"ה</b>: כ\"ה בגוכתי\"ק."],["3891","105","<b>הוא הנותן לך כח לעשות חיל</b>: עקב ח, יח."],["3892","106","<b>עוברי בעמק הבכא</b>: תהלים פד, ז."],["3893","107","<b>ב\"פ א'. . בגיהנם</b>: ראה ערובין יט, א. שמו\"ר פ\"ז, ד. מדרש תהלים פד, ג."],["3894","108","בצילום גוכתי\"ק נכתב כאן תיבה שקשה לפענחה."],["3895","109","<b>ופי' הב' שקאי על עולי רגלים</b>: ראה מצודת דוד ואבן עזרא לתהלים שם."],["3896","110","<b>להגוף)</b>: בגוכתי\"ק לא נרשם התחלת הסוגר."],["3897","111","<b>להגוף)</b>: ע\"כ נכתב בגוכתי\"ק — ראה המשך המאמר לעיל בחלק המאמרים כאן. לקמן (בחלק ההנחות) בהנחה כאן."]]],[2000480394,"<h3>וכל שיח השדה</h3>\n<b>ש\"פ בראשית מ\"א לפ\"ק</b>\n<b>וכל</b> שיח השדה<sup data-n=\"3898\">1</sup> טרם יהי' בארץ כו' ואדם אין לעבוד את אדמה<sup data-n=\"3899\">2</sup> ואי' במדרש שיח תפלה<sup data-n=\"3900\">3</sup> וכמ\"ש ויצא יצחק לשוח בשדה<sup data-n=\"3901\">4</sup> כל שיח דברייתו<sup data-n=\"3902\">5</sup> מרא מתי יתבני בי מקדשא וכמו שאנו מבקשים יה\"ר מלפניך כו' שיבנה בהמק\"ד<sup data-n=\"3903\">6</sup> ואדם אין כאלי' וכחוני המעגל<sup data-n=\"3904\">7</sup> לעבוד הבריות להקב\"ה, וצ\"ל הלא היו כמה צדיקים מופלגים ולמה אומר רק כאלי' וכחוני המעגל, מובן מזה שבפרט זה הם נבדלים מכל הצדיקים, והענין דהנה גבי אלי' כתי' הנה אנכי שולח לכם את אלי' הנביא לפני בא יום ה' הגדול והנורא<sup data-n=\"3905\">8</sup> והשיב לב אבות על בנים<sup data-n=\"3906\">9</sup> ולב בנים על אבותם, ולכאו' צ\"ל מה צריכים לאלי' ע\"ז, דענין הבאת שלום שייך בב' אנשים מרוחקים ומכ\"ז השונאים זא\"ז אבל אב ובן מה יכול להיות קירוב יותר מזה ומה שייך בהם הבאת שלום, והנה בזהר איתא שא' הינוקא<sup data-n=\"3907\">10</sup> לר\"י ור\"י<sup data-n=\"3908\">11</sup> חמינא בריחא דלבושייכא דלא קריתון ק\"ש וא\"ל שעסקו במצות נשואי חו\"כ והעוסק במצוה פטור מן המצוה<sup data-n=\"3909\">12</sup>, ולכאו' אינו מובן דההכרח לומר שע\"י מצות נשואי חו\"כ ממשיכי' ההמשכה שע\"י ק\"ש דא\"ל איך הכיר שלא קראו ק\"ש<sup data-n=\"3910\">13</sup> וא\"כ קשה ממ\"נ אם אינם דומים בהמשכות למה פטור מהמצוה, ואם הם דומים בהמשכתם איך הכיר בהם הינוקא שלא קראו ק\"ש.\n<b>והענין</b> דהנה ארז\"ל ביום חתונתו זו מ\"ת<sup data-n=\"3911\">14</sup> ולכאו' מ\"ת שהוא גילוי העצמיות וכמ\"ש וירד ה' על הר סיני<sup data-n=\"3912\">15</sup> ואמרו ע\"ז משל גס מיחוד חו\"כ והי' להם להמציא משל רוחני יותר, וגם צ\"ל למה במ\"ת שהי' גילוי עצמיות אוא\"ס וכמ\"ש ויהי ביום השלישי כו' ויהי קולות כו' וקול השופר<sup data-n=\"3913\">16</sup> כו' וירד ה' כו' והדברות הם",[["3898","1","<b>וכל שיח השדה</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר ד\"ה זה שנדפס לעיל בחלק המאמרים. וש\"נ.\nמאמר ד\"ה זה שבמאמרי אדמו\"ר מהר\"ש דרושי חתונה ע' קכג הודפס מכאן."],["3899","2","<b>וכל שיח. . ואדם אין לעבוד את אדמה</b>: בראשית ב, ה [ושם: האדמה]."],["3900","3","<b>ואי' במדרש שיח תפלה</b>: לעיל (בחלק המאמרים) בהמאמר כאן כותב: ובמד\"ר במקומו מובן שמפרש שיח לשון תפלה — ראה ב\"ר פי\"ג, ב ובמפרשים שם. פ\"ס, יד. וש\"נ."],["3901","4","<b>ויצא יצחק לשוח בשדה</b>: ח\"ש כד, סג. ראה גם לעיל בחלק המאמרים שם. וש\"נ."],["3902","5","<b>כל שיח דברייתו</b>: ועד\"ז מובא לעיל בהמאמר כאן. ראה ב\"ר שם: כל תפלתן של ישראל."],["3903","6","<b>שאנו מבקשים יה\"ר. . בהמק\"ד</b>: אבות פ\"ה, מ\"כ."],["3904","7","<b>ואדם אין כאלי' וכחוני המעגל</b>: ראה ב\"ר שם ס\"ז. ראה גם הנסמן לעיל (בחלק המאמרים) בהמאמר כאן."],["3905","8","<b>הנה אנכי שולח לכם. . והנורא</b>: מלאכי ג, כג."],["3906","9","<b>והשיב לב אבות על בנים</b>: מלאכי שם, כד."],["3907","10","<b>בזהר איתא שא' הינוקא</b>: ראה שם בלק קפו, א. תו\"ח וארא ח\"א נט, ד."],["3908","11","<b>לר\"י ור\"י</b>: בזהר: ר' יצחק ור' יהודה. ראה גם לעיל (בחלק המאמרים) מאמר ד\"ה ולהבין שרש ענין בחי' מזבח הפנימי ובהערה 115."],["3909","12","<b>והעוסק במצוה פטור מן המצוה</b>: סוכה כה, א. ראה גם הנסמן בלקו\"ש תשא כרך כו ע' 237 הערה 64."],["3910","13","<b>דא\"ל. . ק\"ש</b>: נכתב בין השיטין. וראה בסמוך בפנים."],["3911","14","<b>ביום חתונתו זו מתן תורה</b>: תענית כו, ב (במשנה). ראה מאמרי אדמו\"ר מהר\"ש דרושי חתונה ע' לד. מאמרי אדה\"א דברים ח\"ג ע' תתמז בהערה."],["3912","15","<b>וירד ה' על הר סיני</b>: יתרו יט, כ."],["3913","16","<b>ויהי ביום השלישי. . קולות. . וקול השופר</b>: יתרו שם, טז."]]],[2000480395,"דברים פשוטים<sup data-n=\"3914\">17</sup> לא תרצח לא תנאף לא תגנוב<sup data-n=\"3915\">18</sup> שאלמלי לא נתנה תורה<sup data-n=\"3916\">19</sup> הי' השכל מחייב שיתרחק מהם דלמה יגנוב של חבירו, אך הנה יש ב' מיני השפעות<sup data-n=\"3917\">20</sup>, השפעה חיצוניות והשפעה פנימיות השפעה חיצוניות הוא כמו עד\"מ השפעת הרב לתלמיד הגם שמשפיע לו חכ' וחכ' הוא פנימיות מ\"מ צ\"ל שמשפיע לו רק חיצוניות החכ' והראי' דכשהתלמיד הוא בר שכל אז הוא מבין כשהרב משפיע לו השכל באיזה הלכה שנים אוחזים כו' או המחליף<sup data-n=\"3918\">21</sup> כו' אבל כשהתלמיד אינו בר שכל אף שיסביר לו הרבה מ\"מ לא יבין כלל, ואם נא' שמשפיע לו שישפיע לו<sup data-n=\"3919\">22</sup> עצם המוחין, הרי הרב יודע השכל והתלמיד אף שאינו בר שכל מ\"מ צריך להבין השכל מאחר שנשפע עצם שכל הרב, מובן מזה שהוא רק השפעה חיצוניות ולכן אם התלמיד בעצמו הוא בר שכל רק שהרב משיג יותר ממילא ה\"ה מבין את השכל<sup data-n=\"3920\">23</sup> בטוב יותר, אבל כשהתלמיד אינו בר שכל אינו מועיל כלל השפעת הרב וכמו שמורגל בל' העולם „ ק ‘ קען מען ניט ארוף שט עלין, דהשפעה חיצוניות כשלא יש מי שיקבל ההשפעה נתבטל ההשפעה לגמרי וכמו שארי השפעות חיצוניות, משא\"כ השפעת הטיפה הוא השפעה פנימיות ועצמיות והראי' שהוא מוליד בדומה לו אם<sup data-n=\"3921\">24</sup> מוחין כמו האב, ואפ\"ל יפה כח הבן מכח האב<sup data-n=\"3922\">25</sup> והיינו מפני שנמשך מכח השכל משכל<sup data-n=\"3923\">26</sup> בשכל לכן מה שגבי האב הוא בהעלם אצל הבן הוא בגילוי, והוא [מפני] שהוא השפעה עצמיות (צ\"ע קצת דכח זה יש בהשפעה חיצוניות ג\"כ וכמארז\"ל ומתלמידי יותר מכולם<sup data-n=\"3924\">27</sup> שעי\"ז מאיר מהמשכיל<sup data-n=\"3925\">28</sup> לשכל היינו מה שהי' בהעלם תחילה מאיר בגילוי בשכל ועי\"ז מתוסף בההשפעה להתלמיד ג\"כ).\n<b>ולכאו'</b> צ\"ל והלא רוחניות הוא למעלה מגשמיות ולמה ההשפעה פנימיות נתלבשה בגשמיות והשפעה חיצוניות ברוחניות ולכאו' צ\"ל בהיפך דהשפעה חיצוניות יומשך בגשמיות והשפעה פנימיות ברוחניות. אך הנה הנותנת מפני שהיא מדרי' גבוה יותר אין לה לבוש למטה רק בגשמיות דוקא, והראי' דפני",[["3914","17","<b>והדברות הם דברים פשוטים</b>: ראה גם לקו\"ת במדבר יב, ג. סה\"מ תרכ\"ט ס\"ע ריז ואילך. וש\"נ."],["3915","18","<b>לא תרצח לא תנאף לא תגנוב</b>: יתרו כ, יג."],["3916","19","<b>שאלמלי לא ניתנה תורה</b>: ערובין ק, ב. ראה גם לעיל הנחה ד\"ה יונתי בחגוי הסלע הערה 13."],["3917","20","<b>ב' מיני השפעות</b>: ראה גם לקו\"ת שה\"ש לט, ד. לעיל (בחלק המאמרים) בהמאמר כאן הערה 24."],["3918","21","<b>שנים אוחזים כו' או המחליף</b>: ב\"מ ב, א. ק, רע\"א (במשנה)."],["3919","22","<b>שמשפיע לו שישפיע לו</b>: כ\"ה בגוכתי\"ק."],["3920","23","<b>וכמו שמורגל בל' העולם „ ק ‘. . שטעלין</b>: ראה גם לעיל (בחלק המאמרים) בהמאמר כאן הערה 26."],["3921","24","<b>אם</b>: כ\"ה בכ\"מ — ראה גם סה\"מ תרל\"ח ע' ה. וש\"נ."],["3922","25","<b>יפה כח הבן מכח האב</b>: ראה שבועות מח, סע\"א. לעיל (בחלק המאמרים) בהמאמר כאן ספ\"א. וש\"נ."],["3923","26","<b>משכל</b>: תיבה זו איננה ברורה בצילום גוכתי\"ק."],["3924","27","<b>ומתלמידי יותר מכולם</b>: תענית ז, א. ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 538."],["3925","28","<b>מהמשכיל</b>: תיבה זו איננה ברורה בצילום גוכתי\"ק."]]],[2000480396,"ארי' גבוה מפני שור<sup data-n=\"3926\">30</sup> שה\"ה ימין ושמאל<sup data-n=\"3927\">29</sup> ומ\"מ ארי' למטה הוא חי' טמאה שטורף ודורס<sup data-n=\"3928\">31</sup> ושור הוא בהמה טהורה ויוכל להיות קרבן<sup data-n=\"3929\">32</sup> ריח נחוח לה'<sup data-n=\"3930\">33</sup> ונת\"ל (בד\"ה ביום השמיני עצרת<sup data-n=\"3931\">34</sup> ) שהיא מדריגה גבוה ולכאו' היה צ\"ל בהיפך שהארי' יהי' בהמה טהורה ושור בהמה טמאה אך הנה אף אם יהי' ריבוי רבבות השתל' מדרי' לא הי' אפשר שיומשך מארי' חי' טהורה רק בדרך נפילה ושבירה דוקא ושיהי' חי' טמאה מפני שאין לה לבוש למטה רק חי' טמאה, וככה יובן כשהמלאכים בקשו תורה<sup data-n=\"3932\">35</sup> א\"ל כלום יצה\"ר יש ביניכם<sup data-n=\"3933\">36</sup> ולכאו' והלא לא בקשו תורה בגשמיות אלא ברוחניות שכל הלכה ישנה ברוחניות ג\"כ וכמו קא מפלגי במתיבתא דרקיעא<sup data-n=\"3934\">37</sup> בהרת קדמה לשער לבן כו' ולמעלה אינו שייך בהרת ולא שער לבן, אלא שהוא ברוחניות<sup data-n=\"3935\">38</sup> דצרעת ברוחניות הוא הסתלקות אור אבא<sup data-n=\"3936\">39</sup> והלימוד הוא אם הוא באופן כזה כו', ומה השיב להם כלום יצה\"ר כו' והענין הוא מפני שהתורה היא השפעה פנימיות א\"א שיומשך למטה רק בדבר גשמי להאדם שהוא נתלבש בגוף גשמי כו', רק אחר שלומד תורה בגשמיות ומקיים מצות אז בצאת הנפש מהגוף הוא לומד תורה ברוחניות ומלאכים רק מקשיבים לקולך<sup data-n=\"3937\">40</sup> שמקבלים ע\"י נשמות ודוקא אותן שהיו מלובשים בגופים (וצ\"ע שהרי מבואר במ\"א שהנשמה קודם בואה לגוף היא בג\"ע<sup data-n=\"3938\">41</sup>, וע' בד\"ה וככה בתחילתו<sup data-n=\"3939\">42</sup> ) וזהו ביום חתונתו זו מ\"ת שנמשל לחתונה מפני שתורה היא השפעה עצמיות, ולכן נאמרו דברים פשוטים מפני שתורה הוא מדרי' גבוה אלפך חכ' אלפך בינה<sup data-n=\"3940\">43</sup> לכן נמשך בדברים פשוטים, אף שאלמלא לא אמרה תורה היו עושין כן מצד השכל, ומכשנא' בתורה הוא באו\"א, (מובן מזה שהתורה הוא יחוד פנימי דחו\"ב והנה שרשב\"י שהי' תורתו<sup data-n=\"3941\">44</sup> אומנתו<sup data-n=\"3942\">45</sup> לא הי' מפסיק לתפלה, דתפלה",[["3926","30","<b>דפני ארי' גבוה מפני שור</b>: ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה גור ארי' יהודה פ\"א."],["3927","29","<b>דפני ארי'. . מפני שור. . ימין ושמאל</b>: יחזקאל א, י."],["3928","31","<b>ארי'. . ודורס</b>: ראה חולין מב, א (במשנה). שו\"ע יו\"ד סנ\"ז, ס\"א."],["3929","32","<b>ושור. . קרבן</b>: ויקרא א, ב."],["3930","33","<b>ריח נחוח להוי'</b>: ויקרא א, ט. ראה גם לקו\"ש ויקרא כרך לב ע' 1 ואילך."],["3931","34","<b>ונת\"ל (בד\"ה ביום השמיני עצרת)</b>: נדפס (לעיל בחלק המאמרים) לפני מאמר זה."],["3932","35","<b>כשהמלאכים בקשו תורה</b>: שבת פח, ב."],["3933","36","<b>כלום יצה\"ר יש ביניכם</b>: ראה שם פט, א. מאמרי אדה\"א ויקרא ח\"ב ע' תסט בהערה. אוה\"ת בראשית כרך ג ע' תקסג."],["3934","37","<b>קא מפלגי במתיבתא דרקיע</b>: ראה ב\"מ פו, א. ראה גם לקו\"ש תזריע כרך יב ע' 64 ואילך ובהנסמן שם."],["3935","38","<b>אלא שהוא ברוחניות</b>: ראה גם לקו\"ת ואתחנן ו, ב ואילך. סהמ\"צ להצ\"צ ע' 334. סה\"מ תרל\"ח ע' קמו ובהערה 840."],["3936","39","<b>דצרעת. . הסתלקות אור אבא</b>: ראה זהר תזריע מט, ב (ובביאוה\"ז שם). ע\"ח שער לאה ורחל של\"ח, פ\"ז. לקו\"ת מצורע כד, ג. מאמרי אדה\"ז תקס\"ה ח\"א ע' תכג ואילך. מאמרי אדה\"א ויקרא ח\"ב ע' תנג וע' תעג ואילך. סהמ\"צ להצ\"צ ק, ב ואילך."],["3937","40","<b>מקשיבים לקולך</b>: שה\"ש ח, יג. ראה שהש\"ר שם. זהר ויקרא כב, א. מאמרי אדה\"ז תק\"ע ע' ס. סה\"מ תרל\"ח ע' קמו ואילך. ע' ריט."],["3938","41","<b>שהנשמה. . היא בג\"ע</b>: ראה לקו\"ת במדבר ב, א ובהנסמן במ\"מ לשם. חוקת נו, א."],["3939","42","<b>בד\"ה וככה בתחילתו</b>: תרל\"ז פ\"ו ואילך."],["3940","43","<b>אלפך חכ' אלפך בינה</b>: כנצ\"ל: ואאלפך — איוב לג, ג. שבת קד, א."],["3941","44","<b>שרשב\"י שהי' תורתו אומנתו</b>: שבת יא, א."],["3942","45","<b>אומנתו</b>: ראה לקו\"ש בהר כרך יז ע' 305 הערה 22."]]],[2000480397,"הוא יחוד זו\"נ וכשעוסק בתורה גורם יחוד או\"א<sup data-n=\"3943\">46</sup> הרי בכלל מאתים מנה<sup data-n=\"3944\">47</sup>, וזהו מניחים חיי עולם ועוסקים בחיי שעה<sup data-n=\"3945\">48</sup>, חיי שעה הוא ז\"א<sup data-n=\"3946\">*49</sup>, דשעה מל'<sup data-n=\"3947\">49</sup> וחיי שעה הוא ז\"א, וחיי עולם נמשך מבחי' ע\"ק<sup data-n=\"3948\">50</sup>, וע' בסידור כ' שלק\"ש<sup data-n=\"3949\">*52</sup> הי' מפסיק<sup data-n=\"3950\">51</sup> אף שתורתו אומנתו, וזהו לפי מה שנת' שם שק\"ש הוא יחוד פנימי דחו\"ב, אך לפי מש\"כ דק\"ש הוא יחוד חיצוני דחו\"ב<sup data-n=\"3951\">52</sup> לא הי' צריך להפסיק לק\"ש ג\"כ וצ\"ע).\n<b>ובד\"כ</b> הוא ההפרש בין נשמות למלאכים, דנשמות הם בנים לה' אלקיכם<sup data-n=\"3952\">54</sup>, ה' אלקיכם הוא ז\"א ומל'<sup data-n=\"3953\">55</sup> והו\"ע זיווג גופני ולכן ירדה הנשמה למטה בגוף ונה\"ב, ומלאכים הם מזיווג נשיקין<sup data-n=\"3954\">53</sup> לכן הם רוחנים אף שיש להם גופים וכמ\"ש עושה מלאכיו רוחות<sup data-n=\"3955\">56</sup> משרתיו אש לוהט מ\"מ הם בדקות יותר, ומ\"מ יש מעלה במלאכים על הנשמות שהם רוחנים משא\"כ הנשמה היא גשמי, וצ\"ל שההארה חיצוניות הוא למעלה מהפנימיות, וכמ\"ש בספרי המקובלים דחיצוניות שבמקיף למעלה מפנימיות דאו\"פ<sup data-n=\"3956\">57</sup>, וראי' לזה ממשארז\"ל אבידת אביו ואבידת רבו<sup data-n=\"3957\">58</sup> של רבו קודמת שאביו<sup data-n=\"3958\">59</sup> מביאו לעוה\"ז ורבו שלמדו חכ' מביאו לחיי עוה\"ב, ונת\"ל דהשפעות הטיפה היא השפעה פנימיות והשפעות הרב לתלמיד היא השפעה חיצוניות ומ\"מ של רבו קודמת מפני שלמדו חכ' בחנם<sup data-n=\"3959\">60</sup>, וכן אמרז\"ל יפה שיחתן",[["3943","46","<b>דתפלה הוא יחוד זו\"נ וכשעוסק בתורה גורם יחוד או\"א</b>: ראה סידור שער הק\"ש עג, ג. עה, ב."],["3944","47","<b>בכלל מאתים מנה</b>: ב\"ק עד, א."],["3945","48","<b>מניחים חיי עולם. . שעה</b>: שבת י, א."],["3946","*49","<b>חיי שעה הוא ז\"א</b>: ראה גם סידור שער הק\"ש עה, ב. אוה\"ת ואתחנן כרך ו' ע' ב'רמא. לקמן הנחה ד\"ה אריב\"ל הנהו ך\"ו הודו על יד הערה 37."],["3947","49","<b>דשעה מל'</b>: פע\"ח שער תפילות ר\"ה שכ\"ה, פ\"ג [ירושלים תש\"מ תקעא, א]. סידור שם עה, סע\"א ואילך."],["3948","50","<b>וחיי עולם נמשך מבחי' ע\"ק</b>: ראה גם לקמן הנחה ד\"ה אריב\"ל הנהו ך\"ו הודו ובהערה 39."],["3949","*52","<b>כ' שלק\"ש</b>: תיבת כ' נכתבה בסוף השורה ותיבת שלק\"ש בראש שורה שלאח\"ז."],["3950","51","<b>וע' בסידור כ' שלק\"ש הי' מפסיק</b>: שם עה, ד<sup data-n=\"e284\">א</sup>."],["3951","52","<b>שק\"ש הוא יחוד פנימי דחו\"ב. . חיצוני דחו\"ב</b>: ראה גם לקמן בפנים ובהערה 66."],["3952","54","<b>בנים להוי' אלקיכם</b>: פ' ראה יד, א [ושם: בנים אתם]."],["3953","55","<b>הוי' אלקיכם הוא ז\"א ומל'</b>: ראה גם לקו\"ת שמיני יט, א. סה\"מ תרל\"ג ח\"ב ע' תעא."],["3954","53","<b>נשמות. . זיווג גופני. . ומלאכים הם מזיווג נשיקין</b>: ראה ע\"ח שער מ\"ן ומ\"ד של\"ח, דרוש ד. שער פנימיות וחיצוניות ש\"מ, דרוש י."],["3955","56","<b>עושה מלאכיו רוחות</b>: תהלים קד, ד. ראה לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ואתה תצוה ובהערה 18."],["3956","57","<b>בספרי המקובלים דחיצוניות שבמקיף. . דאו\"פ</b>: ראה גם ע\"ח שער פנימיות וחיצוניות ש\"מ, דרוש ד (קרוב לסופו). ראה גם מאמרי אדה\"ז תקס\"ד ע' קכו<sup data-n=\"e285\">ב</sup>. סה\"מ תרל\"ג ח\"א ע' רסד בשולי היריעהב."],["3957","58","<b>אבידת אביו ואבידת רבו</b>: ראה ב\"מ לג, א. לעיל (בחלק המאמרים) בהמאמר כאן ובהערה 48."],["3958","59","<b>שאביו</b>: בגוכתי\"ק נכפלה תיבה זו."],["3959","60","<b>שלמדו חכ' בחנם</b>: כ\"ה בגוכתי\"ק.\n\n<b>א</b>  בסידור שם שתורתו אומנתו מפסיק לק\"ש — כמו רבי יהודה הנשיא. אבל לא הובא שם בנוגע לרשב\"י. ודעת רשב\"י* — ראה ירושלמי ברכות פ\"א, סה\"ב. שבת פ\"א, סה\"ב. לקו\"ש אבות כרך יז ע' 357 ואילך.\nהובא גם בסה\"מ תרל\"ח ע' רטו. ובהנחת כ\"ק אדמו\"ר מהורש\"ב שם ע' תכב.\n\n<b>ב</b>  בשם הבעש\"ט והמגיד."]]],[2000480398,"של עבדי בתי אבות<sup data-n=\"3960\">61</sup> מתורתן של בנים דבנים הם השפעה פנימיות וכמ\"ש בנים אתם כו' ותורה היא השפעה פנימיות ביום חתונתו כו' ומ\"מ יפה שיחתן שיחה הוא הארה חיצוניות ואפ\"ל שיחת חולין רק דשיחת חולין של ת\"ח ג\"כ צריכים<sup data-n=\"3961\">62</sup> לימוד מפני שההארה חיצוניות היא באו\"א, ולכאו' מפני מה יפה כו' אך הענין הוא דהנה אבות הם כמ\"ש אלקינו ואלקי אבותינו הוא חו\"ב<sup data-n=\"3962\">63</sup> ופעמים נת' עמ\"ש מעבר הנהר ישבו אבותיכם הם חג\"ת דאריך<sup data-n=\"3963\">64</sup> לכן גם ההארה מבחי' זו יפה מתורתן של בנים, וא\"כ יש מעלה בנשמות שהם השפעה פנימיות ויש מעלה במלאכים שהם הארה מבחי' מדרי' גבוה יותר, ועפ\"ז יובן מ\"ש הינוקא חמינא בריחא דלבושייכא דלא קריתון ק\"ש, וא\"ל שעסקו במצות נשואי חו\"כ שהוא השפעה פנימיות ועצמיות, משא\"כ ק\"ש אף שהוא יחוד או\"א מ\"מ הוא יחוד חיצוני דאו\"א (בפ\"א<sup data-n=\"3964\">65</sup> ומ\"ש בסידור שהוא יחוד פנימי דאו\"א<sup data-n=\"3965\">66</sup>, ה\"ז ב' דיעות בקבלה) והם שעסקו במצות נישואי חו\"כ פטורים מק\"ש ומ\"מ א\"ל חמינא בריחא דלבושיכא, לבושים הוא מה שאינו מאיר בפנימיות וריחא הוא ההעלאה<sup data-n=\"3966\">67</sup> מבחי' זו, דלא קריתון ק\"ש דאף שהוא הארה חיצונית מ\"מ ה\"ז ממדרי' גבוה יותר לכן הכיר בהם כו'.\n<b>וזהו</b> מ\"ש הנה אנכי שולח לכם את אלי' הנביא כו' והשיב לב אבות על בנים כי אבות הם חו\"ב והוא הארה חיצוניות לבד והשיב לב אבות על בנים שבאבות שהם הארה חיצוניות מ\"מ יהי' השפעה פנימיות ועצמיות, ולב בנים שהם השפעה פנימיות על אבותם שיהי' ברוחניות ובד\"כ הוא שיהי' פנימיות חו\"ב וברוחניות, ודוקא אלי' יכול לפעול את זאת בנשמות, דאלי' הי' תחילה נשמה בגוף וא\"כ הי' מבחי' השפעה פנימיות ואח\"כ נזדכך ונעשה מלאך שהוא רוחני, לכן בכוחו לפעול בנש\"י ג\"כ כח זה שיהי' השפעה פנימיות ורוחניות, וזהו לפני בא יום ה' הגדול והנורא היינו לפני ביאת משיח שיזדכך העולם אז ישוב לב אבות כו', ולמה אליהו דוקא זהו שאמרו במדרש ואדם אין כאלי'<sup data-n=\"3967\">68</sup> שהי' אדם של אין אפי' בהיותו ע\"פ",[["3960","61","<b>יפה שיחתן של עבדי בתי אבות</b>: ב\"ר פ\"ס, ח."],["3961","62","<b>דשיחת חולין. . לימוד</b>: סוכה כא, ב. ראה לקו\"ת תצא לו, ג. לז, ב. מאמרי אדה\"א דברים ח\"א ע' ריז. וש\"נ. ח\"ד ע' א'ריט. וש\"נ. תו\"ח בראשית א, ד ובהערה 54."],["3962","63","<b>אלקינו ואלקי אבותינו הוא חו\"ב</b>: ראה תו\"א תולדות יז, סע\"ב. מאמרי אדה\"ז תקס\"ח ח\"א ע' תקטז. תו\"ח תולדות קמב, ב. אוה\"ת תולדות כרך ד ע' 1612 ואילך. וש\"נ. ע' 1626. וש\"נ. ואתחנן כרך ו ע' ב'רסד. וש\"נ. וראה גם פלח הרמון תולדות עו, ב."],["3963","64","<b>מעבר הנהר. . חג\"ת דאריך</b>: יהושע כד, ב [ושם: בעבר]. ראה לקו\"ת בחוקותי מז, א."],["3964","65","<b>בפ\"א</b>: ראה גם לעיל הנחה ד\"ה ואהבת את ה' אלקיך ובהערה 74."],["3965","66","<b>ומ\"ש בסידור שהוא יחוד פנימי דאו\"א</b>: ראה שם שער הק\"ש עג, ג. עה, ג ואילך. ראה גם מאמרי אדה\"ז תקס\"ב ח\"א ע' רצז. מאמרי אדה\"א דרושי חתונה ח\"א ע' קכא ואילך. אוה\"ת ואתחנן ע' רכה<sup data-n=\"e286\">ג</sup>. ש\"ש ע' א'תקמח."],["3966","67","<b>לבושים. . וריחא הוא ההעלאה</b>: ראה גם לעיל (בחלק המאמרים) מאמר ד\"ה ולהבין שרש ענין בחי' מזבח הפנימי על יד הערה 110 ואילך."],["3967","68","<b>כאלי' שהי' אדם של אין</b>: ראה גם לעיל (בחלק המאמרים) בהמאמר כאן על יד הערה 60.\n\n<b>ג</b>  ושם נדפס בע\"ח שער הק\"ש. . בלק\"א פ' וירא. וכנשצ\"ל בפע\"ח. . בלקו\"ת."]]],[2000480399,"האדמה שאז נק' אדם ע\"ש שנברא מן האדמה<sup data-n=\"3968\">69</sup>, הי' ג\"כ בבחי' ביטל שהוא בחי' שם ב\"ן<sup data-n=\"3969\">70</sup> ולכן הי' בעיבור יב\"ח<sup data-n=\"3970\">71</sup> דאלי' נזדכך בחיצוניות יותר ממשה<sup data-n=\"3971\">72</sup>. וזהו וכל שיח השדה כל שיח דברייתו מתי יתבני בי מקדשא מפני שאדם אין כאלי' וכחוני המעגל שאם הי' אלי' הרי הי' פועל בנשמות מ\"ש והשיב לב אבות כו' וחוני המעגל פעל כל רצונו מהקב\"ה<sup data-n=\"3972\">73</sup> והוא מורה על הקירוב וביטל בתכלית לאלקות, ואם הי' אלי' וחוני המעגל כבר הי' נבנה בהמק\"ד אך מפני שאדם אין לכן כל שיח דקריתי<sup data-n=\"3973\">74</sup> מתי יבנה בהמק\"ד וכמו שאנו מבקשים יה\"ר מלפניך כו' שיבנה בהמק\"ד במהרה בימינו ותן חלקינו בתורתך.",[["3968","69","<b>אדם ע\"ש. . האדמה</b>: ב\"ר פי\"ז, ד."],["3969","70","<b>שהוא בחי' שם ב\"ן</b>: ראה פע\"ח שער הק\"ש ש\"ח, פ\"ח. לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 156."],["3970","71","<b>בעיבור יב\"ח</b>: ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה מאמר ד\"ה כנשר יעיר ובהערה 16."],["3971","72","<b>דאלי'. . יותר ממשה</b>: ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 157."],["3972","73","<b>וחוני המעגל. . מהקב\"ה</b>: תענית יט, א."],["3973","74","<b>דקריתי</b>: אוצ\"ל: דברייתו."]]],[2000480400,"<h3>והוא כחתן כו'</h3>\n<b></b><b>אור ליום ד' פ' נח על חתונת רמ\"מ תרמ\"א לפ\"ק</b>\nאור ליום ד' פ' נח\n<b>והוא</b> כחתן<sup data-n=\"3974\">1</sup> כו' וישיש כגבור<sup data-n=\"3975\">2</sup> כו' משמע שהחתן בעצמו שש, וישיש היינו שמשמח אחרים<sup data-n=\"3976\">3</sup> וא\"כ הוא בעצמו א\"צ לשמחו, וצ\"ל והלא ארז\"ל כל הנהנה כו' ואם משמחו<sup data-n=\"3977\">4</sup> כו' הרי צריך שמחה וכן או' בנוסח ש\"ב<sup data-n=\"3978\">5</sup> משמח חתן וכלה, משמח חתן עם הכלה הרי צריך לשמחו ואו' שוש תשיש ששון שייך למקבל.\n<b>והענין</b> דהנה כתיב קנה חכ' כו' קנה בינה<sup data-n=\"3979\">6</sup> חו\"ב היינו תושב\"כ ותושבע\"פ<sup data-n=\"3980\">7</sup> ועי\"ז יבוא לבחי' מ\"ש להנחיל אהבי יש<sup data-n=\"3981\">8</sup>, וענין יש הוא כי אל דיעות",[["3974","1","<b>והוא כחתן</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר ד\"ה זה שנדפס לעיל בחלק המאמרים. וש\"נ.\nבהנחה זו ניתוספו שתי הגהות שנכתבו אח\"כ (בהצילום מגוכתי\"ק נראה שנכתבו בעט), וצויינו להלן מקומם בהערות.\nלע\"ע לא נתברר מי הוא הרמ\"מ.\nמאמר ד\"ה זה שבמאמרי אדמו\"ר מהר\"ש דרושי חתונה ע' קנא הודפס מכאן."],["3975","2","<b>והוא כחתן. . כגבור</b>: תהלים יט, ו [ושם: ישיש]."],["3976","3","<b>וישיש. . בעצמו שש. . שמשמח אחרים</b>: ראה של\"ה לוחות הברית רסו, ב. הובא באוה\"ת ישעי' כרך א רצא, סע\"א."],["3977","4","<b>כל הנהנה כו' ואם משמחו</b>: ראה ברכות ו, ב. ראה גם לקוטי שיחות כרך ו' ע' 107 ואילך."],["3978","5","<b>ש\"ב</b>: שבע ברכות."],["3979","6","<b>קנה חכ' כו' קנה בינה</b>: משלי ד, ז<sup data-n=\"e287\">א</sup> וראה גם פסוק ה."],["3980","7","<b>חו\"ב היינו תושב\"כ ותושבע\"פ</b>: ראה זח\"ב תוספות רעו, ב. תו\"ח בראשית לו, ג ובהערה 37. בא ח\"א צד, ד. וש\"נ."],["3981","8","<b>להנחיל אהבי יש</b>: משלי ח, כא.\n\n<b>א</b>  מהוספת תיבת כו' משמע הכוונה לפסוק זה, וכן הובא כתוב זה (לעיל בחלק המאמרים) בהמאמר כאן על יד הערה 10."]]],[2000480401,"ה'<sup data-n=\"3982\">9</sup>, ד\"ע וד\"ת<sup data-n=\"3983\">10</sup>, ד\"ת הוא בריאה יש מאין שלמטה יש ולמעלה אין, איך שיפורש אין אם הארה או שאינו מושג<sup data-n=\"3984\">11</sup> כו', וד\"ע הוא שלמטה אין ולמעלה יש אמיתי וזהו להנחיל אוהבי יש שבד\"ת יאיר בחי' ד\"ע, וזהו יש פ\"א, והוא ע\"י קנה חכ' קנה בינה ב\"פ קנה כו'<sup data-n=\"3985\">13</sup> עי\"ז להנחיל אוהבי יש<sup data-n=\"3986\">12</sup>, ישיש ב\"פ יש<sup data-n=\"3987\">14</sup>, דהנה ארז\"ל נו\"ן שע\"ב נבראו בעולם<sup data-n=\"3988\">15</sup> ומ\"ט שערים השיג<sup data-n=\"3989\">16</sup> וזהו ותחסרהו מעט מאלקים<sup data-n=\"3990\">17</sup> שאפי' משה שזכה לבינה<sup data-n=\"3991\">18</sup> הי' חסר מעט מאלקים דבינה<sup data-n=\"3992\">19</sup> שלא השיג שער הנו\"ן וזהו\"ע ספה\"ע כתי' תספרו חמשים<sup data-n=\"3993\">20</sup> כו', וסופרים רק מ\"ט יום היינו זפ\"ז שלזה אפשר להגיע ע\"י אתעדל\"ת עבודה בירור המדות אך שער הנו\"ן אינו ע\"י אתעדל\"ת כ\"א ממילא<sup data-n=\"3994\">21</sup> כו' וכן בתורה ארז\"ל ע\"פ אמרת ה' כו' מזוקק שבעתים<sup data-n=\"3995\">22</sup> אר\"י לא כו' אלא מ\"ט פנים טהור ומ\"ט פנים טמא<sup data-n=\"3996\">23</sup> דשער הנו\"ן דבינה למעלה מהשגה, ומשה בעת הסתלקותו זכה לשער הנו\"ן<sup data-n=\"3997\">24</sup> ג\"כ, וזהו לעליונים חכ' נדמה למטה<sup data-n=\"3998\">25</sup> דשער הנו\"ן למטה מחכ' ולתחתונים בינה נדמה למעלה שהוא למעלה מהשגה, וכשם שבבינה יש שער הנו\"ן שאינו מושג כמו\"כ בחכ'<sup data-n=\"3999\">26</sup> יש ל\"ב נת\"ח וכמ\"ש בס\"י<sup data-n=\"4000\">27</sup> בל\"ב נתיבות פליאות כו' ונתיב הל\"ב אינו מושג וכמ\"ש נתיב לא ידעו עיט<sup data-n=\"4001\">28</sup> ולא",[["3982","9","<b>כי אל דיעות ה'</b>: שמואל-א ב, ג."],["3983","10","<b>ד\"ע וד\"ת</b>: ראה מאמרי אדה\"א ויקרא ח\"א ע' רסב. וש\"נ. תו\"ח בראשית יח, ג ובהערה 11. סה\"מ תרל\"ד כאן ע' כח."],["3984","11","<b>אין אם הארה או שאינו מושג</b>: ראה גם סה\"מ תרל\"ב ח\"א ע' עדר. וש\"נ. מאמר ד\"ה אמר ריב\"ל תרל\"ה."],["3985","13","<b>ב\"פ קנה כו'</b>: (לעיל בחלק המאמרים) בהמאמר כאן על יד הערה 11 כותב ב\"פ קנה גימ' יש. וש\"נ."],["3986","12","<b>והוא. . יש</b>: תיבות אלו נרשמו בין השיטין ועה\"ג — ניתוספו אח\"כ — ראה לעיל הערה 1."],["3987","14","<b>ישיש ב\"פ יש</b>: ראה גם לעיל ח\"א (בהנחת כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ישקני מנשיקות פיהו ובהערה 76."],["3988","15","<b>נו\"ן שע\"ב נבראו בעולם</b>: ר\"ה כא, ב. ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה נעשה אדם פ\"ב ובהערה 17."],["3989","16","<b>ומ\"ט שערים השיג</b>: ראה ר\"ה שם."],["3990","17","<b>ותחסרהו מעט מאלקים</b>: תהלים ח, ו. ראה מאמרי אדה\"א במדבר ח\"ב ע' תלד."],["3991","18","<b>משה שזכה לבינה</b>: ראה ר\"ה שם. מאמרי אדה\"ז תקס\"ח ח\"א ע' קפה."],["3992","19","<b>מאלקים דבינה</b>: ראה זהר בהקדמה ב, א. תו\"ח בראשית ח, ב ובהערה 35."],["3993","20","<b>תספרו חמישים</b>: אמור כג, טז."],["3994","21","<b>וסופרים רק מ\"ט יום. . שער הנו\"ן. . ממילא</b>: ראה (לעיל בחלק המאמרים) בהמאמר כאן הערה 21."],["3995","22","<b>בתו'. . אמרת. . מזוקק שבעתים</b>: תהלים יב, ז [ושם: אמרות]. ירושלמי סנהדרין פ\"ד, ה\"ב."],["3996","23","<b>אר\"י. . מ\"ט פנים טהור. . טמא</b>: ראה ירושלמי סנהדרין שם. פס\"ר פ' דעשה\"ד פכ\"א, ו. מאמרי אדה\"א במדבר ח\"א ע' רנ. וש\"נ. תו\"ח בראשית יד, ג ובהערה 40."],["3997","24","<b>ומשה בעת הסתלקותו זכה לשער הנו\"ן</b>: ראה לקו\"ת וס' הליקוטים להאריז\"ל ואתחנן ג, כו. לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח ובהערה 350."],["3998","25","<b>לעליונים. . נדמה למטה</b>: ראה סוטה יד, רע\"א. מאמרי אדה\"ז תקס\"ה ח\"א ע' קפד־ לקו\"ת במדבר יב, א ואילך (בשם המגיד). לעיל ח\"א (בהנחת כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה מזבח אדמה תעשה לי על יד הערה 85."],["3999","26","<b>וכשם שבבינה. . כמו\"כ בחכ'</b>: ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה וזהו שרש ענין יונתי ובהערה 88."],["4000","27","<b>ל\"ב נת\"ח וכמ\"ש בס\"י</b>: פ\"א, מ\"א. ראה גם הנסמן במאמרי אדה\"א בראשית ע' ג."],["4001","28","<b>נתיב לא ידעו עיט</b>: איוב כח, ז. ראה ת\"ז ת\"ל עג, ב. לעיל (בחלק המאמרים) שם ובהערה 92."]]],[2000480402,"שזפתו עין אי', פי' אפי' מלאכים שאומרי' אי' מקום כבודו<sup data-n=\"4002\">29</sup> וכבוד גי' ל\"ב<sup data-n=\"4003\">30</sup>, מ\"מ נתיב הל\"ב אינם משיגים, ויעקב השיג ל\"א נת\"ח<sup data-n=\"4004\">31</sup> וכמ\"ש ויקרא לו אל<sup data-n=\"4005\">32</sup> כו' ל\"א וכלול מיו\"ד היינו ש\"י<sup data-n=\"4006\">33</sup>, בכלל נתיב הל\"ב הוא בחי' מה שפנימי' אבא<sup data-n=\"4007\">35</sup> פני' ע\"י<sup data-n=\"4008\">36</sup>, ושער הנו\"ן דבינה הוא מה שהתגלות עתיק בבינה<sup data-n=\"4009\">37</sup> (ע' בד\"ה ובגפן שלשה שריגים פ\"ו<sup data-n=\"4010\">38</sup> וז\"ל יובל בחולם זהו שער הנו\"ן דבינה שהוא פנימיות בינה שבה התגלות עתיק שהוא עולם התענוג עכ\"ל)<sup data-n=\"4011\">34</sup> אך זהו מחצה מתר\"ך.\n<b>וענין</b> ישיש ב\"פ ש\"י, וצ\"ל ג\"כ<sup data-n=\"4012\">39</sup> לשמחו, והענין דהנה כתי' ע\"כ יעזב איש או\"א חו\"ב<sup data-n=\"4013\">40</sup> דאצי' וכשנמשך למטה לכן צריכים לשמחו, וי\"ל השמחה על ב' אופ'<sup data-n=\"4014\">41</sup> הא', דהנה כתי' חכמות בחוץ תרונה<sup data-n=\"4015\">42</sup> חכמות תרין ח\"ע וח\"ת מל' יר\"ת היורדת<sup data-n=\"4016\">43</sup> למטה עי\"ז תרונה רינה עונג ע\"י מצות מעשיות נמשך מחצה העליון דכתר וזהו ישיש כו', וזהו נוסח הברכה בא\"י אלקינו חו\"ב<sup data-n=\"4017\">44</sup> מלך העולם זו\"ן ועי\"ז ממשיכים מבחי' אשר ענג<sup data-n=\"4018\">45</sup> העליון כתר, וזה\"ע ישיש, ועיקר הפי' דהנה עלית למרום זה משה לקחת מתנות<sup data-n=\"4019\">46</sup> שאינו בערך אתעדל\"ת<sup data-n=\"4020\">47</sup> אך מתנות אין<sup data-n=\"4021\">48</sup> נותנין אלא למי ששוה<sup data-n=\"4022\">49</sup> וזהו\"ע המתנה שנותנין לחתן<sup data-n=\"4023\">50</sup> לאחר הדרשה שאינו בערך הדרשה,",[["4002","29","<b>אי' מקום כבודו</b>: נוסח קדושת כתר."],["4003","30","<b>וכבוד גי' ל\"ב</b>: זהר רע\"מ צו לג, א."],["4004","31","<b>ויעקב השיג ל\"א נת\"ח</b>: ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה וזהו שרש ענין יונתי ובהערה 91."],["4005","32","<b>ויקרא לו אל</b>: וישלח לג, כ."],["4006","33","<b>ל\"א וכלול מיו\"ד היינו ש\"י</b>: ראה גם אוה\"ת בהעלותך ס\"ע תיט. סה\"מ תרל\"ח ע' קצד. וש\"נ. (לעיל בחלק המאמרים) בהמאמר כאן על יד הערה 32."],["4007","35","<b>נתיב הל\"ב. . שפנימי' אבא</b>: ראה גם לקו\"ת בהעלותך לו, ג. (לעיל בחלק המאמרים) מאמר ד\"ה וזהו שרש ענין יונתי ובהערה 96."],["4008","36","<b>שפנימי' אבא פני' ע\"י</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתסה. לקו\"ת נצבים מט, ד. תו\"ח שמות ח\"א כג, א הערה 951."],["4009","37","<b>שהתגלות עתיק בבינה</b>: ראה זהר קרח קעח, ב. מאמרי אדה\"א הנחות תקע\"ז ע' ד. וש\"נ. תו\"ח לך פא, ב. ביאוה\"ז להצ\"צ אחרי ע' שסד."],["4010","38","<b>בד\"ה ובגפן שלשה שריגים פ\"ו</b>: אוה\"ת וישב כרך ה ע' 1808."],["4011","34","<b>בכלל. . עכ\"ל)</b>: כ\"ז נרשם בין השיטין ועה\"ג — ניתוסף אח\"כ — ראה לעיל הערה 1."],["4012","39","<b>ג\"כ</b>: אולי כתוב: מ\"ש."],["4013","40","<b>ע\"כ יעזב איש או\"א חו\"ב</b>: בראשית ב, כד [בדילוג]. ראה ע\"ח שער עתיק שי\"ב, פ\"א. לעיל ח\"א (בחלק ההנחות) הנחה ד\"ה תכון תפלתי קטורת לפניך על יד הערה 50."],["4014","41","<b>אופ'</b>: אופנים."],["4015","42","<b>חכמות בחוץ תרונה</b>: משלי א, כ. ראה זהר תולדות קמא, ב."],["4016","43","<b>מל' יר\"ת </b>[ח\"ת ]<b> היורדת</b>: בהצילום אינו ברור כ\"כ מה נכתב כאן, וכן אולי נרשמו כאן עוד תיבות."],["4017","44","<b>בא\"י אלקינו חו\"ב</b>: ראה גם תו\"א יתרו ע, ב."],["4018","45","<b>אשר ענג</b>: ראה תו\"א תולדות יח, סע\"ב. ויצא כג, ג. שמות נג, ב. מאמרי אדה\"א נ\"ך ריש ע' שכז. וש\"נ."],["4019","46","<b>עלית למרום. . לקחת מתנות</b>: תהלים סח, יט [בדילוג]. ראה שבת פט, א. סה\"מ תרל\"ד כאן ע' כט."],["4020","47","<b>מתנות שאינו בערך אתעדל\"ת</b>: ראה לקו\"ת תזריע כב, א. במדבר ה, א. ואתחנן ב, ד."],["4021","48","<b>אין</b>: אינו ברור. ואולי כתוב אינו."],["4022","49","<b>מתנות אין נותנין אלא למי ששוה</b>: ראה מגילה כו, ב. גיטין נ, ב. ב\"מ טז, א. ב\"ב קנו, א."],["4023","50","<b>המתנה שנותנין לחתן</b>: ראה גם סה\"מ תרל\"ד כאן ע' כט. לעיל ח\"א (בחלק ההנחות) הנחה ד\"ה תכון תפלתי קטורת לפניך על יד הערה 48. לקו\"ת נשא כט, ב. מכתב כ\"א טבת תשי\"ג (אג\"ק מאת כ\"ק אדמו\"ר ח\"ז ס\"ע קיח ואילך)."]]],[2000480403,"והיינו דהדרשה הוא אתעדל\"ת ואח\"כ המתנה היא מחצה העליון דכתר, וזהו והוא כחתן יצא מחופתו היינו המקיף וכמ\"ש כי על כל כבוד חופה<sup data-n=\"4024\">51</sup> שיומשך מהמקיף לפנימי, וזהו חתן הוא רק הארה אך לצורך הולדה בדומה לו נמשך מבחי' ומדרי' שלמעלה יותר ולכן צריכים לשמחו מה שבחי' זו נמשך לעבודת הבירורים, ומזה גופא צ\"ל השמחה מה שנמשך מבחי' זו למטה והוא רק בדרך מתנה, אך כמה שאפשר להגיע ע\"י עבודה צריכים להגיע ואח\"כ נמשך המתנה ותחילה צ\"ל והוא כחתן יוצא מחופתו ואח\"כ ישיש כו'.",[["4024","51","<b>כי על כל כבוד חופה</b>: ישעי' ד, ה."]]],[2000480404,"<h3>ויאמר ה' אל אברם לך לך</h3>\n<b></b><b>בס\"ד ש\"פ לך תאמ\"ר לפ\"ק</b>\nלך\n<b>ויאמר</b> ה' אל אברם לך לך<sup data-n=\"4025\">1</sup> מארצך ממולדתך כו' אל הארץ אשר אראך<sup data-n=\"4026\">2</sup>, ואי' במד' דכשבא לארץ בנה ג' מזבחות<sup data-n=\"4027\">3</sup> א' כשבא עד מקום שכם<sup data-n=\"4028\">4</sup> ושם נא' לה' הנראה אליו<sup data-n=\"4029\">5</sup>, ב' ויעתק ההרה ובנה שם מזבח ושם נא' לה' סתם<sup data-n=\"4030\">6</sup>, ואח\"כ גבי עקידת יצחק לא נז' ה' כלל רק ויבן שם אברהם את המזבח<sup data-n=\"4031\">7</sup> בה' הידיעה, ובכל פ' העקידה לא נז' שם הוי' כ\"א שם אלקים והאלקי' נסה כו' אלקי' יראה לו השה<sup data-n=\"4032\">8</sup>, רק אחר שעקד את יצחק בנו כתי' ויקרא מלאך הוי'<sup data-n=\"4033\">9</sup> כו' רק מלא\"ך ה', וצ\"ל דהנה בזהר איתא דשם אלקים אינו מתרצה ע\"י הקרבן<sup data-n=\"4034\">10</sup> ועיקר הקרבן לשם הוי' וכמ\"ש ריח נחוח לה'<sup data-n=\"4035\">11</sup> וגבי שם אלקי' כתי' זבחי אלקי' רוח נשברה<sup data-n=\"4036\">12</sup> לב נשבר ונדכה<sup data-n=\"4037\">13</sup> אלקים ל\"א תבז\"ה אבל קרבן הוא לשם הוי' וא\"כ למה בפ' העקידה לא נז' כלל שם הוי', והנה נת\"ל בענין אילו של יצחק<sup data-n=\"4038\">14</sup> דאפרו הוא יסוד למזבח הפנימי דאברהם לא ידע",[["4025","1","<b>ויאמר ה' אל אברם לך לך</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר ד\"ה זה שנדפס לעיל בחלק המאמרים. וש\"נ."],["4026","2","<b>ויאמר. . לך לך. . אראך</b>: ר\"פ לך."],["4027","3","<b>ואי' במד'. . ג' מזבחות</b>: לעיל בהמאמר כאן מציין: לב\"ר ספל\"ט ע\"ש. וכנראה כוונתו בתיבות ע\"ש ששם מבואר באופן אחר שהג' מזבחות הם הנזכרים בפ' לך."],["4028","4","<b>א' כשבא עד מקום שכם</b>: לך יב, ו."],["4029","5","<b>לה' הנראה אליו</b>: לך שם, ז."],["4030","6","<b>ב' ויעתק ההרה. . לה' סתם</b>: שם יב, ח. [ועד\"ז במזבח הג' שבב\"ר שם — לך יג, יח]."],["4031","7","<b>ויבן שם אברהם את המזבח</b>: וירא כב, ט."],["4032","8","<b>והאלקי' נסה. . אלקי' יראה לו השה</b>: שם כב, א. ח."],["4033","9","<b>ויקרא מלאך הוי'</b>: שם כב, יא [ושם: אליו מלאך]."],["4034","10","<b>דשם אלקי' אינו מתרצה ע\"י הקרבן</b>: ראה זהר משפטים דק\"ח ע\"א. ויקרא ה, א. (לעיל בחלק המאמרים) מאמר ד\"ה ביום השמיני עצרת ובהערה 17."],["4035","11","<b>ריח נחוח לה'</b>: ויקרא א, ט. ראה גם לקו\"ש ויקרא כרך לב ע' 1 ואילך."],["4036","12","<b>זבחי אלקי' רוח נשברה</b>: תהלים נא, יט. ראה גם אגה\"ת פ\"ז. תניא פי\"ז."],["4037","13","<b>ונדכה</b>: ראה גם (לעיל בחלק המאמרים) המשך יונתי ובהערה 553."],["4038","14","<b>נת\"ל בענין אילו של יצחק</b>: ראה (לעיל בחלק המאמרים) מאמר ד\"ה שובה ישראל. וש\"נ."]]],[2000480405,"מהאיל כלל ואי' בפדר\"א ובילקוט פשט האיל<sup data-n=\"4039\">15</sup> את ידו ונגע בטליתו של א\"א ונת\"ל מהו\"ע טליתו<sup data-n=\"4040\">16</sup> כו' ואח\"כ כשראה אותו אברהם הי' איל זה מקור לכל ואפרו הוא יסוד מזבח הפנימי, וצ\"ל מה שייך הקרבן למזבח הפנימי שהוא להקטיר קטורת<sup data-n=\"4041\">17</sup> ואם הי' אומר על מזבח החיצון שהוא ג\"כ על קרבנות ומעשה אבות סימן לבנים<sup data-n=\"4042\">18</sup> שהוא מקור ע\"ז, אבל מה שייכות יש לו למזבח הפנימי, וצ\"ל תחילה ענין הקרבנות שהם ריח נחוח לה' ונת\"ל איך יש בכח הבהמה לכפר על האדם<sup data-n=\"4043\">19</sup> והיינו מפני דשרש הבהמה מתהו שקדם לתיקון<sup data-n=\"4044\">20</sup> אלא שע\"י שבה\"כ נפל למטה ויש בו ניצוצות דתהו וע\"י הקרבן מעלים הניצוץ לשרשו ומקורו ונעשה מזה שמחה למעלה ומהשמחה נמתקים הדינים<sup data-n=\"4045\">21</sup> (וכמו המלך בעת שמחתו שולח לאסיריו חפשי) והוא כ\"ש מי\"ג מדה\"ר נא' נושא עון ועובר על פשע<sup data-n=\"4046\">22</sup> כ\"ש קרבן שמגיע בבחי' עולם התהו, ומ\"מ צ\"ל איך הוא בכח הבהמה גשמיות להמשיך המשכות כאילו.\n<b>והענין</b> דהנה להקרבן הי' צריכים להאדם ג\"כ דצריכים שהאדם המקריב יקדיש אותו בפה<sup data-n=\"4047\">23</sup>, וצריך שחיטה והקרבת הכהן ושריפה, דהנה בהמה בגימ' ב\"ן<sup data-n=\"4048\">24</sup> ששרשה מש' ב\"ן<sup data-n=\"4049\">25</sup> המתברר ואדם בגימ' מ\"ה<sup data-n=\"4050\">26</sup> ששרשו משם מ\"ה<sup data-n=\"4051\">27</sup> המברר, וכמו בשרש ומקור מ\"ה מברר ב\"ן<sup data-n=\"4052\">28</sup> כמו\"כ למטה אדם שבגימ' מ\"ה מברר את הבהמה שבגימ' ב\"ן לכן צ\"ל תחילה קידוש בפה היינו להעלות אותה כדי שיוכל לבררה ואנו רואין שיש בכח המקיף להעלות וכמו עד\"מ כשזורקין אבן ביד שטבעו ליפול למטה מ\"מ ע\"י הזריקה הוא עולה למעלה והיינו מצד כח המקיף של היד וכ\"ז שלא נפסק כח המקיף של היד הוא עולה למעלה ואח\"כ כשנפסק הכח הוא יורד",[["4039","15","<b>בפדר\"א ובילקוט פשט האיל</b>: ספל\"א. ילקו\"ש וירא כב, יג (רמז קא)."],["4040","16","<b>ונת\"ל מהו\"ע טליתו</b>: ראה (לעיל בחלק המאמרים) מאמר ד\"ה שובה ישראל סביב הערה 54."],["4041","17","<b>למזבח הפנימי שהוא להקטיר קטורת</b>: ראה תצוה ל, א. ז. ח. סהמ\"צ להרמב\"ם מ\"ע כח. רמב\"ם הל' כלי המקדש פ\"א, הי\"א. הל' תמידין ומוספין רפ\"ג."],["4042","18","<b>ומעשה אבות סימן לבנים</b>: ראה תו\"א וישלח כו, רע\"א. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' צא. רמב\"ן לך יב, ו. לקו\"ש תולדות כרך כה ע' 123. וש\"נ."],["4043","19","<b>ונת\"ל איך. . הבהמה לכפר על האדם</b>: ראה (לעיל בחלק המאמרים) מאמר ד\"ה ביום השמיני עצרת אחר הערה 43."],["4044","20","<b>מתהו שקדם לתיקון</b>: ראה תו\"א בשלח סה, ד. לקו\"ת אמור לז, ד. וש\"נ. ראה גם לעיל שם הערה 51."],["4045","21","<b>ומהשמחה נמתקים הדינים</b>: ראה גם תו\"א ח\"ש טו, ד. וארא נז, ד. תו\"ח וארא ח\"א סט, ג ואילך. וש\"נ."],["4046","22","<b>נושא עון ועובר על פשע</b>: מיכה ז, יח."],["4047","23","<b>להקרבן. . יקדיש אותו בפה</b>: ראה רש\"י ותוס' מעילה ח, א (במשנה). (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 19."],["4048","24","<b>בהמה בגימ' ב\"ן</b>: ראה תניא ספמ\"ו. מאמרי אדה\"א ויקרא ח\"א ע' ד. וש\"נ."],["4049","25","<b>מש' ב\"ן</b>: ראה לעיל הנחה ד\"ה לכל תכלה הערה 82."],["4050","26","<b>ואדם בגימ' מ\"ה</b>: ראה ע\"ח שער התיקון ש\"י, פ\"ג. לקו\"ת ושער הפסוקים להאריז\"ל בראשית ג, כ. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקסז ובהנסמן במ\"מ לשם. תו\"ח בראשית ט, א הערה 14."],["4051","27","<b>משם מ\"ה</b>: ראה זהר בהקדמה ד, א ובדרך אמת שם. הנסמן במאמרי אדה\"א נ\"ך ע' עא."],["4052","28","<b>מ\"ה מברר ב\"ן</b>: ראה ע\"ח שער טנת\"א ש\"ה, פ\"א. מאמרי אדה\"א דברים ח\"א ע' ה. וש\"נ. ח\"ב ע' תקעג ואילך. ח\"ד ע' א'ריג ואילך."]]],[2000480406,"למטה, וכח היד אינו נכנס בהאבן בפנימיות רק בדרך מקיף, כמו\"כ ע\"י קידוש בפה הוא ממשיך או\"מ על הבהמה שאו\"מ זה הוא נעלה יותר מאו\"מ של היד ה\"ה מעלה אותה מגשמיותה (דכמו שכח המקיף של היד פועל בהאבן היפוך טבעו שטבעו ליפול למטה והמקיף פועל בו שיעלה למעלה כמו\"כ רוח הבהמה היורדת למטה<sup data-n=\"4053\">29</sup>, וע\"י המקיף הוא מעלה אותו וככה יובן בנה\"ב ג\"כ שטבעו ג\"כ לירד כו' והוא מתעלה ע\"י הקרבן וכמשית\"ל, וע' משנת\"ל (פ' נצבים) בענין הסכירה<sup data-n=\"4054\">30</sup> דכשהמים מתגברים על הסתימה פועלים הילוך בהעצים והעפר ג\"כ שהוא היפך טבעם כו') דאף דשרש הבהמה מתהו שקדם לתיקון מ\"מ ירד למטה ע\"י נפילה ושבירה ומקבלת חיות מק\"נ עד שהוא גרוע יותר מהאדם ולכן הותר שחיטה ונחירת בע\"ח<sup data-n=\"4055\">31</sup> לצורך אכילת מין המדבר, וע\"י או\"מ זה הוא מעלה אותה מגשמיותה כדי שיוכל ליכלל אח\"כ באש של מעלה<sup data-n=\"4056\">32</sup> שהוא עיקר ההקרבה וצ\"ל ע\"י אמצעות הכהן שהוא איש החסד<sup data-n=\"4057\">33</sup> ימין מקרבת<sup data-n=\"4058\">34</sup>, ונכלל באש של מעלה ואי' בזהר דבב\"ר הי' ארי' דאכיל קורבנין<sup data-n=\"4059\">35</sup> דפני ארי' אל הימין הוא ג\"כ בחי' חסד<sup data-n=\"4060\">37</sup> ימין מקרבת ואגב היא לאכללה שמאלא בימינא<sup data-n=\"4061\">38</sup> דשרש הבהמה מפני שור<sup data-n=\"4062\">39</sup> אל השמאל<sup data-n=\"4063\">36</sup> ונכלל בבחי' פני ארי'<sup data-n=\"4064\">40</sup> אל הימין.\n<b>ועוד</b> זאת יש בקרבן דהנה אמרז\"ל ע\"פ ואם האכל יאכל<sup data-n=\"4065\">41</sup> בב' אכילות הכתוב מדבר א' אכילת מזבח והוא בחי' ארי' דאכיל קורבנין ואחת אכילת אדם כהנים אוכלים ובעלים מתכפרים<sup data-n=\"4066\">42</sup>, ואכילת אדם מעורר למעלה ג\"כ אכילת אדם העליון דעל דמות הכסא דמות כמראה אדם והוא בחי' שם מ\"ה וכמ\"ש בת\"ז במא' פתח אלי'<sup data-n=\"4067\">45</sup> באריכות, והוא בירור דמ\"ה וב\"ן<sup data-n=\"4068\">43</sup>, (בפ\"א<sup data-n=\"4069\">46</sup> ונת' במ\"א בד\"ה מזמור",[["4053","29","<b>רוח הבהמה היורדת למטה</b>: ע\"פ קהלת ג, כא."],["4054","30","<b>משנת\"ל (פ' נצבים) בענין הסכירה</b>: ראה גם לעיל הנחה ד\"ה אני לדודי הא' פ' תצא בתחילתו."],["4055","31","<b>הותר שחיטה ונחירת בע\"ח</b>: ראה (לעיל בחלק המאמרים) בהמאמר כאן ובהערות 24-25."],["4056","32","<b>באש של מעלה</b>: יומא כא, ב."],["4057","33","<b>הכהן שהוא איש החסד</b>: ראה זהר נשא קמה, ב. צו כז, א. מאמרי אדה\"א דברים ח\"ג ע' תתעג. וש\"נ."],["4058","34","<b>ימין מקרבת</b>: סוטה מז, א."],["4059","35","<b>ארי' דאכיל קורבנין</b>: ראה זהר בהקדמה ו, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תקלא. וש\"נ. שה\"א עט, ב הערה 13. לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח פ\"ה."],["4060","37","<b>הימין. . חסד</b>: ראה זהר בראשית כו, ב. ת\"ז בהקדמה יז, ב. שער היחוה\"א פ\"ה. אגה\"ק ס\"י."],["4061","38","<b>לאכללה שמאלא בימינא</b>: ראה זהר ר\"פ קרח."],["4062","39","<b>דשרש הבהמה מפני שור</b>: ראה ע\"ח שער קיצור אבי\"ע ש\"נ, פ\"ח. מאמרי אדה\"א שמות ח\"א ע' כח. וש\"נ. סה\"מ תרל\"ח ע' יח. וש\"נ."],["4063","36","<b>דפני ארי' אל הימין. . מפני שור אל השמאל</b>: יחזקאל א, י."],["4064","40","<b>הבהמה. . ונכלל בבחי' פני ארי'</b>: ראה גם סה\"מ תרל\"ח ע' לה."],["4065","41","<b>ואם האכל יאכל</b>: צו ז, יח. זבחים יג, ב. ראה לקו\"ת צו ז, ד ואילך. לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח פ\"ז. וש\"נ."],["4066","42","<b>כהנים אוכלים ובעלים מתכפרים</b>: פסחים נט, ב. רמב\"ם הל' מעשה הקרבנות פ\"י, ה\"א. לעיל שם. וש\"נ."],["4067","45","<b>בת\"ז במא' פתח אלי'</b>: בהקדמה יז, א."],["4068","43","<b>ואכילת אדם. . בירור דמ\"ה וב\"ן</b>: ראה גם ביאוה\"ז בלק קט, ד. סידור שער האלול רכז, ד. תו\"א בשלח סו, א. לקו\"ת אמור לח, ג."],["4069","46","<b>בפ\"א</b>: ראה גם לעיל הנחה ד\"ה ואהבת את ה' אלקיך ובהערה 74."]]],[2000480407,"לתודה (ט\"ל)<sup data-n=\"4070\">47</sup> דאכילת אדם<sup data-n=\"4071\">44</sup> למעלה מאכילת מזבח שהוא בבריאה משא\"כ אכילת אדם הוא בירור מ\"ה וב\"ן באצי'). והעולה שהיא כולה כליל<sup data-n=\"4072\">48</sup> וכן פרים הנשרפים<sup data-n=\"4073\">49</sup> מהו\"ע השריפה, הענין הוא דהנה בכל נברא יש גוף ונפש ולמעלה הוא אור וכלי, ושרש הנפש אפי' נפש האדם ואפי' נה\"א שבאדם הוא מבחי' ממכ\"ע<sup data-n=\"4074\">50</sup> וכ\"ש נפש הבע\"ח ונפש הצומח ונפש הדומם שיש לו ג\"כ נפש<sup data-n=\"4075\">51</sup> הם ממכ\"ע, משא\"כ גוף גשם הדבר אפי' אם יהי' רבבות השתל' מדרי' לא יתהווה הגשמיות מבחי' ממכ\"ע, וגם חוקרים מודים ע\"ז דהתהוות הגשמיות מהרוחניות<sup data-n=\"4076\">53</sup> אין לך בריאה יש מאין גדול מזה, רק שהם סוברים שאותו האין שמהווה היש הוא ממציא מציאות היש, ובאמת אינו כן שלא יש בכח אין זה להמציא אותו כ\"א מבחי' א\"ס הסוכ\"ע<sup data-n=\"4077\">52</sup> שהוא כל יכול וגשמיות ורוחניות שוין קמי' שגם רוחניות אינו תופס מקום וכמ\"ש כחשיכה כאורה<sup data-n=\"4078\">54</sup> בב' כפי\"ן לכן אפשר שיהי' גשמיות ג\"כ (והוא בחי' איהו שמתייחד עם גרמוהי וע' משנת\"ל ד\"ה יפה שעה א' מענין זה דכשכורתים האילן<sup data-n=\"4079\">55</sup> קימו גשמו<sup data-n=\"4080\">56</sup> הוא מבחי' איהו והוא בחי' א\"ס הסוכ\"ע כו') רק שצ\"ל ע\"י בחי' האין המהווה היש (וכמ\"ש באגה\"ק<sup data-n=\"4081\">57</sup> שרק בו וע\"י מהווה מציאות היש וכמ\"ש בד\"ה הנ\"ל<sup data-n=\"4082\">58</sup> ).\n<b>והנה</b> הקרבן הוא גוף הבהמה לכן צריכים שחיטה היינו להפריד ממנו החיות שהוא מבחי' ממכ\"ע, וטעון הזאה דהדם הוא הנפש<sup data-n=\"4083\">59</sup>, ולא שהדם עצמו הוא הנפש רק שהוא הכלי שבו מלובש החיות וא\"כ ה\"ז כלי לבחי' ממכ\"ע לכן צריכים הזאה וכמ\"ש עלה בכבש ופנה לסובב<sup data-n=\"4084\">60</sup> היינו שמעלה הדם לבחי' סוכ\"ע וזהו ובא לו לקרן דרומית מזרחית והוא כעין סחרא למדבחא (זח\"ג דק\"ך ע\"א יעו\"ש) ואח\"כ שורפים אותה, דאף שגוף הגשם הוא מסוכ\"ע מ\"מ גידולה מקטנות לגדלות דכשהוא קטן נק' עגל וכשמתגדל ונק' שור פר הרי גידולו הוא מהנפש המחי' אותה ולכן",[["4070","47","<b>בד\"ה מזמור לתודה (ט\"ל) דאכילת אדם</b>: סה\"מ תרל\"ט (נמצא בדפוס). ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 32."],["4071","44","<b>דעל דמות הכסא. . אדם</b>: יחזקאל א, כו."],["4072","48","<b>והעולה שהיא כולה כליל</b>: ויקרא א, ט. רמב\"ם הל' מעשה הקרבנות רפ\"ו."],["4073","49","<b>פרים הנשרפים</b>: משנה זבחים מז, סע\"א."],["4074","50","<b>ושרש הנפש. . ממכ\"ע</b>: ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה ולקחתם לכם רפ\"ג ובהנסמן שם."],["4075","51","<b>הדומם. . נפש</b>: ראה שער היחוד והאמונה פ\"א. אגה\"ק סכ\"ה (קלט, א) בשם האריז\"ל. (לעיל בחלק המאמרים) מאמר ד\"ה והנה כובע ובהערה 58."],["4076","53","<b>חוקרים מודים ע\"ז דהתהוות הגשמיות מהרוחניות</b>: ראה עקרים מ\"א, פכ\"ג. מ\"ד, פ\"ג. תו\"א מג\"א צ, ב. לקו\"ת פ' ראה כ, ד. לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח פ\"ד. וש\"נ."],["4077","52","<b>גוף גשם הדבר. . א\"ס הסוכ\"ע</b>: ראה תו\"א מג\"א צ, ב. סע\"ג. צא, ג. צב, ג ואילך. (לעיל בחלק המאמרים) מאמר ד\"ה סוכה שחמתה מרובה מצלתה ובהערה 25."],["4078","54","<b>כחשיכה כאורה</b>: תהלים קלט, יב. ראה לקו\"ת צו יב, א. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה כי הנה יוצר הרים ובהערה 30."],["4079","55","<b>משנת\"ל ד\"ה יפה שעה א'. . דכשכורתים האילן</b>: הא' (פיסקא וביאור הענין יובן)."],["4080","56","<b>קימו גשמו</b>: אוצ\"ל: קיומו הגשמי."],["4081","57","<b>וכמ\"ש באגה\"ק</b>: ס\"כ."],["4082","58","<b>וכמ\"ש בד\"ה הנ\"ל</b>: שבהערה 55."],["4083","59","<b>דהדם הוא הנפש</b>: פ' ראה יב, כג."],["4084","60","<b>עלה בכבש ופנה לסובב</b>: זבחים נג, רע\"א במשנה. ראה גם (לעיל בחלק המאמרים) בהמאמר כאן הערה 39."]]],[2000480408,"כשבהמה אינה בשלימות בריאותה היא מתנוונה והולכת א\"כ הגידול הוא מבחי' ממכ\"ע<sup data-n=\"4085\">61</sup> לכן צריך שריפה. ועוי\"ל דאף דשרש האדם הוא מתיקון ושרש הבהמה מתהו ולכן ציור האדם הוא שהולך בקומה זקופה וציור הבהמה שהראש והזנב שוים<sup data-n=\"4086\">62</sup> והיינו להורות דשרש האדם מבחי' יושר דתיקון ושרש הבהמה מעיגולים דתהו שמעלה ומטה שוין שם, זהו כלליות הציור מ\"מ מה שיש בה גידים ועצמות והתכלות האברים הוא ע\"ד ציור דתיקון דבתהו אין שם התכללות לכן צריכין שריפה וישאר רק העפר דג' יסודות אמ\"ר יוצאים ונשאר יסוד העפר דהכל הי' מעפר<sup data-n=\"4087\">63</sup> אפי' גלגל חמה דבמח' ארץ קדמה<sup data-n=\"4088\">64</sup>, רק בבריאה שמים קדם לארץ אבל במח' ארץ קדמה לשמים דיסוד העפר שרשו למעלה מכל היסודות, ואפר זה הוא יסוד למזבח הפנימי שהי' אחר מ\"ת דקודם מ\"ת לא הי' מקטירים קטורת, והאבות עשו הכנה למ\"ת<sup data-n=\"4089\">65</sup> ואפרו דאילו של יצחק הי' יסוד למזבח הפנימי.\n<b>והנה</b> עכשיו תפלה במקום קרבנות תקנו<sup data-n=\"4090\">66</sup>, דענין התפלה הוא שפיכת הנפש<sup data-n=\"4091\">67</sup> וכמ\"ש ואשפך נפשי לפני ה'<sup data-n=\"4092\">68</sup> וענין שפיכה אנו מוצאים רק גבי דם<sup data-n=\"4093\">69</sup> כתי' שופך דם האדם באדם<sup data-n=\"4094\">70</sup> וא\"כ תפלה הוא שפיכת הנפש היינו שפיכת הדם וכמו בקרבן עיקר ההקרבה הי' החלב והדם כמו\"כ ענין התפלה שפיכת הדם כנ\"ל, וכמו קרבן הוא ל' קירוב הכחות והשמות<sup data-n=\"4095\">71</sup> למעלה כמו\"כ מתקרב עי\"ז נפש האדם ג\"כ [שהיא ג\"כ ממכ\"ע] וזהו וסמך ידו על ראש העולה<sup data-n=\"4096\">72</sup> ונרצה לו לכפר עליו היינו דע\"י שמתעלה נפש הבהמה יתעלה נפשו ג\"כ, והנה התחלת העבודה בבהמק\"ד הי' תרומת הדשן שהי' בחצות לילה<sup data-n=\"4097\">73</sup> ובעבודה הוא תקון חצות<sup data-n=\"4098\">74</sup> ובקצרה ענין",[["4085","61","<b>גידולו. . הוא מבחי' ממכ\"ע</b>: ראה גם (לעיל שם) בהמאמר כאן."],["4086","62","<b>האדם. . הבהמה שהראש והזנב שוים</b>: ראה גם (לעיל בחלק המאמרים) המשך יונתי פ\"ד. וש\"נ."],["4087","63","<b>דהכל הי' מעפר</b>: קהלת ג, כ."],["4088","64","<b>דבמח' ארץ קדמה</b>: חגיגה יב, א. ראה תו\"א מקץ לב, סע\"ד ואילך. מאמרי אדה\"א ויקרא ח\"א ע' רלא. וש\"נ."],["4089","65","<b>והאבות עשו הכנה למ\"ת</b>: ראה תו\"א לך יא, ג<sup data-n=\"e288\">א</sup>. אוה\"ת לך כ\"ד ע' תרצב."],["4090","66","<b>תפלה במקום קרבנות תקנו</b>: ברכות כו, א-ב. ראה לקו\"ת פינחס עז, ג. מאמרי אדה\"א ויקרא ח\"א ע' ד. וש\"נ. אוה\"ת תשא ע' א'תתפג."],["4091","67","<b>התפלה הוא שפיכת הנפש</b>: ראה פע\"ח בתחלתו. מאמרי אדה\"א דברים ח\"ב ע' תרסט. וש\"נ. סה\"מ תרל\"ח ע' מב ואילך. (לקמן בחלק ההנחות) הנחה ד\"ה שובה ישראל הא' על יד הערה 83."],["4092","68","<b>ואשפך נפשי לפני ה'</b>: שמואל-א א, טו [ושם ואשפך את — ראה גם מאמרי אדה\"א נ\"ך ע' רעג בהערה]."],["4093","69","<b>שפיכה אנו מוצאים רק גבי דם</b>: כ\"ה בגוכתי\"ק."],["4094","70","<b>שופך דם האדם באדם</b>: נח ט, ו."],["4095","71","<b>קרבן. . קירוב הכחות והשמות</b>: ראה בחיי ויקרא א, ט (ע' תא). (וראה גם שם) במדבר ז, י. פינחס כט, יג. דברים א, א. אוה\"ת פינחס ע' א'פז. סה\"מ תרכ\"ז ע' עה. וש\"נ. ע' שנא."],["4096","72","<b>וסמך ידו על ראש העולה</b>: ויקרא א, ד. ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה סמוכים לעד פ\"ג."],["4097","73","<b>תרומת הדשן שהי' בחצות לילה</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 55."],["4098","74","<b>תרומת הדשן. . תקון חצות</b>: ראה גם לעיל שם.\n\n<b>א</b>  הועתק לעיל ח\"א (בחלק המאמרים) המשך מצה זו פכ\"ד.\nושם נדפס אופן רט\"ז. וצ\"ל כבפנים ההערה."]]],[2000480409,"תקון חצות הוא מרירות על הריחוק<sup data-n=\"4099\">75</sup> דכשיתבונן בעוצם ריחוקו מאלקות יתמרמר מזה, אך יזהר שלא יפול בעצבות שהוא היפך המרירות<sup data-n=\"4100\">76</sup> והוא אסקופה הנדרסת<sup data-n=\"4101\">77</sup> לכל העונות דמצד העצבות איז רעכט אלץ, ואח\"כ פ' הקרבנות, וצלה\"ק תחילה ברכת השחר דכד קרא תרנגולתא<sup data-n=\"4102\">78</sup> מברך הנותן לשכוי בינה והיינו מ\"ש חצות לילה אקום להודות לך<sup data-n=\"4103\">79</sup>, ועי\"ז יבא לבחי' קרבן דכל העוסק בתורת עולה<sup data-n=\"4104\">80</sup> כאילו הקריב עולה והיינו שמתקרב קצת, ואח\"כ מתחיל להתפלל הודו לה' קראו בשמו<sup data-n=\"4105\">81</sup> וצ\"ל והלא תיכף כשניער משנתו אומר מודה אני לפניך<sup data-n=\"4106\">82</sup> ומהו אומרו עוד הפעם הודו לה'.\n<b>והענין</b> דהנה מ\"ש מודה אני הוא הודאה כלליות וזהו לפניך שכולל כל הפרטים דכשניער משנתו ה\"ה כקטן שנולד ויותר מזה דקטן שנולד באמצע היום הרי יש גדולים להרגיל ולאמן (בפ\"א מל' כאשר ישא האומן<sup data-n=\"4107\">83</sup> כו') אותו אבל בזמן קימה לכל אדם לא יש כלל מי שיאמן אותו, וזהו מ\"ש המחדש בטובו בכ\"י תמיד<sup data-n=\"4108\">84</sup> מאין ליש ובאמת ל\"ד בכ\"י אלא בכ\"ע ובכל רגע אלא שביום הוא ניכר דלילה זמן החשך וכמ\"ש ויהי ערב ויהי בקר<sup data-n=\"4109\">85</sup> דכשמתחיל להאיר ביום ה\"ז כמו תחילת הבריאה וה\"ה כקטן רק הקטן אין לו דעת<sup data-n=\"4110\">86</sup> והאדם יש לו דעת וכמו אדה\"ר כשנוצר הי' לו דעת דכל מה שנברא בשימ\"ב בצביונם נבראו<sup data-n=\"4111\">87</sup>, אך מ\"מ אינו משיג עדיין שום פרטיות לכן הוא אומר מודה אני שהוא הודאה כלליות שמשיג שא\"צ להיות נפרד, ואח\"כ מ\"ש הודו לה' היינו שמשיג דבשם הוי' אינו שייך השגה שהוא הי' הוה ויהי' כא'<sup data-n=\"4112\">88</sup> רק הודאה, וקראו בשמו דבשמו של הוי' היינו (בפ\"א בחי' מל' ) שם אד' שם אלקים<sup data-n=\"4113\">89</sup> שייך קריאה, וה\"ז השגה שמשיג שאינו שייך בו השגה.",[["4099","75","<b>תקון חצות הוא מרירות על הריחוק</b>: ראה גם לעיל שם ובהערה 54."],["4100","76","<b>בעצבות. . המרירות</b>: ראה תניא פל\"א."],["4101","77","<b>אסקופה הנדרסת</b>: ערובין צח, א. ראה גם מאמרי אדה\"א נ\"ך ע' לא ואילך. וש\"נ."],["4102","78","<b>דכד קרא תרנגולתא</b>: ראה ברכות ס, ב."],["4103","79","<b>חצות לילה אקום להודות לך</b>: תהלים קיט, סב."],["4104","80","<b>דכל העוסק בתורת עולה</b>: ראה מנחות קי, א. לקו\"ש מסעי כרך יח ע' 413. וש\"נ. ערב פסח כרך לב ע' 37. וש\"נ."],["4105","81","<b>הודו לה' קראו בשמו</b>: דהי\"א טז, ח. ראה גם המשך תער\"ב ח\"א ע' תריט. מאמר ד\"ה אני לדודי תשט\"ו."],["4106","82","<b>כשניער משנתו אומר מודה אני לפניך</b>: ראה שו\"ע אדה\"ז חאו\"ח מהדו\"ק ס\"א, ס\"ה. מהדו\"ת ס\"א, ס\"ו. סידור אדה\"ז במקומו (נדפס גם בהוספות למהדורת שו\"ע קה\"ת שם). ראה גם המשך תער\"ב שם. ד\"ה אני לדודי שם."],["4107","83","<b>כאשר ישא האומן</b>: בהעלותך יא, יב."],["4108","84","<b>המחדש בטובו בכ\"י תמיד</b>: ברכת יוצר. ראה לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה להבין ענין ר\"ח ובהערה 43."],["4109","85","<b>ויהי ערב ויהי בקר</b>: בראשית א, ה."],["4110","86","<b>הקטן אין לו דעת</b>: ראה חגיגה ב, ב. גיטין כב, סע\"ב. כג, א."],["4111","87","<b>בצביונם נבראו</b>: ר\"ה יא, א. חולין ס, א."],["4112","88","<b>הוי'. . שהוא הי' הוה ויהי' כא'</b>: ראה שער היחוד והאמונה פ\"ז. תו\"ח מקץ ריט, ד הערה 62."],["4113","89","<b>קראו בשמו. . בחי' מל'. . אד'. . אלקים</b>: ראה (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 64 ואילך."]]],[2000480410,"<b>אך</b> קודם הודו לה' כו' צלה\"ק ברכת השחר וכמ\"ש חי חי יודוך<sup data-n=\"4114\">90</sup> שיש ח\"י ברכאן דצלותא<sup data-n=\"4115\">91</sup> וח\"י ברכות דברכת השחר<sup data-n=\"4116\">92</sup> ברוך אתה ה' שמברך לש' הוי' שהוא משיג איך ששם הוי' הוא ל' התהוות<sup data-n=\"4117\">93</sup> הגם שאינו משיג איך הוא הי' הוה ויהי' כא'<sup data-n=\"4118\">94</sup> ואיך נבראו מאיליו וממילא אך זה הוא משיג שההתהוות הוא משם הוי' דואתה מחי' את כולם<sup data-n=\"4119\">95</sup> א\"ת מחי' אלא מהווה<sup data-n=\"4120\">96</sup> שמהווה כל צרכו מאין ליש ולכן הוא מברך לשם הוי', ואח\"כ פ' הקרבנות דכל העוסק בתורת עולה כאילו הקריב עולה, ואח\"כ הוא מתחיל לעלות במעלות וכמ\"ש סולם מוצב ארצה<sup data-n=\"4121\">97</sup> וראשו מגיע השמימה סולם דא צלותא<sup data-n=\"4122\">98</sup>, וראשו מגיע השמימה דהנה יש שמו\"א תתאין ושמו\"א עילאין<sup data-n=\"4123\">99</sup> והשמימה כולל גם שמי השמים<sup data-n=\"4124\">100</sup>, דהנה ישעי' א' שמעו שמים<sup data-n=\"4125\">101</sup> והאזיני ארץ ומשה א' האזינו השמים<sup data-n=\"4126\">102</sup> ותשמע הארץ, דנבואת ישעי' הי' בבריאה<sup data-n=\"4127\">103</sup> ואי' בכהאריז\"ל דכל נבואה הוא מנו\"ה דאצי'<sup data-n=\"4128\">104</sup> לכן שמים וארץ שמדבר משרשו באצי' היינו שמו\"א תתאין ז\"א ומל'<sup data-n=\"4129\">105</sup> דכמו שהשמים מקיף הארץ כמו<sup data-n=\"4130\">*106</sup> המדות מקיפים הדבור<sup data-n=\"4131\">106</sup> ומשה אמר השמים והארץ היינו שמו\"א עילאין דכתי' אתהלך לפני ה' בארצות החיים<sup data-n=\"4132\">107</sup> שיש ב'",[["4114","90","<b>חי חי יודוך</b>: ראה פיוט אמצת עשור [תפלת שחרית ליו\"כ]. שע\"ת מג, א הערה 17. תו\"ח וארא ח\"א נ, רע\"א ובהערה 23."],["4115","91","<b>ח\"י ברכאן דצלותא</b>: זהר בראשית כו, א."],["4116","92","<b>וח\"י ברכות דברכת השחר</b>: ראה גם תו\"ח וארא שם ובהערה 25. סה\"מ תרכ\"ח ריש ע' ע. ע' עח. וראה גם מאמר ד\"ה אני לדודי תשט\"ו."],["4117","93","<b>הוי' הוא ל' התהוות</b>: ראה זהר רע\"מ פינחס רנז, סע\"ב. (לקמן בחלק ההנחות) הנחה ד\"ה ביום השמיני עצרת ובהערה 13."],["4118","94","<b>הי'. . כא'</b>: נסמן לעיל הערה 88."],["4119","95","<b>דואתה מחי' את כולם</b>: נחמי' ט, ו."],["4120","96","<b>א\"ת מחי' אלא מהווה</b>: ראה שער היחוה\"א פ\"ב ובמ\"מ, הגהות והע\"ק שם. הערה בסה\"מ תש\"ד ע' 20."],["4121","97","<b>סולם מוצב ארצה</b>: ויצא כח, יב."],["4122","98","<b>סולם דא צלותא ראה זח\"א בהשמטות רסו, ב. ח\"ג תוספת שו, ב. ת\"ז תמ\"ה פג, א. בסה\"מ תרל\"ו ח\"ב ע' רמד</b>: ואמרו בזהר ובמד\"ר — ראה סה\"מ תרכ\"ז ס\"ע עג: בזהר. . צלותא, ובמדרש. . כבש המזבח. . ובאמת היינו הך, ע\"ש. אוה\"ת ויצא כרך ז ס\"ע תתתכב. ע' 2442."],["4123","99","<b>שמו\"א תתאין ושמו\"א עילאין</b>: באוה\"ת לך כרך ד תשכה סע\"א מציין לזהר ויקהל דרנ\"ו ע\"א. וכנצ\"ל: רט, א."],["4124","100","<b>והשמימה כולל גם שמי השמים</b>: ראה אוה\"ת לך שם ס\"ע תשכו. לעיל (בחלק המאמרים) בהמאמר כאן על יד הערה 91. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה גדולה מילה על יד הערה 22."],["4125","101","<b>ישעי' א' שמעו שמים</b>: ישעי' א, ב."],["4126","102","<b>ומשה א' האזינו השמים</b>: האזינו לב, א. ראה גם לעיל (בחלק המאמרים) בהמאמר כאן על יד הערה 77. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה גדולה מילה על יד הערה 6 ואילך."],["4127","103","<b>דנבואת ישעי' הי' בבריאה</b>: ראה לקו\"ת להאריז\"ל ישעי' פ\"ו. לקוטי הש\"ס להנ\"ל יבמות מט, ב ד\"ה מנשה. תו\"ח בא ח\"א קיד, סע\"ג. וש\"נ. סה\"מ תרמ\"ז ע' קלו. קמב. סה\"מ ליקוט ח\"ג (מאמר ד\"ה בגמ' יבמות. . ע\"פ ואראה תרמ\"ט) ע' ו."],["4128","104","<b>דכל נבואה הוא מנו\"ה דאצי'</b>: ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה משה קבל תורה מסיני בסופה. וש\"נ."],["4129","105","<b>באצי'. . שמו\"א. . ז\"א ומל'</b>: ראה גם לעיל (בחלק המאמרים) בהמאמר כאן ובהערה 81."],["4130","*106","<b>כמו</b>: כ\"ה בגוכתי\"ק."],["4131","106","<b>המדות מקיפים הדבור</b>: ראה גם מאמרי אדמו\"ר הצ\"צ הנחות תרי\"ד ע' ג. סה\"מ תרכ\"ו ס\"ע כו ואילך. תרל\"ח ע' שפד."],["4132","107","<b>אתהלך לפני ה' בארצות החיים</b>: תהלים קטז, ט. ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה גדולה מילה על יד הערה 19. (בחלק המאמרים) המשך מצה זו פ\"ט על יד הערה 258."]]],[2000480411,"ארצות ארץ תתאה מל' וארץ עילאה<sup data-n=\"4133\">108</sup> בינה<sup data-n=\"4134\">109</sup> ושמים הוא חכ'<sup data-n=\"4135\">110</sup> ובמד' יש כמה פי' על שמים שם מים והיינו מי החכ' וכן שמים אש ומים<sup data-n=\"4136\">111</sup> נטל אש ומים ופתכן<sup data-n=\"4137\">112</sup> כו' וי\"ל ג\"כ על חכ' דמים הוא חכ'<sup data-n=\"4138\">113</sup> וכ' החייט שבחכ' יש קצת דין<sup data-n=\"4139\">114</sup> וזהו שי\"ן של אש<sup data-n=\"4140\">115</sup> שיש בתי' שמים והחכ' מקיף את הבינה, ושמי השמים כתר<sup data-n=\"4141\">116</sup> והשמימה כולל שמו\"א תתאין ושמו\"א עילאין וגם שמי השמים, וזהו וראשו של הסולם מגיע השמימה וזהו לבסוף דוקא וכמו בקרבן שהעיקר הוא העפר והוא לבסוף דוקא כמו\"כ מה שבתפלה ראשו מגיע השמימה הוא לבסוף ותחילה הוא מוצב ארצה היינו שמתחיל מדברים קטנים שלא עשני עבד שלא עשני אשה ואח\"כ פ' הקרבנות כו'.\n<b>וכמו</b> בסולם יש ד' שליבות<sup data-n=\"4142\">117</sup> כמו\"כ בתפלה<sup data-n=\"4143\">118</sup> יש ד' מדרי' עד ב\"ש, ופסוד\"ז עד ברכת יוצר, וברכת ק\"ש וק\"ש, ושמ\"ע, ותחלה אומר הודו לה' דבשם ה' אינו שייך רק הודאה, קראו בשמו, בשמו של הוי' שייך קריאה אבל בשם הוי' עצמו רק הודאה, וע\"י ההודאה ה\"ה ממשיך בחי' שם הוי' מאחר שאינו שייך בו רק הודאה,",[["4133","108","<b>בארצות. . ב' ארצות ארץ תתאה. . וארץ עילאה</b>: מובא בשם הזהר במאמרי אדה\"א במדבר ח\"ב ע' תקעא. תו\"ח משפטים ח\"ב רצה, ב."],["4134","109","<b>בארצות. . מל'. . בינה</b>: ראה גם תו\"ח שם רצה, ג. וש\"נ."],["4135","110","<b>ושמים הוא חכ'</b>: ראה אוה\"ת לך שם ע' 1450 ואילך. לעיל (בחלק המאמרים) בהמאמר כאן ובהערה 82."],["4136","111","<b>ובמד'. . שמים שם מים. . אש ומים</b>: ראה חגיגה יב, סע\"א. רש\"י בראשית א, ח. סה\"מ תרל\"ח ע' רטז הערה 19."],["4137","112","<b>נטל אש ומים ופתכן</b>: ראה ב\"ר פ\"ד, ז. חגיגה שם. סה\"מ תרל\"ח ע' ריח הערה 39."],["4138","113","<b>דמים הוא חכ'</b>: ראה תניא פ\"ג ובמ\"מ הגהות והע\"ק שם. תו\"ח בשלח ח\"א קמג, ב ובהערה 91."],["4139","114","<b>וכ' החייט שבחכ' יש קצת דין</b>: ראה תו\"א בראשית ה, ד. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה כי הנה יוצר הרים ובהערה 37."],["4140","115","<b>שי\"ן של אש</b>: ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 1038."],["4141","116","<b>ושמי השמים כתר</b>: ראה (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 89."],["4142","117","<b>בסולם יש ד' שליבות</b>: תנחומא<sup data-n=\"e289\">ב</sup> הובא במו\"נ ח\"ב, פ\"י<sup data-n=\"e290\">ג</sup>. דרשות ר\"י אבן שועיב פ' ויצא ע' ס ד\"ה ועוד אז\"ל. מגלה עמוקות אופן רג. אופן ריז<sup data-n=\"e291\">ד</sup>. מגלה עמוקות עה\"ת מהדו\"ת<sup data-n=\"e292\">ה</sup> פ' ויצא ד\"ה ויצא יעקב ע' סו. שם ע' פה. בהערה הבאה."],["4143","118","<b>בסולם יש ד' שליבות כמו\"כ בתפלה</b>: ראה מגלה עמוקות אופן קצו<sup data-n=\"e293\">ו</sup>. של\"ה חלק תושב\"כ שער השמים פ' ויצא רצא, סע\"ב. לקו\"ת בשלח ב, ב. מאמרי אדה\"א דברים ח\"ב ע' תו ואילך. וש\"נ. שמות ח\"א ע' רמז ואילך. תו\"ח וארא ח\"א עד, ב. וש\"נ. (לעיל בחלק המאמרים) בהמאמר כאן על יד הערה 92. סה\"מ מלוקט א' ע' תיד. לקו\"ש ר\"ה כרך כד ע' 646. וש\"נ. מכתב י\"ט אייר תרצ\"ט נדפס ברשימות חוב' קנח ע' 5.\n\n<b>ב</b>  ראה מבוא לתנחומא באבער פ\"י אות טז ע' 94.\n\n<b>ג</b>  הובא גם בבחיי ויצא עה\"פ [ושם: שדרשו רז\"ל]. רד\"ק ויצא כח, יג ע\"ש.\n\n<b>ד</b>  הובא בילקוט ראובני ויצא כח, יב ד\"ה סוד* (ע' 246).\n\n<b>ה</b>  על השער בשנת גלה מגלה עמוקות תשל\"ח.\n\n<b>ו</b>  ראה ילקוט ראובני ויצא שם ד\"ה תפילה (ע' 244)."]]],[2000480412,"ואח\"כ פסוד\"ז זמרה הוא ל' לזמר עריצים<sup data-n=\"4144\">119</sup> כמו אילן שיש ענפים יבישים או שהתחילו לרקוב צריכים לכרות אותם שלא ימנעו הגידול כמו\"כ כי אדם עץ השדה<sup data-n=\"4145\">120</sup> צריכים לזמר החוחים והקוצים המונעים ומעכבים העלי', ואח\"כ כשנגדל האילן כדבעי אז בברכת ק\"ש הוא התבוננות איך ששרפים אומרים קדוש<sup data-n=\"4146\">121</sup>, ומזכירים את השם אחר ג' תי' ואופנים מזכירים השם אחר ב' תי' ברוך כבוד ה'<sup data-n=\"4147\">122</sup> ואמרז\"ל שאני אופנים שהם מכסא עצמו<sup data-n=\"4148\">123</sup>, ובקצרה ההפרש הוא דשרפים רוצים העולם שמשיגים איך שהוא קדוש ומובדל ורוצים ליכלל ולהבטל בבחי' זו ואופנים הם ברעש גדול והיינו מצד העדר השגה<sup data-n=\"4149\">124</sup> דכשמשיגים אינו שייך רעש רק הרעש הוא מפני שמשיגים שיש איזה דבר ואינם משיגים מה הוא לכן הם מרעישים וה\"ז ע\"ד מ\"ת בוכים<sup data-n=\"4150\">125</sup> אנן בעינן למהוי קדם מלכא לכן בוכים ר\"ת ברוך כבוד ה' ממקומו<sup data-n=\"4151\">126</sup> שממשיכים ממקורו ושרשו<sup data-n=\"4152\">127</sup> והיינו ע\"י הבכי' ולכן מזכירים השם אחר ב' תיבות.\n<b>ומה</b> שייך זה להאדם הענין דהנה לכ\"א מישראל יש ב' נפשות<sup data-n=\"4153\">128</sup> נפה\"א שהוא חלק אלוה ממעל<sup data-n=\"4154\">129</sup> ורוצה ליכלל תמיד כנר בפני אבוקה, ונה\"ב שנק' בהמיות שרשו מפני שור<sup data-n=\"4155\">130</sup> ויש בזה דיעות אם מפני שור שבפני אדם<sup data-n=\"4156\">131</sup> או מפני אדם שבפני שור<sup data-n=\"4157\">132</sup>, ולכן כשמזכירים לו איך ששרשו בטל לאלקות דשרשו משמרי אופנים<sup data-n=\"4158\">133</sup> פועלים בו הזזה שיהי' ג\"כ בטל לאלקות וזהו שמע כו' וברוך שם<sup data-n=\"4159\">134</sup> כו' יחו\"ע",[["4144","119","<b>פסוד\"ז. . לזמר עריצים</b>: ע\"פ ישעי' כה, ה. ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה בן פורת יוסף הא' ובהערה 33."],["4145","120","<b>כי אדם עץ השדה</b>: פ' שופטים כ, יט."],["4146","121","<b>ששרפים אומרים קדוש</b>: ישעי' ו, ג. ברכת יוצר. ראה חולין צא, ב. ובתוד\"ה ברוך (שם צב, רע\"א)."],["4147","122","<b>ואופנים. . ברוך כבוד ה'</b>: יחזקאל ג, יב. ברכת יוצר. ראה חולין צב, רע\"א ובתוד\"ה ברוך. ראה גם סה\"מ תרל\"ד ע' רנד."],["4148","123","<b>ואמרז\"ל שאני אופנים שהם מכסא עצמו</b>: בסה\"מ תרל\"ד שם: רש\"י ז\"ל — חולין צא, סע\"ב ד\"ה והאיכא ברוך."],["4149","124","<b>ההפרש הוא דשרפים. . שמשיגים. . ואופנים. . העדר השגה</b>: ראה לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח פ\"ג."],["4150","125","<b>מ\"ת בוכים</b>: ראה הנסמן לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח פי\"ט הערה 487."],["4151","126","<b>בכי\"ם ר\"ת ברוך כבוד ה' ממקומו</b>: ראה ע\"ח שער הכללים פ\"ב. כנפי יונה ח\"ב, ס\"ב. עשרה מאמרות הובא בשל\"ה תורה שבכתב צאן יוסף ש, ב. עמה\"מ שער קרית ארבע שי\"ד, פ\"ה (פב, א)."],["4152","127","<b>ממקומו. . ממקורו ושרשו</b>: ראה גם לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח ספ\"ז ובהערה 126."],["4153","128","<b>לכ\"א מישראל יש ב' נפשות</b>: ראה תניא פ\"א."],["4154","129","<b>נפה\"א שהוא חלק אלוה ממעל</b>: ראה איוב לא, ב. תניא רפ\"ב. לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 395."],["4155","130","<b>ונה\"ב. . מפני שור</b>: ראה לקו\"ת ויקרא ב, ב. ש\"א יז, א הערה 11. לעיל (בחלק המאמרים) מאמר ד\"ה ולקחתם לכם ובהערה 30."],["4156","131","<b>ונה\"ב. . מפני שור שבפני אדם</b>: ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'רז. וראה גם סה\"מ תרכ\"ט ע' קכח."],["4157","132","<b>ונה\"ב. . מפני אדם שבפני שור</b>: ראה גם שערי אורה ח, א הערה 15. סה\"מ תרל\"ח ע' לט. וש\"נ."],["4158","133","<b>ונה\"ב. . משמרי אופנים</b>: ראה לקו\"ת ויקרא ב, ב. האזינו עד, ג."],["4159","134","<b>שמע כו' וברוך שם</b>: ואתחנן ו, ד. פסחים נו, א."]]],[2000480413,"ויחו\"ת<sup data-n=\"4160\">135</sup> כ\"א לפ\"ע, ואפ\"ל שזהו ג\"כ ההפרש בין נה\"א לנה\"ב דנה\"ב יכול לבוא לביטל היש לאין ונה\"א לביטל האמיתי, ובאמת ביחו\"ת יש ג\"כ מדרי' זו אלא שהוא ברזא דאחד שהוא בהעלם, ואח\"כ בשמ\"ע אומר ברוך אתה ה' שיומשך שם ה' והיינו י\"ב ברכות האמצעיות שאדם שואל צרכיו בהם שיהי' רופא חולים ומברך השנים ריבוי פרנסה בשפע והוא מצוה על ש' ה' והיינו בכח הביטל דק\"ש, ובגמר התפלה אומר שים שלום דהעיקר הוא היחוד שנעשה עי\"ז למעלה ובשים שלום אז גמר ההשפעות הטפה<sup data-n=\"4161\">136</sup>, ואחר התפלה אומר ונפשי כעפר לכל תהי' ולכאו' מה גרוע יותר מעפר והול\"ל<sup data-n=\"4162\">137</sup> להתחיל בזה התפלה, אלא כמו שבקרבן העיקר הוא העפר ומ\"מ צלה\"ק תחילה השחיטה והקרבה והשריפה כמו\"כ ע\"י כל התפלה שמתחיל תחילה מדברים קטנים ואח\"כ הודו לה' כו' ואח\"כ פסוד\"ז לזמר עריצים וברכת ק\"ש הביטל דשרפים ואופנים ועי\"ז הוא הביטל דק\"ש ואח\"כ בשמ\"ע ההמשכה ועי\"ז אחר התפלה אומר ונפשי כעפר לכל תהי' שהוא בחי' אפר וכמו באילו של יצחק האפר הוא יסוד למזבח הפנימי כמו\"כ בעבודה מה שאו' ונפשי כעפר לכל תהי' אפר זה הוא יסוד למזבח הפנימי כו'.\nוהחיות נושאות את הכסא נושאות ומנושאות<sup data-n=\"4163\">138</sup>.",[["4160","135","<b>שמע כו' וברוך שם כו' יחו\"ע ויחו\"ת</b>: זהר בראשית יח, ב. ראה תו\"א ויקהל קטו, ב."],["4161","136","<b>ובשים שלום. . הטפה</b>: ראה פע\"ח שער העמידה ש\"ט, פ\"כ."],["4162","137","<b>והול\"ל</b>: כ\"ה בגוכתי\"ק."],["4163","138","<b>והחיות. . נושאות ומנושאות</b>: ראה בחיי תרומה כה, י בשם הפדר\"א ספ\"ד. הנסמן במאמרי אדה\"א בראשית ע' שעג. מאמרי אדה\"ז תקס\"ד ע' כג. שה\"א ע, א. תו\"ח פקודי ח\"ב תנט, א. וש\"נ."]]],[2000480414,"<h3>ואהבת את ה' אלקיך</h3>\n<b>ש\"פ וירא מ\"א לפ\"ק</b>\n<b>ואהבת</b> את ה' אלקיך<sup data-n=\"4164\">1</sup> בכל לבבך ובכל נפשך ובכל מאדך<sup data-n=\"4165\">2</sup>, ופי' במשנה סוף ברכות בכל לבבך בשני יצריך<sup data-n=\"4166\">3</sup> ובכל נפשך אפי' נוטל<sup data-n=\"4167\">4</sup> ובכל מאדך בכל ממונך, וצ\"ל והלא בכל מאדך<sup data-n=\"4168\">5</sup> הוא ביטל שלא לפי הגבלת הכלים והוא אה\"ר שלמעלה מטו\"ד ומהו ענין בכל ממונך לזה שאפי' אם יפזר ריבוי צדקה ואפי' כל ממונו אינו בערך כלל לגבי האה\"ר, ולפי פי' המשנה מוכרח לומר דהא בהא תליא",[["4164","1","<b>ואהבת את ה' אלקיך</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב — רק שורות אחדות — ממאמר ד\"ה ולהבין שרש ענין בחי' מזבח הפנימי שנדפס לעיל בחלק המאמרים. וש\"נ."],["4165","2","<b>ואהבת את ה'. . ובכל מאדך</b>: ואתחנן ו, ה."],["4166","3","<b>במשנה. . בכל לבבך בשני יצריך</b>: ברכות נד, א. ראה גם לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח ובהערה 18."],["4167","4","<b>נוטל ובכל</b>: בהצילום אינו ברור, ואולי נכתב: נוטל כו' ובכל."],["4168","5","<b>וצ\"ל הלא בכל מאדך</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 102."]]],[2000480415,"דכדי שיבוא לבחי' אה\"ר צלה\"ק תחילה ענין בכל ממונך, ולהבין זה צ\"ל משנת\"ל דאפרו של אילו של יצחק<sup data-n=\"4169\">6</sup> הי' יסוד למזבח הפנימי וצ\"ל מעלת",[["4169","6","<b>משנת\"ל דאפרו של אילו של יצחק</b>: ראה (לעיל בחלק המאמרים) מאמר ד\"ה שובה ישראל ובהערות 12-14."]]],[2000480416,"<h3>עשה צדקה ומשפט</h3>\n<b>ש\"פ חיי תאמ\"ר לפ\"ק</b>\n<b>עשה</b> צדקה ומשפט<sup data-n=\"4170\">1</sup> נבחר לה' מזבח<sup data-n=\"4171\">2</sup> ואמרז\"ל אר\"א גדולה הצדקה יותר מהקרבנות<sup data-n=\"4172\">3</sup> שנא' עשה צדקה ומשפט נבחר לה' מזבח, מזבח פרש\"י<sup data-n=\"4173\">4</sup> חטאת ועולה ואשם ושלמים, וצ\"ל והלא הקרבנות הוא מהמצות הגבוהות שהי' במקדש (בפ\"א<sup data-n=\"4174\">6</sup> והוא מג' עמודים<sup data-n=\"4175\">5</sup> שעליהם העולם עומד) ואיך שייך שהצדקה גדולה מהקרבנות, וע\"פ פשוט אינו מובן כלל אמת שכ\"ה בפסוק שנבחר לה' מזבח מ\"מ צ\"ל טעם הדבר, והנה צלה\"ק תחילה משנת\"ל שהמצות הם נגד עבודת הקטרת<sup data-n=\"4176\">7</sup> שהי' במקדש ועתה בעוה\"ר שאין בהמק\"ד קיים הם מעהמ\"צ בכלל ובפרט מצות צדקה שכולל כל המצות וכמ\"ש וצדקה תהי' לנו<sup data-n=\"4177\">8</sup> כי נשמור לעשות כל המצוה הזאת, וכ\"ה במדרש שכ' דקטרת בגימ' תרי\"ג<sup data-n=\"4178\">9</sup> דאות קו\"ף בא\"ת ב\"ש ג\"ר ד\"ק נתחלף לדלי\"ת ועם ג' אותיות הנשארים טר\"ת עולה מספר תרי\"ג א\"כ מפרשי' ג\"כ שקטרת הו\"ע המצות.\n<b>והענין</b> דהנה בנדבת המשכן [כתי' העשיר לא ירבה<sup data-n=\"4179\">10</sup> והדל לא ימעיט] וגם הי' נדבות גדולות ואי' בילקוט<sup data-n=\"4180\">11</sup> שזהו\"ע כי תשא את ראש בנ\"י<sup data-n=\"4181\">12</sup> נשיאות הראש, והענין דהנה לא כל הנשמה מתלבשת בגוף<sup data-n=\"4182\">13</sup> כ\"א הארה ומקצת וניצוץ קטן",[["4170","1","<b>עשה צדקה ומשפט</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר ד\"ה זה שנדפס לעיל בחלק המאמרים. וש\"נ."],["4171","2","<b>עשה צדקה ומשפט נבחר לה' מזבח</b>: משלי כא, ג."],["4172","3","<b>גדולה הצדקה יותר מהקרבנות</b>: ראה סוכה מט, ב ובר\"ח שם. (לעיל בחלק המאמרים) בהמאמר כאן הערה 3."],["4173","4","<b>פרש\"י</b>: בסוכה שם ד\"ה נבחר בשינוי הסדר."],["4174","6","<b>בפ\"א</b>: ראה גם לעיל הנחה ד\"ה ואהבת את ה' אלקיך הא' ובהערה 74."],["4175","5","<b>הקרבנות. . מג' עמודים</b>: ראה אבות פ\"א, מ\"ב."],["4176","7","<b>משנת\"ל שהמצות הם נגד עבודת הקטרת</b>: ראה (לעיל בחלק המאמרים) מאמר ד\"ה ולהבין שרש ענין בחי' מזבח הפנימי על יד הערה 109 ואילך."],["4177","8","<b>צדקה. . המצות. . וצדקה תהי' לנו</b>: ואתחנן ו, כה [בדילוג]. ראה גם (לעיל בחלק המאמרים) המשך יונתי הערה 27."],["4178","9","<b>במדרש שכ' דקטרת בגימ' תרי\"ג</b>: במד\"ר פי\"ג, טו-טז. רש\"י נשא ז, כ."],["4179","10","<b>העשיר לא ירבה</b>: תשא ל, טו."],["4180","11","<b>ואי' בילקוט</b>: ר\"פ תשא."],["4181","12","<b>כי תשא את ראש בנ\"י</b>: תשא ל, יב. ראה גם סה\"מ תרל\"ח ע' פד."],["4182","13","<b>דלא כל הנשמה מתלבשת בגוף</b>: ראה תו\"א תשא פו, ב. לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 595."]]],[2000480417,"לבד מתלבש בגוף אבל עיקר הנשמה נשארת למעלה ועז\"נ ונוזלים מלבנון<sup data-n=\"4183\">14</sup> אע\"ג דאיהו לא חזי מזליהו חזי<sup data-n=\"4184\">15</sup> שהיא רואה ושומעת כל הכרוזים שמכריזים למעלה ושם גילוי אלקות בבחי' ראי', וב' בחי' אלו בנש\"י נק' יעקב וישראל<sup data-n=\"4185\">16</sup> יעקב הוא יו\"ד עקב<sup data-n=\"4186\">17</sup> היינו ששרשן מיו\"ד וגם מקוש\"י ונמשך בבחי' עקביים אפי' בנשמות דעקבות משיחא<sup data-n=\"4187\">18</sup>, וזהו הנשמה המתלבשת בגוף, וישראל הוא לי ראש<sup data-n=\"4188\">19</sup> הוא שרש ומקור הנשמה, כי תשא את ראש ר\"ל דהנשמה המתלבשת בגוף היא בבחי' רגל לגבי שרש הנשמה וזהו כי תשא את ראש היינו ראש האדם למטה וגם את ראש לחבר עם הראש (את הוא מה שטפל<sup data-n=\"4189\">20</sup> ובטל וכמבואר במ\"א) היינו לחבר הארת הנשמה המתלבשת בגוף עם שרש ומקור הנשמה<sup data-n=\"4190\">21</sup> כמו שהיא למעלה, וכמ\"ש שאו את ראש כל עדת בנ\"י לגולגלתם<sup data-n=\"4191\">22</sup> היינו שיתעלה לבחי' גולגלתא דחפיא על מוחא<sup data-n=\"4192\">23</sup> והוא בחי' מקיף שאינו מאיר בפנימיות, והעלי' הוא ע\"י ונתנו איש כופר נפשו<sup data-n=\"4193\">24</sup> הוא מצות צדקה ונפשו היינו כל נפשו שמתעלה ע\"י צדקה, וזהו שאי' במשנה בכל מאדך בכל ממונך<sup data-n=\"4194\">25</sup> וצ\"ל והלא בכל מאדך הוא אה\"ר שלמעלה מהגבלת הכלי ומה ערך ממון לזה, אך הענין דע\"י צדקה יכולים לבוא לבחי' בכל מאדך שלמעלה מהגבלת הכלים, וזהו וירח ריח בגדיו<sup data-n=\"4195\">26</sup>, בגדיו הם מעשה המצות<sup data-n=\"4196\">27</sup> דכמו הבגד הוא לבוש שהאדם מתכסה בו כמו\"כ מעהמ\"צ הם לבושים להנשמה<sup data-n=\"4197\">28</sup> והלבושים יש להם ריח והו\"ע רוח",[["4183","14","<b>ונוזלים מלבנון</b>: שה\"ש ד, טו [ושם: מן לבנון<sup data-n=\"e294\">א</sup>]. ראה לקו\"ת האזינו עג, א ואילך."],["4184","15","<b>אע\"ג דאיהו לא חזי מזלייהו חזי</b>: מגילה ג, א."],["4185","16","<b>וב' בחי' אלו בנש\"י נק' יעקב וישראל</b>: ראה לקו\"ת דרושים לר\"ה סב, ג. (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 12."],["4186","17","<b>יעקב הוא יו\"ד עקב</b>: ע\"ח שער סדר אצי' ש\"ג, פ\"ב. ראה תו\"א ר\"פ ויצא. מאמרי אדה\"א דברים ח\"ג ע' תתמז. וש\"נ. תו\"ח שמות ח\"א יח, ב. וש\"נ."],["4187","18","<b>דעקבות משיחא</b>: ראה גם לעיל (בחלק המאמרים) מאמר ד\"ה וזהו שרש יונתי הערה 16."],["4188","19","<b>וישראל הוא לי ראש</b>: ראה פע\"ח שער הלולב שכ\"ט, פ\"א. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' צה. שע\"ת צד, ד הערה 26. סה\"מ תרל\"ח ע' קז. וש\"נ."],["4189","20","<b>את מה שהוא טפל</b>: ראה ברכות לו, ב."],["4190","21","<b>לחבר הארת הנשמה. . עם שרש ומקור הנשמה</b>: ראה גם לקו\"ת במדבר א, ב. תצא לו, סע\"א ואילך. שה\"ש יז, א. יח, ד."],["4191","22","<b>שאו. . בנ\"י לגולגלתם</b>: במדבר א, ב [בדילוג]. ראה גם לקו\"ת במדבר א, ב. ד. ב, א. ה, א."],["4192","23","<b>גולגלתא דחפיא על מוחא</b>: ראה זהר אד\"ר נשא קכח, ב."],["4193","24","<b>ונתנו איש כופר נפשו</b>: תשא ל, יב."],["4194","25","<b>שאי' במשנה בכל מאדך בכל ממונך</b>: ראה ואתחנן ו, ה. ברכות נד, א. (לעיל בחלק המאמרים) מאמר ד\"ה ולהבין שרש ענין בחי' מזבח הפנימי ובהערה 102."],["4195","26","<b>וירח ריח בגדיו</b>: תולדות כז, כז [ושם: את ריח<sup data-n=\"e295\">ב</sup>]."],["4196","27","<b>בגדיו הם מעשה המצות</b>: תולדות כז, כז. ראה לקו\"ת מסעי פט, ב. (לעיל בחלק המאמרים) מאמר ד\"ה ולהבין שרש ענין בחי' מזבח הפנימי ובהערה 112."],["4197","28","<b>מעהמ\"צ הם לבושים להנשמה</b>: ראה לעיל שם ובהערה 113.\n\n<b>א</b>  אבל כ\"ה גם לעיל בהנחה ד\"ה ובחודש השביעי הב' על יד הערה 65.\n\n<b>ב</b>  אבל כ\"ה גם במאמרי אדה\"א בראשית ע' קעב. וש\"נ. תו\"ח שמות ח\"א ח, סע\"ב ובהערה 353."]]],[2000480418,"אמשיך רוח ואייתי רוח<sup data-n=\"4198\">29</sup>, דריח ורוח ענינם אחד<sup data-n=\"4199\">30</sup>, והוא ע\"ד הגילוי שיהי' לע\"ל עד יערה עלינו רוח ממרו\"ם<sup data-n=\"4200\">31</sup>.\n<b>והנה</b> נת\"ל דהקטרת הם מסממנים דומם<sup data-n=\"4201\">32</sup> גשמים דוקא כמו\"כ מצות נתלבשו בדברים גשמים דומם, ובמ\"א מבואר שהקטרת הם העלאות האותיות<sup data-n=\"4202\">33</sup> כ\"ה בכהאריז\"ל בכ\"מ, כן מבואר במ\"א בענין המצות שהם העלאות האותיות<sup data-n=\"4203\">34</sup> ועי\"ז נמשך המשכה דמצות הם רוח שהוא אויר אור י'<sup data-n=\"4204\">35</sup> שעי\"ז נמשך בחי' ותורה אור<sup data-n=\"4205\">36</sup>, (בפ\"א וזהו בשמים ראש<sup data-n=\"4206\">37</sup>, בשמים הוא בחי' ריח ועי\"ז הוא נשיאת ראש), ולכן כל הגילוים דלע\"ל נא' בל' צדקה וכמ\"ש וילבש צדקה כשריון<sup data-n=\"4207\">38</sup> וכובע ישועה בראשו, כובע ישועה בראשו הוא בקיצור, תוס' המשכה מא\"ס המאציל העליון ביתר שאת מההמשכה והשפעה בראשית האצי'<sup data-n=\"4208\">39</sup>, וכפי מ\"ש ברמ\"ז מובן יותר שפי' שהם שע\"ה נהורין שנמשכים מחוטמא<sup data-n=\"4209\">40</sup>, ועפ\"ז מובן מה ששייך למ\"ש תחילה וילבש צדקה כשריון שהוא בחי' ריח וכלי הריח הוא החוטם שהוא מקור שע\"ה נהורין לכן ע\"י צדקה נמשך כובע ישועה שע\"ה נהורין, ובמדרש פי' כובע ישועה הוא מצנפת של כה\"ג<sup data-n=\"4210\">41</sup>, וענין המצנפת הוא ג\"כ הארת הכתר<sup data-n=\"4211\">42</sup>, ובד\"כ כובע ישועות הוא תוס' המשכה מעצמיות המאציל במוחין בכלל (בפ\"א וגם בחי' כתר נכלל במוחין) ובד\"פ בבחי' גולגלתא ומו\"ס, דהנה ריח הוא משיב את הנפש<sup data-n=\"4212\">43</sup> דכשנתעלף הרי לפי שעה",[["4198","29","<b>רוח אמשיך רוח ואייתי רוח</b>: ראה זהר תרומה קסב, ריש ע\"ב. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשג. מאמרי אדה\"א בראשית ע' רל. וש\"נ."],["4199","30","<b>דריח ורוח ענינים אחד</b>: ראה גם אוה\"ת חנוכה ח\"ב ריש ע' רפז. (לעיל בחלק המאמרים) בהמאמר כאן על יד הערה 23."],["4200","31","<b>עד יערה עלינו רוח ממרו\"ם</b>: ישעי' לב, טו."],["4201","32","<b>נת\"ל דהקטרת הם מסממנים דומם</b>: ראה (לעיל בחלק המאמרים) מאמר ד\"ה ולהבין שרש ענין בחי' מזבח הפנימי סביבות הערה 109. תו\"א וישב כט, ב. ש\"א יא, א ובהערה 28. סה\"מ תרמ\"ג ע' מו."],["4202","33","<b>שהקטרת הם העלאות האותיות</b>: ראה תו\"א וישב כט, א ואילך. ש\"א ע' 10 ואילך. אוה\"ת הנ\"ל ע' 562."],["4203","34","<b>מבואר במ\"א בענין המצות שהם העלאות האותיות</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן על יד הערה 31 ושם: וע' בת\"א בד\"ה מזוזה מימין וביאורו (ראה שם מקץ מב, ב ואילך. מג, א ואילך) איך ע\"י העלאת האותיות שע\"י קיום המצות נמשך אור החכ'."],["4204","35","<b>אויר אור יו\"ד</b>: ראה גם לעיל הנחה ד\"ה יונתי בחגוי הסלע ובהערה 98."],["4205","36","<b>ותורה אור</b>: משלי ו, כג."],["4206","37","<b>בשמים ראש</b>: תשא ל, כג."],["4207","38","<b>וילבש צדקה כשריון</b>: ישעי' נט, יז."],["4208","39","<b>תוס' המשכה. . האצי'</b>: ראה אגה\"ק סו\"ס ג."],["4209","40","<b>מ\"ש ברמ\"ז. . שע\"ה נהורין שנמשכים מחוטמא</b>: ראה שם בראשית ד, סע\"ב [ושם: בא\"ר ק\"ל<sup data-n=\"e296\">ג</sup> אורכא דחוטמא שע\"ה עלמין<sup data-n=\"e297\">ד</sup>]."],["4210","41","<b>כובע ישועה הוא מצנפת של כה\"ג</b>: ראה שמו\"ר תצוה פל\"ח, ח. (לעיל בחלק המאמרים) בהמאמר כאן ובהערות 47-48."],["4211","42","<b>המצנפת. . הארת הכתר</b>: ראה מאו\"א מערכת מצנפת סקכ\"ח."],["4212","43","<b>ריח הוא משיב את הנפש</b>: ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה ביום השמיני עצרת ובהערה 67.\n\n<b>ג</b>  זהר אד\"ר נשא קל, ע\"ב.\n\n<b>ד</b>  ראה גם בענין שע\"ה נהורין לקמן ובהערה 79. לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח פ\"ז ובהערה 121."]]],[2000480419,"נסתלק הנפש והריח הוא משיב הנפש ותחילת השבת הנפש הוא במוח ואח\"כ מתפשט כו', כמו\"כ יובן למעלה שבחי' ריח נמשך תחלה במוחין כו'.\n<b>וזהו</b> וילבש צדקה כשריון ואמרז\"ל מה השריון הזה<sup data-n=\"4213\">44</sup> כל קשקשת וקשקשת מצטרפת לשריון גדול כמו\"כ צדקה כל פרוטה ופרוטה מצטרפת לחשבון גדול<sup data-n=\"4214\">45</sup>, דהשריון הוא מלא נקבים והקשקשים סותמים הנקבים והו\"ע מ\"ש מגן הוא לכל החוסים בו<sup data-n=\"4215\">46</sup>, דהנה במדר\"ש ע\"פ וישטמוהו בעלי חצים<sup data-n=\"4216\">47</sup> אלו בעלי לה\"ר וכמ\"ש אשר שננו כחרב לשונם<sup data-n=\"4217\">48</sup> דרכו חיצם דבר מר, וכן פי' המפרשים<sup data-n=\"4218\">49</sup> דבכל צרתם לו צר<sup data-n=\"4219\">50</sup> כבי' מתלבש בשריון שהדינין והקטרוגים לא יגעו ברחמי ה', ובכהאריז\"ל<sup data-n=\"4220\">51</sup> פי' ע\"פ ח\"ץ הי' מכותם<sup data-n=\"4221\">52</sup>, שהם צ\"ח קללות הכתובים במשנה תורה ושרשם מפגם הברית, והענין דגבי מעלים עיניו מצדקה כתי' וקרא עליך אל ה'<sup data-n=\"4222\">53</sup> והי' בך חטא, ובגמ' מזהירים על ענין הצדקה, וצ\"ל והלא כל המצות כשמעלים עיניו ה\"ז חטא ולמה דוקא צדקה, והענין דהנה כתיב אין אדם צדיק בארץ אשר יעשה טובה לא יחטא<sup data-n=\"4223\">54</sup>, פי' חטא הוא חסרון וכמ\"ש והייתי אני ובני שלמה חטאים<sup data-n=\"4224\">55</sup>, ופרש\"י חסרים, וכן קולע אל השערה ולא יחטא<sup data-n=\"4225\">56</sup> שאין חסר, וא\"כ פי' יחטיא שחסר, ולכל<sup data-n=\"4226\">57</sup> אדם יכול למצוא בדקות חסרון בנפשו, ואמרז\"ל ג' עבירות אין אדם ניצול בהם בכ\"י<sup data-n=\"4227\">58</sup> הרהורי עבירה ועיון תפלה ואבק לה\"ר, וצדקה מעבר הכתם (בפ\"א דלבד משארז\"ל<sup data-n=\"4228\">59</sup> שע\"י צדקה נתעלה רבוי מהנפש, הנה) דהנה צדקה הוא להחיות רוח שפלים<sup data-n=\"4229\">60</sup> כמו\"כ גורם למעלה ג\"כ להחיות רוח שפלים שהכל כדלים ושפלים נחשבים לגבי א\"ס, וממילא נמשך להחוטא ג\"כ דמה יוכל להיות יותר שפל מהחוטא,",[["4213","44","<b>מה השריון הזה</b>: ראה ב\"ב ט, ב. אוה\"ת ישעי' כרך א ס\"ע רפג ואילך."],["4214","45","<b>כל פרוטה. . לחשבון גדול</b>: ראה גם אגה\"ק ס\"ל. (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 54."],["4215","46","<b>מגן הוא לכל החוסים בו</b>: שמואל-ב כב, לא. תהלים יח, לא."],["4216","47","<b>במדר\"ש ע\"פ וישטמוהו בעלי חצים</b>: ראה ב\"ר פצ\"ח, יט. ויחי מט, כג."],["4217","48","<b>אשר שננו כחרב לשונם</b>: תהלים סד, ד — פסוק זה לא הובא בב\"ר שם."],["4218","49","<b>פי' המפרשים</b>: ראה כלי פז — לר' שמואל לאנייאדו — לישעי' כאן (נט, יז). הועתק לשונו (לעיל בחלק המאמרים) בהמאמר כאן על יד הערה 59."],["4219","50","<b>דבכל צרתם לו צר</b>: ישעי' סג, ט. זהר וירא קכ, ב."],["4220","51","<b>ובכהאריז\"ל</b>: לקו\"ת להאריז\"ל פ' כי תבוא צויין אליו (לעיל בחלק המאמרים) בהמאמר כאן."],["4221","52","<b>חץ הי' מכותם</b>: תהלים סד, ח [ושם: חץ פתאום היו<sup data-n=\"e298\">ה</sup> — וכ\"ה באוה\"ת חנוכה ח\"ב ע' 574]."],["4222","53","<b>וקרא עליך אל ה'</b>: פ' ראה טו, ט. ראה לקו\"ת פ' ראה ל, ג ואילך."],["4223","54","<b>אין אדם. . יחטא</b>: קהלת ז, כ [ושם: אדם אין. . טוב ולא]."],["4224","55","<b>והייתי אני ובני שלמה חטאים</b>: מלכים-א א, כא."],["4225","56","<b>קולע אל השערה ולא יחטא</b>: ס' שופטים כ, טז [בדילוג]."],["4226","57","<b>יחטיא. . ולכל</b>: כ\"ה בגוכתי\"ק."],["4227","58","<b>ג' עבירות. . בכ\"י</b>: ראה ב\"ב קסד, סע\"ב ואילך."],["4228","59","<b>משארז\"ל</b>: מה שאמר רבינו ז\"ל — תניא פל\"ז."],["4229","60","<b>להחיות רוח שפלים</b>: ישעי' נז, טו. ראה גם סה\"מ תרל\"ג ח\"ב ע' תסה ובהנסמן שם.\n\n<b>ה</b>  אבל עד\"ז הובא (גם לעיל בחלק המאמרים) בהמאמר כאן על יד הערה 68."]]],[2000480420,"משא\"כ כשאינו נותן צדקה הרי נשאר הכתם וזה והי' בך חטא ואין הכוונה חטא הצדקה לבד אלא חטא הקדום שלא עבר הכתם ולכן מזהירים על צדקה דבאמת כל המצות צריכים זהירות מ\"מ מזהיר על צדקה יותר שהוא מעביר הכתם.\n<b>וזהו</b> וילבש צדקה כשריון, דהשריון הוא מלא נקבים והקשקשים סותמין הנקבים. ולמעלה צריכים לשניהם דהנקבים הם שיומשך השפעת החסד לעושי רצונו והקשקשים<sup data-n=\"4230\">61</sup> להיות מגן ומחסה שלא יהי' תוס' יניקה לחיצונים, וענין מגן מבואר בזהר שהוא מ\"ש שמש ומגן<sup data-n=\"4231\">62</sup> ה' אלקי'<sup data-n=\"4232\">63</sup> ופי' פרד\"ס<sup data-n=\"4233\">64</sup> שהו\"ע יחוד הוי' אלקי'<sup data-n=\"4234\">65</sup>, ובעבודה הוא מ\"ש ושמרו דרך ה' לעשות צדקה ומשפט<sup data-n=\"4235\">66</sup> דהנה ברה\"ע הי' בשם אלקים וכמ\"ש בראשית ברא אלקי'<sup data-n=\"4236\">67</sup> וזהו ושמרו דרך ה' שיומשך שם הוי' בעולם הוא ע\"י צדקה ומשפט וכמ\"ש משפט וצדקה ביעקב אתה עשית<sup data-n=\"4237\">68</sup>, אתה הוא גילוי<sup data-n=\"4238\">69</sup> דכדי שיהי' גילוי אלקות גם בבחי' יעקב הוא הארת הנשמה המתלבשת בגוף הוא ע\"י משפט וצדקה, דהנה לגבי א\"ס אם חטאת מה תפעל בו ורבו פשעיך מה תעשה לו<sup data-n=\"4239\">70</sup> אם צדקת מה תתן לו ומה<sup data-n=\"4240\">71</sup> מידך יקח דכחשיכה כאורה בב' כפי\"ן<sup data-n=\"4241\">72</sup> שהאור שוה לחשך, שממית בידים תתפש<sup data-n=\"4242\">73</sup> והיא בהיכלי מלך, וצ\"ל משפט שיומשך למקום הראוי דוקא, והוא ע\"י המשפט שעושה בנפשו עי\"ז המשפט למעלה שיומשך למקום הראוי דוקא, ועל ל' החסידות השריון הוא החשמל ששרשו<sup data-n=\"4243\">74</sup> מבינה<sup data-n=\"4244\">75</sup> והוא הפרסה שבין אצי' לבריאה<sup data-n=\"4245\">76</sup>, שיהי' שם אלקים ונו\"ן שע\"ב<sup data-n=\"4246\">77</sup> בבריאה, ובבריאה מעורב טו\"ר<sup data-n=\"4247\">78</sup> ושייך שם מלחמת עמלק שהוא מבעלי חצים לכן צריך שריון, ושרש החשמל",[["4230","61","<b>דהשריון. . דהנקבים. . והקשקשים</b>: ראה גם אוה\"ת ישעי' כרך א ע' רפד."],["4231","62","<b>מגן מבואר בזהר. . שמש ומגן</b>: פקודי רכד, ב. הובא גם באוה\"ת לך (ח\"א ע' עט) כרך ד ע' 1396 ע\"ש."],["4232","63","<b>שמש ומגן ה' אלקי'</b>: תהלים פד, יב."],["4233","64","<b>פרד\"ס</b>: כ\"ה בכ\"מ — ראה סה\"מ תרל\"ח ע' קט הערה 293."],["4234","65","<b>פרד\"ס שהו\"ע יחוד הוי' אלקי'</b>: שער עה\"כ שכ\"ג, פי\"ג. ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 89."],["4235","66","<b>ושמרו דרך ה' לעשות צדקה ומשפט</b>: וירא יח, יט."],["4236","67","<b>בראשית ברא אלקי'</b>: בראשית א, א."],["4237","68","<b>משפט וצדקה ביעקב אתה עשית</b>: תהלים צט, ד. ראה גם (לעיל בחלק המאמרים) המשך יונתי ובהערה 31."],["4238","69","<b>אתה הוא גילוי</b>: ראה גם לעיל שם ובהערה 32."],["4239","70","<b>אם חטאת. . תעשה לו</b>: איוב לה, ו."],["4240","71","<b>אם צדקת. . ומה</b>: איוב לה, ז [ושם: או מה — נסמן לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ויהי בימי אחשורוש הערה 19]."],["4241","72","<b>דכחשיכה כאורה בב' כפי\"ן</b>: תהלים קלט, יב. ראה לקו\"ת צו יב, א. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה כי הנה יוצר הרים ובהערה 30."],["4242","73","<b>שממית בידים תתפש</b>: משלי ל, כח. ראה ב\"ר פס\"ו, ז. עמה\"מ שער עולם התוהו ש\"ו, פמ\"ה. שער קרית ארבע שי\"ד, פ\"ט ופצ\"ח."],["4243","74","<b>השריון. . ששרשו מבינה</b>: ראה (לעיל בחלק המאמרים) בהמאמר כאן על יד הערה 99 מציין בעה\"מ שער עולם הבריאה ספ\"ו."],["4244","75","<b>החשמל ששרשו מבינה</b>: ראה גם (לעיל בחלק המאמרים) המשך מצה זו ובהערה 1483."],["4245","76","<b>הפרסה שבין אצי' לבריאה</b>: ראה ע\"ח שער דרושי נקודות ש\"ח, פ\"ב. לקוטי הש\"ס להאריז\"ל חולין ס, ב ד\"ה לכי ומעטי (כ, ב). הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתפא."],["4246","77","<b>ונו\"ן שע\"ב</b>: ר\"ה כא, ב."],["4247","78","<b>ובבריאה מעורב טו\"ר</b>: בסה\"מ תש\"ח ע' 82 (לענין ק\"נ דבריאה) בהערה מציין: ע\"ח ש' הקליפות פ\"ג<sup data-n=\"e299\">ו</sup>. ועיי\"ש בהקדמה לש' ציור העולמות. בש' סדר אבי\"ע פ\"ד. מבו\"ש ש\"ו ח\"ב פ\"ד ועוד.\n\n<b>ו</b>  הועתק גם באוה\"ת נח כרך ג ע' 1200 ואילך [ושם נדפס: ספ\"ג. וכנראה שצ\"ל: רפ\"ג]."]]],[2000480421,"הוא מבחי' שע\"ה נהורין שהו\"ע כובע ישועה<sup data-n=\"4248\">79</sup> ונת\"ל שהשריון הוא מ\"ש מגן הוא לכל החוסים בו וי\"ל שזהו מ\"ש ותתן לו מגן ישעך<sup data-n=\"4249\">80</sup> שהמגן הוא ישעך בחי' שע\"ה נהורין שהו\"ע כובע ישועה, וכוב\"ע הוא אותיות כ\"ו ע\"ב<sup data-n=\"4250\">81</sup> כ\"ו הוא מספר ש' הוי'<sup data-n=\"4251\">82</sup> ושם ע\"ב<sup data-n=\"4252\">83</sup> בגימ' חסד<sup data-n=\"4253\">84</sup> וא\"כ כובע הוא חסד הוי'<sup data-n=\"4254\">85</sup> והוא חסד דלגאו<sup data-n=\"4255\">86</sup> חסד עילאה<sup data-n=\"4256\">87</sup> בחי' ורב<sup data-n=\"4257\">89</sup> חסד<sup data-n=\"4258\">88</sup> שהוא בלתי בע\"ג ובחי' זו יומשך למטה והוא ע\"י הצדקה.\n<b>וזהו</b> גדולה הצדקה יותר מהקרבנות<sup data-n=\"4259\">90</sup> שנא' עשה צדקה ומשפט נבחר לה' מזבח, וצ\"ל והלא קרבנות יש בו כמה פרטים וכתי' לנטוע שמים וליסוד ארץ וקאי על הקרבנות שריחם עולה לשמים והוא מג' העמודים שעליהם העולם עומד, וזהו\"ע סולם מוצב ארצה<sup data-n=\"4260\">91</sup> וראשו מגיע השמים דהסולם שראה יעקב בעבודה הו\"ע הקרבנות<sup data-n=\"4261\">92</sup> ואיך נא' שהצדקה גדולה מזבח. אך הענין דהנה בצדקה יש ב' מדרי' דהנה ארז\"ל המבזבז על<sup data-n=\"4262\">94</sup> יבזבז יותר מחומש<sup data-n=\"4263\">93</sup> מהריווח וזהו מצות צדקה הוא רק חומש ומדה בינונית הוא מעשר<sup data-n=\"4264\">95</sup> וה\"ז הגבלה חומש ומעשר דוקא, וה\"ז כמו כל",[["4248","79","<b>החשמל. . שע\"ה נהורין. . כובע ישועה</b>: (לעיל בחלק המאמרים) בהמאמר כאן הערה *106 ממאו\"א : ש\"ע נהורין.\nראה גם בענין שע\"ה נהורין לעיל ובהערה 40. לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח פ\"ז ובהערה 121."],["4249","80","<b>ותתן לו מגן ישעך</b>: שמואל-ב כב, לו־ תהלים יח, לו [ושם: לי]."],["4250","81","<b>וכובע הוא אותיות כ\"ו ע\"ב</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן על יד הערה 107."],["4251","82","<b>כ\"ו הוא מספר ש' הוי'</b>: ראה שו\"ע (ואדה\"ז) או\"ח הל' ציצית סכ\"ד, ס\"ה (ס\"ז). לעיל שם הערה 108."],["4252","83","<b>ושם ע\"ב</b>: ראה זהר תרומה קלב, ב. פרדס שער פרטי השמות שכ\"א, פ\"ה. מכתב להרב בראנדט נדפס ברשימות חוברת מא (לפ' אחו\"ק)."],["4253","84","<b>ושם ע\"ב בגימ' חסד</b>: ראה זהר רע\"מ תצא רעו, ב. הקדמת ת\"ז ח, סע\"ב. י, ריש ע\"ב. תכ\"ב סז, א. פרדס שעה\"כ שכ\"ג, פ\"ח מערכת חסד. לקו\"ת להאריז\"ל שמות (ג, ד) עה\"פ וירא ה' כי סר לראות."],["4254","85","<b>חסד הוי'</b>: שמואל-א כ, יד. תהלים לג, ו."],["4255","86","<b>חסד דלגאו</b>: ראה זהר אד\"ר נשא קלג, ב."],["4256","87","<b>חסד עילאה</b>: זהר ויחי ריט, א."],["4257","89","<b>ורב חסד</b>: תשא לד, ו."],["4258","88","<b>חסד עילאה בחי' ורב חסד</b>: ראה זהר אד\"ר שם קמ, ב. אגה\"ק ס\"י."],["4259","90","<b>לנטוע שמים וליסוד ארץ. . הקרבנות</b>: ישעי' נא, טז. ראה ירושלמי תענית פ\"ד, סה\"ב. לקו\"ת במדבר ו, ב. אוה\"ת ויצא ח\"א ע' 430<sup data-n=\"e300\">ז</sup>."],["4260","91","<b>סולם מוצב ארצה</b>: ויצא כח, יב."],["4261","92","<b>דהסולם. . הקרבנות</b>: ראה ב\"ר פס\"ח<sup data-n=\"e301\">ח</sup>, יב."],["4262","94","<b>על</b>: כנשצ\"ל: אל."],["4263","93","<b>המבזבז. . יותר מחומש</b>: כתובות סז, סע\"ב. ראה גם שו\"ע אדה\"ז הל' משא ומתן סקנ\"ו, ס\"ג. אגה\"ת ספ\"ג. אגה\"ק ס\"י. סי\"ג. אג\"ק אדה\"ז ח\"א ע' קלד ואילך. ולאדהצ\"צ שם ע' שכז. לקו\"ש תרומה ח\"א ע' 170. קדושים כרך יז ע' 229 ואילך. בחוקותי כרך כז ע' 217 ואילך. פ' ראה כרך לד ע' 90 ואילך. פינחס כרך לח ע' 111 ואילך. אג\"ק שלו ח\"ו ע' נה. חט\"ז ס\"ע יד."],["4264","95","<b>חומש ומדה בינונית הוא מעשר</b>: ראה שו\"ע יו\"ד רסרמ\"ט. אגה\"ק ס\"י. מאמרי אדה\"א הנחות תקע\"ז ע' ס. סה\"מ תש\"י ע' 177 ובהערה לשם. ראה גם להבא לקמן אגה\"ק הנ\"ל.\n\n<b>ז</b>  נדפס גם באוה\"ת דברים ע' מ. והנחה אחרת שם כרך ו ס\"ע ב'תרא ואילך. ישעי' כרך ג' ע' א'קפח וע' א'קצב.\n\n<b>ח</b>  וכן צ\"ל באוה\"ת ויצא כרך ה' ע' תתלז."]]],[2000480422,"המצות שהם מוגבלים ציצית צ\"ל כמו שהם כפולים ל\"ב חוטים<sup data-n=\"4265\">96</sup> ולא פחות מי\"ב גודלים<sup data-n=\"4266\">97</sup>, ותפילין צ\"ל אצבעיים<sup data-n=\"4267\">98</sup> אך זה אינו מעכב וצ\"ל ד' בתים<sup data-n=\"4268\">99</sup> וזהו מעכב ושיהי' מרובעים<sup data-n=\"4269\">100</sup>, שופר שיעורו טפח<sup data-n=\"4270\">101</sup>, סוכה לא פחות מז\"ט ומשהו<sup data-n=\"4271\">102</sup>, ד\"מ שבלולב יש להם שיעור, לולב צ\"ל ד\"ט<sup data-n=\"4272\">103</sup> והדס ג\"ט<sup data-n=\"4273\">104</sup>, ומקוה שהוא מטהר יש לו שיעור מ' סאה<sup data-n=\"4274\">105</sup> דוקא, הגם דשרש המצות הוא למעלה מהגבלה, אך העיקר הוא המשכת החסד למטה שיומשך חסד הוי' מעולם ועד עולם<sup data-n=\"4275\">106</sup> לכן צ\"ל הגבלה כדי שיוכלו העולמות לקבל, וזהו שארז\"ל אנכי ולא יהי' לך שהם כוללים מ\"ע ומל\"ת<sup data-n=\"4276\">107</sup> מפי הגבור\"ה שמענו<sup data-n=\"4277\">108</sup> וכן תרי\"ג מצות נאמרו למשה<sup data-n=\"4278\">109</sup> מפי הגבור\"ה<sup data-n=\"4279\">110</sup>, וקודם",[["4265","96","<b>ציצית. . ל\"ב חוטים</b>: ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 673. סידור ושו\"ע אדה\"ז שבהערה הבאה. באגה\"ק שם ליתא."],["4266","97","<b>ולא פחות מי\"ב גודלים</b>: ראה שו\"ע אדה\"ז הל' ציצית סי\"א, ס\"ה. סידור אדה\"ז הל' ציצית נדפס גם בהוספות לשו\"ע אדה\"ז שם. לקו\"ת נשא כז, ג. ראה גם שיעורים בספר התניא לאגה\"ק ס\"י ע' 1367 בהערה.\nולהעיר ששני דוגמאות אלו הובאו גם במאמרי אדה\"ז תקס\"ה ח\"ב ע' תרלב (בשינוי)."],["4267","98","<b>ותפילין צ\"ל אצבעיים</b>: ראה שו\"ע אדה\"ז הל' תפילין סל\"ב, סס\"ג. לקו\"ת נשא שם. סה\"מ תרל\"ב ח\"א ע' רמו. סה\"מ קונטרסים ח\"ב ס\"ע 700 ואילך. תרפ\"ט ע' 260<sup data-n=\"e302\">ט</sup>. מאמר ד\"ה פזר נתן ש\"פ וישב תשי\"ח. ראה גם לקו\"ש ואתחנן כרך כט ס\"ע 382<sup data-n=\"e303\">א</sup>. ריש ע' 383<sup data-n=\"e304\">ב</sup>."],["4268","99","<b>ותפילין. . ד' בתים</b>: ראה שו\"ע אדה\"ז שם סל\"ב, ס\"ח. ראה גם סה\"מ תרל\"ב שם. סה\"מ קונטרסים שם ריש ע' שנא. (לעיל בחלק המאמרים) המשך יונתי רפי\"ב. לעיל ח\"א (בחלק ההנחות) הנחה ד\"ה הנה אנכי כורת עמך ברית ובהערה 48. סה\"מ תרל\"ח ע' שח. פרט זה לא הוזכר באגה\"ק שם."],["4269","100","<b>ותפילין. . מרובעים</b>: ראה שו\"ע אדה\"ז הל' תפילין שם, סנ\"ט. לקו\"ת נשא שם. סה\"מ קונטרסים שם. מאמר ד\"ה פזר נתן הנ\"ל. ראה גם שיעורים בספר התניא שם ע' 1368 בהערה."],["4270","101","<b>שופר שיעורו טפח</b>: שו\"ע אדה\"ז הל' שופר סתקפ\"ו, ס\"ו־ סי\"ג. ראה גם לקמן הנחה ד\"ה עטרת תפארת שיבה על יד הערה 123. סה\"מ קונטרסים שם ריש ע' שנא. וראה גם לקוטי לוי יצחק אגרות ע' שנה."],["4271","102","<b>סוכה לא פחות מז\"ט ומשהו</b>: באגה\"ק כאן ז\"ט — וכ\"ה במאמר ד\"ה פזר נתן הנ\"ל. ראה (לעיל בחלק המאמרים) המשך יונתי ובהערה 270. סה\"מ תרל\"ד ע' קמב וע' קצד."],["4272","103","<b>לולב צ\"ל ד\"ט</b>: ראה שו\"ע שבהערה הבאה. הובא גם לקמן הנחה ד\"ה עטרת תפארת שיבה על יד הערה 124. במאמר ד\"ה פזר נתן הנ\"ל."],["4273","104","<b>והדס ג\"ט</b>: שו\"ע אדה\"ז הל' לולב רסתר\"נ. הובא גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה לכל תכלה ראיתי קץ על יד הערה 45. מאמר ד\"ה פזר נתן הנ\"ל. באגה\"ק הנ\"ל ליתא."],["4274","105","<b>ומקוה. . מ' סאה</b>: שו\"ע יו\"ד הל' מקואות רסר\"א. שו\"ע אדה\"ז הל' נט\"י סקנ\"ט, סכ\"א."],["4275","106","<b>חסד הוי' מעולם ועד עולם</b>: תהלים קג, יז [ושם: וחסד — וכ\"ה באגה\"ק כאן (ע' קטז). ס\"ח]."],["4276","107","<b>אנכי ולא יהי'. . מ\"ע ומל\"ת</b>: יתרו כ, ב. ג. ראה זח\"ב (תוספות) רעו, א. (יתרו) צא. א. של\"ה ר\"פ יתרו שטו, ב. תניא רפ\"כ."],["4277","108","<b>אנכי ולא יהי'. . מפי הגבור\"ה שמענו</b>: מכות כד, א. ראה מו\"נ ח\"ב פל\"ג. תניא פ\"כ. אגה\"ק כאן (קיד, ב). תו\"ח וארא ח\"א סט, א הערה 418. סה\"מ תרכ\"ט ע' רכו."],["4278","109","<b>תרי\"ג מצות נאמרו למשה</b>: ראה מכות כג, סע\"ב. כללי המצות לר\"י גיקטיליא מערכת שש מאות [צפת תשנ\"ב ע' 208]. לקו\"ש יתרו כרך כו ס\"ע 424 ואילך. אג\"ק שלו ח\"ג ע' רג."],["4279","110","<b>תרי\"ג. . מפי הגבור\"ה</b>: כ\"ה באגה\"ק כאן קיד, ב בשם חז\"ל.\n\n<b>ט</b>  נדפס גם בסה\"מ תש\"י ע' 273.\n\n<b>א</b>  נדפס גם באג\"ק שלו חי\"ג ע' רנא.\n\n<b>ב</b>  נדפס גם באג\"ק שלו חט\"ו ע' שו."]]],[2000480423,"מ\"ת כתיב וידבר אלקי'<sup data-n=\"4280\">111</sup> שהוא מדת הצמצום<sup data-n=\"4281\">112</sup>, ובמ\"ת הי' גילוי אלקות וכמ\"ש וירד ה' על הר סיני<sup data-n=\"4282\">113</sup>, עמד וביטל הגזירה ואני המתחיל<sup data-n=\"4283\">114</sup> כו', ומהו\"ע הצמצום, אך הצמצום הוא סיבת הגילוי<sup data-n=\"4284\">115</sup> וכמו צמצום שכינתו בין שני בדי ארון<sup data-n=\"4285\">116</sup> הגם דעיקר גילוי השכינה הי' בבהמק\"ד בין שני בדי ארון מ\"מ נא' צמצום כו' והיינו כדי שיהי' גילוי, וזהו מימינו אש דת למו<sup data-n=\"4286\">117</sup>, ומ\"מ שרש המצות הם מבחי' תר\"ך עמודי אור<sup data-n=\"4287\">119</sup> דכתר<sup data-n=\"4288\">118</sup> שלמעלה מהגבלה רק כמו שירדו למטה הם מוגבלים, וכמו\"כ מצות צדקה ירד למטה בהגבלה כמו כל המצות.\n<b>אך</b> מ\"ש וחטאך בצדקה פרוק<sup data-n=\"4289\">120</sup> דצדקה תציל ממות<sup data-n=\"4290\">121</sup> ומאן דנפיל מדרגא איקרי מית<sup data-n=\"4291\">122</sup> ע\"ז לא נתנו חכמים שיעור<sup data-n=\"4292\">123</sup> דמי שחטא הרי עשה מגרעת בקדש דמצות הם אשר קדשנו במצותיו<sup data-n=\"4293\">124</sup> שעי\"ז נמשך בחי' קדש העליון ובהעדר המצוה הרי עשה גרעון בקדש וכ\"ש ע\"י מל\"ת ואינו מועיל מיני' ובי' שה\"ה ג\"כ קדש וצריך להמשיך מבחי' בבע\"ג שיהי' נושא עון ועובר על פשע<sup data-n=\"4294\">125</sup> וזהו ע\"י צדקה בלי שיעור ממשיך מבחי' המקיף שאינו מאיר בפנימיות שיומשך בפנימיות ועי\"ז יתמלא כל הפגמים והגרעון, וזהו במקום שבע\"ת עומדים<sup data-n=\"4295\">126</sup> צ\"ג אינם יכולים לעמוד, שאינם יכולים לעמוד שם כלל, שא\"צ להמשיך בחי' זו רק בע\"ת שחטא צריך להמשיך",[["4280","111","<b>וידבר אלקי'</b>: יתרו כ, א."],["4281","112","<b>אלקי' שהוא מדת הצמצום</b>: ראה שער היחוה\"א רפ\"ו. תו\"ח שמות ח\"א לד, ד. וש\"נ."],["4282","113","<b>וירד ה' על הר סיני</b>: יתרו יט, כ."],["4283","114","<b>עמד וביטל הגזירה ואני המתחיל</b>: ראה שמו\"ר פי\"ב, ג. וראה גם פלח הרמון אמור ע' רפ הערה 81."],["4284","115","<b>הצמצום הוא סיבת הגילוי</b>: ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו פ\"ז ובהנסמן שם."],["4285","116","<b>צמצום שכינתו. . ארון</b>: ראה ב\"ר פ\"ד, ד. מאמרי אדה\"ז תקס\"ג ח\"א ס\"ע שמו ואילך (נו\"א). לקו\"ת אמור לד, ב. הנסמן במאמרי אדה\"א בראשית ע' קכט. שה\"א ז, א ובהערה 12."],["4286","117","<b>מימינו אש דת למו</b>: ברכה לג, ב. ראה שער היחוד והאמונה פ\"ה."],["4287","119","<b>תר\"ך עמודי אור דכתר</b>: ראה לקו\"ת להאריז\"ל חבקוק. מאמרי אדה\"א ויקרא ח\"ב ע' תסא. וש\"נ. תו\"ח בראשית מה, ג הערה 32."],["4288","118","<b>שרש המצות. . דכתר</b>: ראה תניא פמ\"א בהגהה ובמ\"מ הגהות והע\"ק לשם. מאמרי אדה\"א קונטרסים ע' רסג. וש\"נ."],["4289","120","<b>וחטאך בצדקה פרוק</b>: דניאל ד, כד [ושם: וחטיך — ראה גם (לעיל בחלק המאמרים) בהמאמר כאן על יד הערה 81. לקמן הנחה ד\"ה אשריכם זורעי על כל מים על יד הערה 129]."],["4290","121","<b>דצדקה תציל ממות</b>: משלי י, ב. יא, ד."],["4291","122","<b>ומאן דנפיל מדרגא איקרי מית</b>: ראה לקו\"ת חוקת נו, סע\"ד ואילך. לקו\"ש ח\"ש כרך י' ע' 211<sup data-n=\"e305\">ג</sup>. במאמרי אדה\"א דברים ח\"ג ע' תתצד בשם הזהר — ראה זהר אד\"ר נשא קלה, ב הובא בע\"ח שער שביה\"כ ש\"ט, פ\"ב־ מבו\"ש ש\"ב ח\"ב, פ\"ג. ראה גם ב\"ר פצ\"ו, ג: ואין מות אלא לשון השפלה."],["4292","123","<b>לא נתנו חכמים שיעור</b>: ראה אגה\"ק כאן. אגה\"ת ספ\"ג. (לעיל בחלק המאמרים) בהמאמר כאן הערה 153."],["4293","124","<b>אשר קדשנו במצותיו</b>: נוסח ברכת המצות."],["4294","125","<b>נושא עון ועובר על פשע</b>: מיכה ז, יח."],["4295","126","<b>במקום שבע\"ת עומדים</b>: ראה ברכות לד, ב. לקו\"ש נצבים כרך יד ע' 361 וע' 363. תו\"ח שמות ח\"א מא, א. וש\"נ. סה\"מ מלוקט ד' ס\"ע יח.\n\n<b>ג</b>  נדפס גם באג\"ק שלו ח\"ב ע' ד [ושם ע' ג התאריך: בין כסה לעשור, תש\"ה. ועפ\"ז לכאורה צריך לתקן בלקו\"ש שם. כמו\"כ ישנם שינויים קלים]."]]],[2000480424,"מבחי' בבע\"ג, והנה הגם שעיקר התשובה הוא חרטה בלב<sup data-n=\"4296\">127</sup> וע\"י עומק הלב ממשיך מלמעלה ג\"כ בחי' ממעמקים, מ\"מ צ\"ל בעשי' גשמיות למטה ג\"כ וזהו\"ע מעשה הצדקה (בפ\"א והשפעת החסד) וזהו בכל מאדך בכל ממונך ולכאו' אינו בערך כלל לבחי' אה\"ר שלמעלה מהגבלת הכלים, והענין ע\"י מצות צדקה שלא בהגבלה יבוא לבחי' בכל מאדך דפי' מאדך מאד שלך<sup data-n=\"4297\">128</sup> שאינו בערך מאד העליון שבבע\"ג אלא שבחסד ה' עלינו ע\"י מאד האדם נתעורר בחי' מאד העליון שבבע\"ג כמו\"כ ע\"י מצות צדקה בלי הגבלה נמשך מלמעלה בחי' חסד שהוא חס דלי\"ת<sup data-n=\"4298\">129</sup> דלגבי' כולם כדלים, דכולם בחכ' עשית<sup data-n=\"4299\">130</sup> שאפי' חכ' נחשבת לעשי' גשמיות<sup data-n=\"4300\">131</sup> ולית לי' מגרמי' כלום וכולא קמי' כלא חשיב<sup data-n=\"4301\">132</sup>, וכל שיותר קמי' יותר כלא חשיב, וע\"י הצדקה שהוא מרחם על העני נמשך מלמעלה ג\"כ לרחם על דלים שיומשך מבחי' חסד דלגאו ואפ\"ל שהוא בחי' חסד דקשוט<sup data-n=\"4302\">133</sup> שה\"ה בחי' מחי' מתים ברחמים רבים<sup data-n=\"4303\">134</sup> שלמעלה מהארת מי חטאת שהוא רק מטהר ט\"מ<sup data-n=\"4304\">135</sup> אבל הצדקה מחי' מתים.\n<b>וזהו</b> גדולה צדקה יותר מהקרבנות דכתי' עשה צדקה ומשפט נבחר לה' מזבח (בפ\"א דקרבנות שהוא העלאת הנפש ה\"ה רק ברוחניות לבד, אבל צדקה הוא בגשמיות, וגם) דקרבנות הם רק פרט מצוה ונת\"ל ההפרש בין מצות צדקה לשערי מצות<sup data-n=\"4305\">136</sup>, דכל המצות שע\"י מתעלה הנפש, מתעלה רק אותו כח שעושה המצוה אבל מצות שהוא<sup data-n=\"4306\">137</sup> נותן כל יגיעה כמו<sup data-n=\"4307\">138</sup> דבנפשו יביא לחמו<sup data-n=\"4308\">139</sup> ואפי' כשמרויח בלא יגיעה מ\"מ במה שהרויח יכול לקנות דבר שיהנה כל גופו וכשנותן לעני הרי מתעלה כל נפשו לכן גדולה מהקרבנות, אך צ\"ל צדקה ומשפ\"ט, דהנה ביגמדה\"ר<sup data-n=\"4309\">140</sup> כתי' לשארית נחלתו<sup data-n=\"4310\">141</sup> ולא לכל נחלתו למי שמשים עצמו כשריים<sup data-n=\"4311\">142</sup>, אלי' וקוץ בה,",[["4296","127","<b>שעיקר התשובה. . בלב</b>: אגה\"ק כאן קטו, ב. תניא פכ\"ט (לו, ב). לקו\"ת ר\"ה נח, ד ושם: וכמרז\"ל הידוע. ראה הנסמן במ\"מ לשם."],["4297","128","<b>מאדך מאד שלך</b>: ראה גם לעיל ח\"א (בחלק ההנחות) הנחה ד\"ה תכון תפלתי קטורת לפניך ובהערה 30."],["4298","129","<b>חסד שהוא חס דלי\"ת</b>: ראה ת\"ז תכ\"ב סז, ריש ע\"ב. מאמרי אדה\"א שמות ח\"ב ע' תרמג. וש\"נ."],["4299","130","<b>דכולם בחכ' עשית</b>: תהלים קד, כד."],["4300","131","<b>חכ' נחשבת לעשי' גשמיות</b>: ראה תניא פ\"ב בהגהה. לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח פ\"ח ובהערה 142."],["4301","132","<b>וכולא קמי' כלא חשיב</b>: ראה זהר בהקדמה יא, ב. ראשית חכמה שער היראה ש\"א, פ\"ז [ז, רע\"א]. מאמרי אדה\"ז תקס\"ו ע' שמא. מאמרי אדה\"א דברים ח\"ב ע' תרנג."],["4302","133","<b>חסד דקשוט</b>: זהר אד\"ר נשא קלג, ב. ראה לקו\"ת נשא כה, ג. שלח נא, א."],["4303","134","<b>מחי' מתים ברחמים רבים</b>: נוסח שמו\"ע."],["4304","135","<b>מי חטאת. . מטהר ט\"מ</b>: חוקת פי\"ט. ראה גם אגה\"ק סכ\"ח."],["4305","136","<b>ונת\"ל ההפרש. . צדקה לשארי מצות</b>: ראה (לעיל בחלק המאמרים) מאמר ד\"ה ולהבין שרש ענין בחי' מזבח הפנימי על יד הערה 165 ואילך. לעיל על יד הערה 59."],["4306","137","<b>מצות שהוא</b>: אוצ\"ל: מצות צדקה שהוא."],["4307","138","<b>כמו</b>: תיבה זו איננה ברורה בהצילום ואולי כתוב: כפו."],["4308","139","<b>דבנפשו יביא לחמו</b>: פיוט (לימים נוראים) כי כשמך."],["4309","140","<b>ביגמדה\"ר</b>: דמיכה — ראה גם סדר תשליך בסידור אדה\"ז. (לקמן בחלק ההנחות) הנחה ד\"ה ביום השמיני עצרת ובהערה 89."],["4310","141","<b>לשארית נחלתו</b>: מיכה ז, יח."],["4311","142","<b>ולא לכל. . עצמו כשריים</b>: ר\"ה יז סע\"א ואילך. ראה גם (לעיל בחלק המאמרים) בהמאמר כאן הערה 169."]]],[2000480425,"ולכאו' איך שייך דקדוק ביגמה\"ר ודוחיקי' בזה שיש שם ג\"כ דקדוק, אך מה שנק' מכילין דרחמים<sup data-n=\"4312\">143</sup> ה\"ז מדה והגבלה וכדי להסיר הגבלה זו הוא ע\"י המשפט בצדקה, וזהו עשה צדקה ומשפט נבחר לה' מזבח שמצות צדקה במשפט הוא למעלה מזבח וכמשארז\"ל גדולה הצדקה יותר מהקרבנות כו'.\n<b>רחבה</b> מצותך מאד<sup data-n=\"4313\">144</sup> שהמצות הם כלים רחבים לבחי' מאד העליון<sup data-n=\"4314\">145</sup> שבבע\"ג דהמצות בשרשם הם בלתי מוגבלים רק שירדו למטה בהגבלה, ועיקר העבודה שיבוא לבחי' מאד בבע\"ג.\n<b>דנה\"א</b> מצ\"ע א\"צ תיקון<sup data-n=\"4315\">146</sup> ועיקר מה שירד למטה הוא לברר הנה\"ב, והנה\"ב הוא מעלים ומסתיר ומאן דנפיל מדרגא איקרי מית וזהו צדקה תציל ממות שצדקה מציל מזה כו', ולכן גדולה הצדקה כו'.",[["4312","143","<b>שנק' מכילין דרחמים</b>: זהר תרומה קלב, ב."],["4313","144","<b>רחבה מצותך מאד</b>: תהלים קיט, צו."],["4314","145","<b>שהמצות. . מאד העליון</b>: ראה אגה\"ק סי\"ז. וראה גם (לעיל בחלק המאמרים) מאמר ד\"ה והנה כובע בשולי הגליון הד'."],["4315","146","<b>דנה\"א מצ\"ע א\"צ תיקון</b>: ראה תניא פל\"ז (מח, ב). ש\"א ט, א הערה 4."]]],[2000480426,"<h3>אריב\"ל הנהו ך\"ו הודו</h3>\n<b>ש\"פ תולדות מ\"א לפ\"ק</b>\n<b>אריב\"ל</b> הנהו ך\"ו<sup data-n=\"4316\">3</sup> הודו<sup data-n=\"4317\">1</sup> כנגד מי כנגד ך\"ו דורות שברא הקב\"ה בעולמו ולא נתן להם את התורה וזן אותם בחסדו<sup data-n=\"4318\">2</sup>, וצ\"ל והלא דוד הי' זמן רב אחר מ\"ת שהי' בערך תתנ\"ד לאלף הג'<sup data-n=\"4319\">4</sup> ואיך שיאמר<sup data-n=\"4320\">*5</sup> הודו על ך\"ו דור שהיו קודם מ\"ת, וגם צ\"ל דקדוק הגמ' ולא נתן להם תורה וזנם בחסדו מהו\"ע חסדו, ועוד צ\"ל והלא בך\"ו הודו חשיב מה שהי' אחר מ\"ת ואפי' מ\"ש וניער פרעה וחילו<sup data-n=\"4321\">5</sup> בים סוף והעביר ישראל בתוכו<sup data-n=\"4322\">6</sup> הי' ג\"כ לאחר שקבלו איזה מצות דפ' החודש הזה לכם כו' נא' במצרים והקרבן עשו במצרים<sup data-n=\"4323\">7</sup>, ומכ\"ש מ\"ש לסיחון מלך האמורי ולעוג<sup data-n=\"4324\">8</sup> מלך הבשן שהי' זמן רב אחר מ\"ת, ואיך שייך לומר שהוא כנגד ך\"ו דור שהיו קודם מ\"ת.",[["4316","3","<b>ך\"ו הודו</b>: תהלים פרק קלו."],["4317","1","<b>אריב\"ל הנהו ך\"ו הודו</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר ד\"ה ויובן זה עוד ע\"פ מארז\"ל פסחים פרק ע\"פ דקי\"ח א' א\"ר יהושע בן לוי הני ששה ועשרים הודו, שנדפס לעיל בחלק המאמרים. וש\"נ."],["4318","2","<b>הנהו ך\"ו הודו. . וזן אותם בחסדו</b>: ראה פסחים קיח, א."],["4319","4","<b>דוד. . תתנ\"ד לאלף הג'</b>: ראה סדה\"ד שנה זו."],["4320","*5","<b>ואיך שיאמר</b>: כ\"ה בגוכתי\"ק."],["4321","5","<b>וניער פרעה וחילו</b>: תהלים שם, טו."],["4322","6","<b>והעביר ישראל בתוכו</b>: שם קלו, יד. ראה גם (לעיל בחלק המאמרים) בהמאמר כאן הערה 6."],["4323","7","<b>מצות דפ' החודש הזה. . והקרבן עשו במצרים</b>: בא יב, א ואילך."],["4324","8","<b>לסיחון. . ולעוג</b>: תהלים שם, יט-כ. ראה חוקת כא, כא ואילך. דברים ב, כד ואילך. ג, א ואילך."]]],[2000480427,"<b>והענין</b> דהנה בגמ' מחלק שית אלפי שנין<sup data-n=\"4325\">9</sup> על ג' זמנים, והזמן האמצעי הוא ב' אלפי' תורה וקודם זמן זה כפה\"נ מפי<sup data-n=\"4326\">10</sup> הגמ' שהם ב' אלפי' של מדת החסד דהיינו מצד מדת חסדו וטובו השפיע להם ריבוי טוב אף שהיו עו\"כ, ולכן אמרז\"ל מס' עכו\"ם של א\"א הי' ת' פרקי<sup data-n=\"4327\">11</sup> ועתה מס' עכו\"ם שלנו מעט הוא שלא בערך כו' אך שאז רוב האומות היו עו\"כ אומה זו לכוכב זה כו' לכן היו לו בזה ריבוי פרטים, ומ\"מ נמשך להם ריבוי השפעה, דמצד אוא\"ס הרי אם חטאת מה תפעול בו<sup data-n=\"4328\">12</sup> ורבו פשעיך מה תעשה לו אם צדקת מה תתן לו<sup data-n=\"4329\">13</sup> ומה מידך יקח<sup data-n=\"4330\">14</sup> ולכן כמה ארך אפים לפניו<sup data-n=\"4331\">15</sup> אעפ\"י שכל הדורות מכעיסים ובאים ומ\"מ השפיע להם ריבוי טוב (בפ\"א<sup data-n=\"4332\">16</sup> דהנה כתי' הוי' הוי' אל רחום וחנון ארך אפים<sup data-n=\"4333\">17</sup> כו' הרי הוי' הא' מבחי' א\"א<sup data-n=\"4334\">18</sup>, ואותן הדורות נמשך להם ך\"ו המשכת<sup data-n=\"4335\">19</sup> משם הוי' דא\"א) ואח\"כ הם ב' אלפים תורה והתחיל בערך שנת נ\"ב לאברהם<sup data-n=\"4336\">20</sup> היינו שיהי' ההנהגה ע\"פ חכ' התורה (בפ\"א דאורייתא מחכ' נפקת<sup data-n=\"4337\">21</sup> והיינו שיומשך החסד ע\"י החכ', וחכ' יש בה קצת דין<sup data-n=\"4338\">22</sup> וא\"כ נמשך החסד בדקדוק למי שראוי דוקא) שיהי' לפ\"ע העלאת מ\"ן מלמטה כמו\"כ יהי' ההמשכה מלמעלה, וע\"ז כתי' אף ברי יטריח ע\"ב יפיץ ענן אורו<sup data-n=\"4339\">23</sup>, והוא מסיבת מתהפך בתחבולתם לפעלם<sup data-n=\"4340\">24</sup> ואי' בזהר לפעלם דבני נשא<sup data-n=\"4341\">25</sup> וכ\"פ רש\"י והוא מהגמ'<sup data-n=\"4342\">26</sup> אם בתחילת השנה מטיבים מעשיהם ונפסק ריבוי גשמים ואח\"כ נתקלקל ח\"ו לשנות א\"א אלא יורדים במקום הרים ושלא בזמנם, ואם בתחילת השנה קלקלו מעשיהם ונפסק השפעה בצמצום מ\"מ לא יאמר נואש דאין לך דבר שעומד בפני התשובה<sup data-n=\"4343\">27</sup> ויש תשובה שמהפך הגז\"ד לגמרי ואפי' תשובה שאינו מהפך הגז\"ד ומ\"מ ע\"י תשובה יורדי' במקום הראוי ובזמנם, דכשגשמים יורדים בזמנם",[["4325","9","<b>שית אלפי שנין</b>: ראה ע\"ז ט, א."],["4326","10","<b>מפי</b>: אולי כתוב: מפי'."],["4327","11","<b>מס' עכו\"ם של א\"א הי' ת' פרקי</b>: ראה ע\"ז יד, ב. זח\"ב תוספת ערה, סע\"ב. זהר חדש (ס\"ת) יתרו לז, ג."],["4328","12","<b>אם חטאת מה תפעל בו</b>: איוב לה, ו."],["4329","13","<b>אם צדקת מה תתן לו</b>: איוב שם, ז."],["4330","14","<b>ומה מידך יקח</b>: סיום הכתוב אם צדקת [ושם: או מה — ראה לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ויהי בימי אחשורוש הערה 19]."],["4331","15","<b>כמה ארך אפים לפניו</b>: אבות פ\"ה, מ\"ב."],["4332","16","<b>בפ\"א</b>: ראה גם לעיל הנחה ד\"ה ואהבת את ה' אלקיך הא' ובהערה 74."],["4333","17","<b>הוי'. . ארך אפים</b>: תשא לד, ו."],["4334","18","<b>הוי' הא' מבחי' א\"א</b>: ראה לקו\"ת ש\"ש סו, סע\"א."],["4335","19","<b>המשכת</b>: אוצ\"ל: המשכות."],["4336","20","<b>ב' אלפים תורה. . נ\"ב לאברהם</b>: ע\"ז ט, א. ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ר' אבהו פתח והמה כאדם על יד הערה 85."],["4337","21","<b>דאורייתא מחכ' נפקת</b>: זהר בשלח סב, א. יתרו פה, א. רע\"מ משפטים קכא, א. קדושים פא, א. חוקת קפב, א. ואתחנן רסא, א."],["4338","22","<b>וחכ'. . קצת דין</b>: ראה תו\"א בראשית ה, ד. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה כי הנה יוצר הרים ובהערה 37."],["4339","23","<b>אף ברי. . ענן אורו</b>: איוב לז, יא."],["4340","24","<b>והוא מסיבת מתהפך בתחבולתם לפעלם</b>: איוב שם, יב [ושם: מסיבות מתהפך בתחבולותיו]."],["4341","25","<b>ואי' בזהר לפעלם דבני נשא</b>: וירא קט, ריש ע\"ב."],["4342","26","<b>וכ\"פ רש\"י והוא מהגמ'</b>: איוב שם, יב. ר\"ה יז, ב."],["4343","27","<b>דאין לך דבר שעומד בפני התשובה</b>: ראה תניא פכ\"ה. פיה\"מ להרמב\"ם אבות פ\"ג, מי\"א. סה\"מ תש\"ט ע' 42 (הא') בהערה. לקו\"ש בא כרך ו ע' 66 הערה 54."]]],[2000480428,"ומקום הראוי' אפי' מעט די, וזהו שאמר בזהר לפעלם דבני נשא כהדין טקלא דאסתחרת קמי'<sup data-n=\"4344\">28</sup>.\n<b>והגם</b> שמפרשי' זה על מקור דבי\"ע ולעיל נת' שקאי על חכ' התורה, אך הנה כתי' כולם בחכ' עשית<sup data-n=\"4345\">29</sup> שגם חכ' נחשבת לעשי' גשמיות<sup data-n=\"4346\">30</sup> וכתי' בה<sup data-n=\"4347\">31</sup> בחכ' יסד ארץ<sup data-n=\"4348\">32</sup>, ארץ שהוא מקור בי\"ע יסד בחכ' שרשו מחכ', דהנה יש ב' מיני השפעות, השפעה דחיי שעה, והשפעה דחיי עולם<sup data-n=\"4349\">33</sup>, והגם שכל השפעה צ\"ל ע\"י בחי' חיי שעה, מ\"מ שרשה מבחי' חיי עולם<sup data-n=\"4350\">34</sup> וכמ\"ש וחיי עולם נטע בתוכינו<sup data-n=\"4351\">35</sup> (שעה, מל'<sup data-n=\"4352\">36</sup>, חיי שעה, ז\"א<sup data-n=\"4353\">37</sup>, עולם, ז\"א<sup data-n=\"4354\">38</sup>, חיי עולם, חו\"ב<sup data-n=\"4355\">39</sup> ) דכל מה שיש בעולם יש בתורה וכמ\"ש בזהר אסתכל באורייתא וברא עלמין<sup data-n=\"4356\">40</sup>, רק שהוא ברוחניות, לכן אפי' השפעה גשמיות תלוי בתורה, וכדאי' בזהר זימנא חדא הוה צריך עלמא למטרא<sup data-n=\"4357\">41</sup> שלחו ב' ת\"ח<sup data-n=\"4358\">42</sup> לרשב\"י א\"ל דרוש ע\"פ מה טוב ומה נעים<sup data-n=\"4359\">43</sup> שבת אחים גם יחד וירדו גשמים, והענין דהנה למעלה יש ג\"כ בחי' גשם וכמ\"ש והי' אור הלבנה כאור החמה<sup data-n=\"4360\">44</sup> ואור החמה יהי' שבעתיים כאור שבעת הימים ופרש\"י<sup data-n=\"4361\">45</sup> שבעת הימים זפ\"ז שבעתים כאור זה\"י הוא ז' פעמי' מ\"ט בגימ' גשם וזהו כל אורה האמור באלי'<sup data-n=\"4362\">46</sup> בירידת הגשמים הכתוב מדבר וכמו שהוא למעלה הוא אור אך בריבוי השתל' מתגשם ההשפעה עד שנעשה גשמים גשמיים, לכן תלוי זה בתורה, וכמ\"ש אם בחוקתי תלכו<sup data-n=\"4363\">47</sup> ונתתי גשמיכם בעתם<sup data-n=\"4364\">48</sup>, וזהו",[["4344","28","<b>כהדין טקלא דאסתחרת קמי'</b>: ראה זהר וירא שם."],["4345","29","<b>כולם בחכ' עשית</b>: תהלים קד, כד."],["4346","30","<b>שגם חכ' נחשבת לעשי' גשמיות</b>: ראה תניא פ\"ב בהגהה. לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח פ\"ח ובהערה 142."],["4347","31","<b>בה</b>: בהצילום אינו ברור מה כתוב כאן — בהכתוב (שבהערה הבאה) ה'."],["4348","32","<b>ה' בחכ' יסד ארץ</b>: משלי ג, יט."],["4349","33","<b>דחיי שעה. . דחיי עולם</b>: שבת י, א."],["4350","34","<b>שכל השפעה. . חיי שעה. . חיי עולם</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן על יד הערה 32."],["4351","35","<b>וחיי עולם נטע בתוכינו</b>: נוסח ברה\"ת. ובא לציון."],["4352","36","<b>שעה מל'</b>: פע\"ח שער תפילות ר\"ה שכ\"ה, פ\"ג [ירושלים תש\"מ תקעא, א]. סידור שער הק\"ש עה, סע\"א ואילך."],["4353","37","<b>חיי שעה ז\"א</b>: ראה גם סידור שער הק\"ש עה, ב. אוה\"ת ואתחנן כרך ו' ע' ב'רמא. לעיל הנחה ד\"ה וכל שיח השדה על יד הערה *49."],["4354","38","<b>עולם ז\"א</b>: ראה ע\"ח שער הארת המוחין של\"ב, פ\"ה. שער לאה ורחל של\"ח, פ\"ט. שער מאמרי רז\"ל סנהדרין צז, א (ל, ב)."],["4355","39","<b>חיי עולם חו\"ב</b>: ראה גם סידור שם. מאמרי אדה\"א בראשית ע' תקכח. אוה\"ת ואתחנן שם. לעיל הנחה ד\"ה וכל שיח השדה על יד הערה 50 [ושם: ע\"ק]."],["4356","40","<b>אסתכל באורייתא וברא עלמין</b>: ראה זהר תולדות קלד, א. תרומה קסא, א. מאמרי אדה\"א דברים ח\"א ע' רעט ואילך."],["4357","41","<b>זימנא חדא. . למטרא</b>: זהר אחרי נ\"ט, ריש ע\"ב. ראה גם סה\"מ תרכ\"ז ע' רצא ואילך. וש\"נ."],["4358","42","<b>שלחו ב' ת\"ח</b>: בזהר שם: ר' ייסא ר' חזקי' ושאר חברייא. וראה גם פי' הרמ\"ז שם ד\"ה כיון דחמא לון."],["4359","43","<b>מה טוב ומה נעים</b>: תהלים קלג, א."],["4360","44","<b>והי' אור הלבנה כאור החמה</b>: ישעי' ל, כו."],["4361","45","<b>ופרש\"י</b>: ראה ישעי' שם. סה\"מ תרל\"ח ע' קס. וש\"נ. לעיל הנחה ד\"ה יונתי ובהערה 115."],["4362","46","<b>כל אורה האמור באלי'</b>: ראה גם לעיל שם ובהערה 113."],["4363","47","<b>אם בחקתי תלכו</b>: בחוקותי כו, ג."],["4364","48","<b>ונתתי גשמיכם בעתם</b>: בחוקותי שם, ד."]]],[2000480429,"שא' דוד כי לעולם חסדו<sup data-n=\"4365\">49</sup> דהנה כתי' אני הוי' לא שניתי<sup data-n=\"4366\">50</sup> שלא יש שום שינוים כלל וא\"כ בחי' שם הוי' דא\"א גם עתה הוא בבחי' החסד בלי גבול. וזהו שא' לעולם חסדו שגם עתה בעולם יומשך בחי' חסדו הוא החסד שבלי גבול.\n<b>וביאור</b> הענין הנה אמרז\"ל לעולם יהא אדם רך כקנה<sup data-n=\"4367\">51</sup> ואל יהא קשה כארז וצ\"ל מהו\"ע ההדרכה שיהי' רך כקנה, וגם צ\"ל אומרם ואל יהא קשה כארז דמאחר שאמר שיהי' רך מובן שלא יהי' קשה כו', אלא משמע שהכוונה שלכל הפחות לא יהי' קשה כארז, והענין דהנה החכמים מדריכים את ישראל שיהי' מנהג מדותיהם ע\"פ חכ' התורה<sup data-n=\"4368\">52</sup>, דהנה תורה הוא ממוצע<sup data-n=\"4369\">53</sup> בין א\"ס לעולם אפי' בחי' עליונה בתורה שהוא בחי' שעשועים הוא רק ממוצע וזה דכתי' תחילה ואהי' אצלו אמון ואי' במדרש אומן<sup data-n=\"4370\">54</sup>, והאומן אינו בונה מד\"ע אלא מתוך כתבו, וכן אי' בזהר אסתכל באורייתא וברא עלמין, וזהו אלפים שנה קדמה תורה לעולם<sup data-n=\"4371\">55</sup> ואינו שייך לומר קדמה בזמן, אלא קדמה במעלה<sup data-n=\"4372\">56</sup> ומדריגה שהיא ממוצע וכמו שיצי\"מ הי' ע\"י משה ואהרן<sup data-n=\"4373\">57</sup> והממוצע צ\"ל כלול משניהם<sup data-n=\"4374\">58</sup> בחי' תחתונה ממדריגה שלמעלה ממנו ובחי' עליונה ממדרי' שלמטה הימנה (משה שושבינא דמלכא<sup data-n=\"4375\">59</sup>, ואהרן שושבינא דמטרוניתא<sup data-n=\"4376\">60</sup> ) וכן בתורה יש ב' מדרי' דאי' בזהר תלת קשרין<sup data-n=\"4377\">61</sup> מתקשרין דא בדא ישראל מתקשראין באורייתא ואורייתא בקוב\"ה וכולהו דרגין על דרגין סתים וגליא, ובאופן ההתקשרות יש בזה פשטים (ואפ\"ל סתים דתורה בגליא דקוב\"ה, וגליא דתורה בסתים דישראל וע\"י ההתקשרות בבחי' גליא דתורה מתקשר לאלקות וה\"ז כמו משה ואהרן וצ\"ע), וה\"ז כמו דצח\"ם שהממוצע<sup data-n=\"4378\">62</sup> בין דומם לצומח הם אבני אלגביש שהם דומם וצומחים<sup data-n=\"4379\">63</sup>, וכן בין צומח לחי אי' בשו\"ע שיש מיני עופות",[["4365","49","<b>כי לעולם חסדו</b>: תהלים קלו, א ואילך."],["4366","50","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו."],["4367","51","<b>לעולם יהא אדם רך כקנה</b>: תענית כ, סע\"א. ראה לקו\"ת אמור לז, ד. מטות פז, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תשמז. וש\"נ. סה\"מ תרל\"ח ע' תלט. וש\"נ."],["4368","52","<b>מנהג מדותיהם ע\"פ חכ' התורה</b>: ראה גם פלח הרמון בחוקותי ע' תקמו."],["4369","53","<b>תורה הוא ממוצע. . ב' מדרי'</b>: ראה גם סה\"מ תרל\"ו ח\"ב ע' שלג."],["4370","54","<b>ואהי' אצלו אמון. . אומן</b>: משלי ח, ל. ב\"ר בתחילתו."],["4371","55","<b>אלפים שנה קדמה תורה לעולם</b>: ראה מדרש תהלים צ, ד. שבת פח, ב וברש\"י שם. הנסמן במאמרי אדה\"א דברים ח\"א ע' כ. מאמר ד\"ה זה תשי\"א יום ב' דחה\"ש."],["4372","56","<b>קדמה במעלה</b>: ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 899."],["4373","57","<b>ממוצע. . משה ואהרן</b>: ראה גם אוה\"ת שבהערה הבאה. סה\"מ תרל\"ח ע' קעז."],["4374","58","<b>והממוצע צ\"ל כלול משניהם</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב, פ\"א. סידור שער הל\"ג בעומר שו, ב. אוה\"ת בשלח ע' תקע ואילך."],["4375","59","<b>משה שושבינא דמלכא</b>: ראה זהר רע\"מ ויקרא כ, א. מצורע נג, ב. רע\"מ שופטים ערה, ב. תו\"ח שמות ח\"א יא, ג הערה 510."],["4376","60","<b>ואהרן שושבינא דמטרוניתא</b>: ראה זהר רע\"מ ויקרא שם. הנסמן במאמרי אדה\"א דברים ח\"א ע' קג. מאמרי אדה\"א שמות ח\"ב ע' שטו וע' שמ."],["4377","61","<b>תלת קשרין</b>: ראה זהר אחרי עג, א. הנסמן במאמרי אדה\"א קונטרסים ע' שלט."],["4378","62","<b>דצח\"ם שהממוצע</b>: ראה ע\"ח ואוה\"ת שבהערה 58."],["4379","63","<b>אבני אלגביש שהם דומם וצומחים</b>: כ\"ה בגוכתי\"ק — ראה יחזקאל יג, יא (ובמפרשים שם). יג. לח, כב.\nבע\"ח שם בשם חכמי הטבע הקורא\"לי הנקרא אלמוגים. באוה\"ת שםא עצי אלמוגים."]]],[2000480430,"שגדלים באילן<sup data-n=\"4380\">64</sup> (ובע\"ח שמ\"א פ\"א<sup data-n=\"4381\">65</sup> אי') ויש עוד מין חי' שטבורו נעוץ בקרקע ומקבל חיות מהקרקע ה\"ה חי וגם צומח, ובין חי למדבר הוא קוף<sup data-n=\"4382\">66</sup> נמצא הממוצע הוא כלול משניהם, וע\"י התורה נעשה האדם ג\"כ ממוצע<sup data-n=\"4383\">67</sup> וכמארז\"ל כל העולם לא נברא אלא לצוות לזה<sup data-n=\"4384\">68</sup> שיבוא לבחי' זה היינו שימשיך גילוי אלקות בעולם דכתי' הליכות עולם לו<sup data-n=\"4385\">69</sup> ויש בזה ב' פי' הילוך מלמעלמ\"ט והילוך מלמטלמ\"ע<sup data-n=\"4386\">70</sup> והו\"ע תורה ותפלה<sup data-n=\"4387\">71</sup> וכתי' גם את העולם נתן בלבו<sup data-n=\"4388\">72</sup> שהעולם נתון בלבו של אדם שלפ\"ע הבירור שעושה בנפשו לפ\"ע זה מברר חלקו בעולם, ולכן אמרז\"ל לעולם יהא אדם רך כקנה היינו שיתנהג ע\"פ המדות דתקון שהם מורכבים זמ\"ז ואל יהא קשה כארז הם מדות דתהו וזה נוגע מאד.\n<b>והענין</b> דהנה גבי בריאת האדם כתי' נעשה אדם בצלמינו<sup data-n=\"4389\">73</sup> וכתי' בצלם אלקי' עשה את האדם<sup data-n=\"4390\">74</sup> משא\"כ שארי בע\"ח, והוא להורות שע\"י אתעדל\"ת אתעדל\"ע<sup data-n=\"4391\">75</sup>, דלכאו' קשה מהו\"ע העבודה וכי עבודה צורך גבוה<sup data-n=\"4392\">76</sup> והלא אנת הוא שלימותא דכולא<sup data-n=\"4393\">77</sup>, אלא שהוא כחותם המתהפך<sup data-n=\"4394\">78</sup> וזהו בצלמינו דצלם הוא צורה",[["4380","64","<b>בשו\"ע. . עופות שגדלים באילן</b>: חיו\"ד ספ\"ד, סט\"וב."],["4381","65","<b>ובע\"ח שמ\"א פ\"א</b>: במהדורת שקלאב וכנשצ\"ל: פ\"ג. ע\"ח שבהערה 58 [ושם: אדני השדה הנזכר במס' כלאים [פ\"ח, מ\"הג] שהוא כמין כלב — ראה גם אוה\"ת ויצא ח\"א ע' קעגד]."],["4382","66","<b>ובין חי למדבר הוא קוף</b>: בסה\"מ תרל\"ו ח\"ב ע' תעט: קוף. . או עוף הנק' פופיגאיה."],["4383","67","<b>האדם ג\"כ ממוצע</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן."],["4384","68","<b>כל העולם. . לצוות לזה</b>: ראה ברכות ו, ב. ראה גם (לעיל בחלק המאמרים) בהמאמר כאן על יד הערה 63."],["4385","69","<b>הליכות עולם לו</b>: חבקוק ג, ו."],["4386","70","<b>הליכת. . מלמעלמ\"ט. . מלמטלמ\"ע</b>: ראה גם תו\"א וישב ל, ד. מאמרי אדה\"ז תקס\"ט ע' קלא ואילך ובהנסמן שם."],["4387","71","<b>והו\"ע תורה ותפלה</b>: ראה גם תו\"א מקץ לח, ג. שע\"ת קב, ג. סה\"מ תרל\"ג ח\"ב ע' תכג ואילך (ובהנסמן בריש המאמר שם)."],["4388","72","<b>גם את העולם נתן בלבו</b>: קהלת ג, יא [ושם: בלבם]. ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה מזבח אדמה תעשה לי ובהערה 142."],["4389","73","<b>נעשה אדם בצלמנו</b>: בראשית א, כו."],["4390","74","<b>בצלם אלקי' עשה את האדם</b>: נח ט, ו. להבא להלן ראה לקו\"ת עקב יז, ג ואילך."],["4391","75","<b>אתעדל\"ת אתעדל\"ע</b>: ראה זהר לך פח, א. מאמר ד\"ה לרוקע נדפס במאמרי אדה\"ז תקס\"ב ח\"א ע' קצד [ובמקביליו ובהנסמן במ\"מ לשם]. מאמרי אדה\"א דברים ח\"א ע' קצח. וש\"נ. תו\"ח שמות ח\"א מא, א ובהערה 189."],["4392","76","<b>עבודה צורך גבוה</b>: ראה גם לעיל הנחה ד\"ה יפה שעה אחת הא' ובהערה 44."],["4393","77","<b>אנת הוא שלימותא דכולא</b>: ראה ת\"ז בהקדמה יז, ב."],["4394","78","<b>כחותם המתהפך</b>: ראה גם אגה\"ק ס\"כ (קלא, א). מאמרי אדה\"ז תקס\"ח ח\"א ע' מב. פיה\"מ קז, א. מאמרי אדה\"א נ\"ך ע' ריד. וש\"נ. קונטרסים ע' רפז. תו\"ח תצוה ח\"ב שכא, א. מאמרי אדמו\"ר הצ\"צ הנחות תרי\"ד ע' ז. (לעיל בחלק המאמרים) בהמאמר כאן על יד הערה 73."]]],[2000480431,"בולטת ועז\"נ שמני כחותם על לבך אלו רצועות דתש\"ר דתליין על לבו, וכמו החותם כשהאותיות בולטים בו אז נעשה על השעוה אותיות שקועים וכשהאותיות על החותם שקועים נעשים על השעוה בולטים וכמו\"כ יובן בעבודה בישראל ע\"י החותם שקוע שפועל בנפשו נמשך מלמעלה חותם בולט וע\"י עבודה דחותם בולט נמשך מלמעלה חותם שוקע, וכן בסתים וגליא דקוב\"ה ע\"י חותם בולט דלמעלה פועל שקיעה בהאדם וע\"י חותם שוקע דלמעלה פועל בליטה בהאדם, ולפ\"ז מובן שע\"י המשכת החסד שנמשך אותן ך\"ו דור עד מ\"ת אך ב' אלפי' תורה מתחילים מש' נ\"ב לאברהם דאבות עשו הכנה למ\"ת<sup data-n=\"4395\">80</sup> וגם נתנו להם איזה מצות<sup data-n=\"4396\">81</sup>, הנה השפעת חסד זה פעל באברהם דכתי' עליו אברהם אוהבי<sup data-n=\"4397\">82</sup> רק שכלול בו יראה<sup data-n=\"4398\">83</sup> ג\"כ אך העיקר הוא האהבה ונק' אוהב הראשון וכמ\"ש מי העיר ממזרח<sup data-n=\"4399\">84</sup> זה אברהם שהמשיך גילוי אלקות בעולם שהאכיל והשקה אפי' לערביים<sup data-n=\"4400\">85</sup> וא\"ל ברכו למי שאכלתם משלו<sup data-n=\"4401\">86</sup> והודיעו<sup data-n=\"4402\">87</sup> אלקותו בעולם לכן נק' אוהב הראשון, ובחי' השפעת החסד שמלמעלה פעל השקיעה באברהם והוא בחי' חסד דמ\"ה<sup data-n=\"4403\">88</sup> היינו ההשפעה מצד הביטל בבחי' שריים<sup data-n=\"4404\">89</sup> (ע' בלקו\"ת ד\"ה שימני<sup data-n=\"4405\">90</sup> כחותם<sup data-n=\"4406\">79</sup> על לבך ובאמ\"ב בשער התפילין<sup data-n=\"4407\">91</sup>, ובלקו\"ת בביאור לד\"ה הנ\"ל<sup data-n=\"4408\">92</sup> וצל\"ע בתו\"א ד\"ה אלה תולדות יצחק<sup data-n=\"4409\">93</sup> כו' בפי' ואהבת ואפשר כמו\"כ יובן כאן וצ\"ע) והוא ע\"י החותם בולט דלמעלה והיינו ההשפעות מצד ולגדולתו אין חקר<sup data-n=\"4410\">94</sup> שלגדולתו העצמיות אין חקר כלל וכולא קמי' כ\"ח<sup data-n=\"4411\">95</sup> דא\"ס הוא קדמון לכל",[["4395","80","<b>דאבות עשו הכנה למ\"ת</b>: ראה תו\"א לך יא, ג<sup data-n=\"e306\">ו</sup>. אוה\"ת לך כרך ד ע' תרצב."],["4396","81","<b>דאבות. . נתנו להם איזה מצות</b>: ראה רמב\"ם הל' מלכים רפ\"ט ובמפרשיו. לקו\"ש לך כרך ה' ע' 68 ואילך. תולדות כרך כה ע' 120 ואילך."],["4397","82","<b>אברהם אוהבי</b>: ישעי' מא, ח."],["4398","83","<b>אברהם. . שכלול בו יראה</b>: ראה אגה\"ק סי\"ג. מאמרי אדה\"א דברים ח\"ד ע' א'תלג. וש\"נ. תו\"ח תצוה ח\"ב שכג, ג."],["4399","84","<b>מי העיר ממזרח</b>: ישעי' מא, ב. ראה גם ב\"ר פ\"ב, ג."],["4400","85","<b>אברהם. . שהאכיל. . לערביים</b>: ראה ב\"מ פו, ב. תו\"ח לך פג, ד הערה 57."],["4401","86","<b>ברכו למי שאכלתם משלו</b>: ראה סוטה י, ב. לקו\"ש וירא כרך טו ע' 122 ואילך ובהנסמן שם."],["4402","87","<b>והודיעו</b>: כ\"ה בגוכתי\"ק."],["4403","88","<b>באברהם. . חסד דמ\"ה</b>: ראה גם בנוסף ללקו\"ת שבהערה 74. (לעיל בחלק המאמרים) בהמאמר כאן על יד הערה 88. סה\"מ תרכ\"ז ע' קצח ואילך. וע' תמז ואילך. תרכ\"ט ע' רכז. וש\"נ. תרל\"ח ע' תפז."],["4404","89","<b>באברהם. . שריים</b>: ראה לקמן בהנחה כאן ובהנסמן שם."],["4405","90","<b>בלקו\"ת בד\"ה שימני כחותם</b>: מה, א ואילך."],["4406","79","<b>שימני כחותם על לבך</b>: שה\"ש ח, ו. ראה ת\"ז תכ\"ב סה, ב. לקו\"ת שה\"ש ד\"ה זה (מה, א ואילך) וביאורו. וש\"נ."],["4407","91","<b>ובאמ\"ב בשער התפילין</b>: פכ\"ד ואילך."],["4408","92","<b>ובלקו\"ת בביאור לד\"ה הנ\"ל</b>: מו, א ואילך."],["4409","93","<b>בתו\"א ד\"ה אלה תולדות יצחק</b>: יז, ג."],["4410","94","<b>ולגדולתו אין חקר</b>: תהלים קמה, ג."],["4411","95","<b>וכולא קמי' כ\"ח</b>: ראה זהר בהקדמה יא, ב. ראשית חכמה שער היראה ש\"א, פ\"ז [ז, רע\"א]. מאמרי אדה\"ז תקס\"ו ע' שמא. מאמרי אדה\"א דברים ח\"ב ע' תרנג.\n\n<b>ו</b>  הועתק לעיל בחלק המאמרים בהמשך מצה זו פכ\"ד."]]],[2000480432,"הקדומים<sup data-n=\"4412\">96</sup> כי גאה גאה<sup data-n=\"4413\">97</sup> ועי\"ז נעשה<sup data-n=\"4414\">98</sup> השקיעה באברהם בחי' חותם שוקע ולכן אמרז\"ל דבחזרתו פרע הקפותיו<sup data-n=\"4415\">99</sup> והיינו להודיע דמה שחייך קודמים היינו כעין מעשה שהי'<sup data-n=\"4416\">100</sup> בקיתון של מים, אבל במותרות אינו שייך חייך קודמים, ובכל מעשיו הודיע אלקותו בעולם, וזהו ואנכי עפר ואפר<sup data-n=\"4417\">101</sup>, עפר הוא דומם שהוא מדריגה האחרונה ואפר הוא דאשתאר מנורא והיינו השקיעה שנעשה בנפשו ע\"י החותם בולט דלמעלה (בפ\"א וכן גבי יעקב כתי' קטנתי מכל החסדים<sup data-n=\"4418\">102</sup> שמכל החסדים שנמשך ממעלה מזה קטונתי) (בפ\"ב<sup data-n=\"4419\">103</sup> וגבי יעקב כתי' קטונתי מכל החסדים ומכל האמת והוא מדרי' גבוה יותר מאברהם, שהאיר בו מבחי' חסד של אמת ועי\"ז קטונתי לגמרי וכמ\"ש באגה\"ק<sup data-n=\"4420\">104</sup> ).\n<b>וכמו\"כ</b> יובן בעבודה שיש אהוי\"ר אך לית פולחנא כפולחנא דרחימותא<sup data-n=\"4421\">105</sup> דעיקר עבודה הוא אהבה וכתי' זכור אב נמשך אחריך כמים<sup data-n=\"4422\">106</sup> פי' מה שנמשך אחרי\"ך זהו כמים (בפ\"ג אחר פועל דמים<sup data-n=\"4423\">107</sup> ) אחריך הוא א\"ס דע\"י גילוי שע\"י גדולתו העצמיות למטה נעשה חותם שוקע למטה ממילא מובן שע\"י האהבה דמים דלמטה ממשיכים בחי' לגדולתו אין חקר שהוא כחותם המתהפך, ולפ\"ז הרי אתעדל\"ע שע\"י האתעדל\"ת דאהבה כמים הוא גבוה יותר מהאתדל\"ע<sup data-n=\"4424\">108</sup> שע\"י האהבה כרשפי אש, דאהבה כרשפי אש הוא חותם בולט דלמטה ונמשך מלמעלה חותם שוקע והיינו המשכת אורות בכלים אך ע\"י אהבה כמים נמשך חותם בולט דלמעלה, לכן גבי יעקב אי' בזהר דארמי מיא לגו חמרא<sup data-n=\"4425\">109</sup> שרצה להמשיך הברכות מיצחק וברכה הוא בריבוי לכן ארמי מיא שיומשך בחי' חותם בולט.\n<b>ועפ\"ז</b> יובן מ\"ש מי אל כמוך נושא עון ועובר על פשע לשארית נחלתו<sup data-n=\"4426\">110</sup> ואמרז\"ל ולא לכל נחלתו למי שמשים עצמו כשריים<sup data-n=\"4427\">111</sup> וצ\"ל והלא בחי' זו הוא שנמשך משם סליחת עונות נושא עון ועובר על פשע ומה שייך שם דקדוקים למי שמשים עצמו כשריים דוקא, והענין דהנה מקובלים הראשונים עד האריז\"ל קוראים",[["4412","96","<b>קדמון לכל הקדומים</b>: לשון ת\"ז תי\"ט (מב, א). ראה מאמרי אדה\"א דברים ח\"ב ע' תנט. וש\"נ."],["4413","97","<b>כי גאה גאה</b>: בשלח טו, א."],["4414","98","<b>נעשה</b>: בהצילום אינו ברור כ\"כ מה כתוב כאן."],["4415","99","<b>דבחזרתו פרע הקפותיו</b>: ב\"ר פמ\"א, ג. רש\"י לך יג, ג."],["4416","100","<b>שחייך קודמים. . מעשה שהי'</b>: ב\"מ סב, א. ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 1395."],["4417","101","<b>ואנכי עפר ואפר</b>: וירא יח, כז."],["4418","102","<b>קטנתי מכל החסדים</b>: וישלח לב, יא."],["4419","103","<b>בפ\"ב</b>: אולי כתוב: בפ\"ג. ראה לעיל הערה 16."],["4420","104","<b>וכמ\"ש באגה\"ק</b>: ס\"ב."],["4421","105","<b>לית פולחנא כפולחנא דרחימותא</b>: ראה זהר בשלח נה, ב. ואתחנן רסז, א. לקו\"ת שלח מב, ג. תו\"ח תצוה ח\"ב שסג, ד. וש\"נ."],["4422","106","<b>זכור אב נמשך אחריך כמים</b>: תפלת גשם."],["4423","107","<b>אחר פועל דמים</b>: תיבות אלו אינם ברורים כ\"כ."],["4424","108","<b>מהאתעדל\"ע</b>: אולי כן כתוב."],["4425","109","<b>דארמי מיא לגו חמרא</b>: ראה זהר בלק קפט, א."],["4426","110","<b>מי אל כמוך. . לשארית נחלתו</b>: מיכה ז, יח."],["4427","111","<b>ולא לכל נחלתו. . כשריים</b>: ר\"ה יז סע\"א ואילך."]]],[2000480433,"סדר ההשתל' גג\"ת<sup data-n=\"4428\">112</sup> כו' ר\"ת גדולה גבורה תפארת, והאריז\"ל קורא אותם חג\"ת כו', ר\"ת חסד גבורה תפארת, ובאמת לא פליגי, דהמקובלים הראשונים קוראים למדות<sup data-n=\"4429\">113</sup> החסד בשם גדולה שכן כתי' לך ה' הגדולה<sup data-n=\"4430\">114</sup> שמדת הגדולה הוא לך, דהנה כדי שיומשך ההשפעה מא\"ס בעולמות הוא מצד שלגדולתו אין חקר ארך אפים וגדל חסד<sup data-n=\"4431\">115</sup> וכמ\"ש כי גאה גאה שמתגאה על גיותניא ומצד הגדולה הוא משפיע בעולם, וא\"כ בנבראים אינו שייך גדולה, שהרי כולא קמי' כ\"ח וכל השתל' העולמות אינו בערך כטפה לגבי ים<sup data-n=\"4432\">116</sup> שאף שאינו שייך בו מדידה מ\"מ שייך בו השערה כמו שאר\"י יכולני לשער<sup data-n=\"4433\">117</sup> כמה טיפין יש בים, ועוד שהם מהות אחד משא\"כ העולמות לא\"ס אין ערוך כלל והתהוותן הוא רק מהארה בעלמא בבחי' אור של תולדה (וכמ\"ש בתו\"א בד\"ה ולא יקרא<sup data-n=\"4434\">118</sup> כו' ואין זה מהות אור הראשון כו') ולכן כל סטר' דקדושה הוא בחי' ביטל וכמאמר כל נהוראין מתחשכאין קמי'<sup data-n=\"4435\">119</sup> כ\"ע אע\"ג דאיהו אור צח אור מצוחצח אוכם הוא<sup data-n=\"4436\">120</sup> קדם עה\"ע שכל נהוראין הם בבחי' חשך ביטל, וא\"כ אינו שייך שייחסו הגדולה לעצמם מאחר שכקכל\"ח, אלא הגדולה שייך דוקא בההשפעה שנמשך מא\"ס, וזהו לך ה' הגדולה שמדת הגדולה הוא לך לבד, ועוי\"ל שמדת הגדולה טפל ובטל לך, דבמקום גדולתו שם אתה מוצא ענוותנותו<sup data-n=\"4437\">121</sup> שזהו ירידה והשפלה לגבי מה שנק' גדולה.\n<b>אכן</b> האריז\"ל קורא אותה בשם חסד היינו חסד דז\"א שהוא בחי' ביטל דאפי' הכלים ג\"כ בטלים, הגם שאי' בכהאריז\"ל דהכלים הם בבחי' גבול ומדה (הוא בע\"ח שמ\"א<sup data-n=\"4438\">122</sup> ) ואפי' לדעת העה\"ק שכ' דהוא אינון ואינון הוא<sup data-n=\"4439\">123</sup> מ\"מ הם בחי' הגבול שבא\"ס<sup data-n=\"4440\">124</sup>, אך א\"כ ה\"ז א\"ס פי' שא\"ס להביטל וא\"כ אינו שייך לקרוא אותו גדולה",[["4428","112","<b>מקובלים הראשונים. . גג\"ת</b>: ראה (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 100."],["4429","113","<b>למדות</b>: כ\"ה בגוכתי\"ק."],["4430","114","<b>לך ה' הגדולה</b>: דהי\"א כט, יא."],["4431","115","<b>ארך אפים וגדל חסד</b>: תהלים קמה, ח."],["4432","116","<b>כטפה לגבי ים</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"א ע' קסד. סהמ\"צ להצ\"צ ע' צא ואילך. מאמרי אדה\"א נ\"ך ע' שלח ואילך."],["4433","117","<b>שאר\"י יכולני לשער</b>: כ\"ה גם בסה\"מ תרכ\"ז ע' קמז־ ע' רצג־ ע' שצ. תרל\"ח ע' תפח. וש\"נ. תרס\"ג ח\"א ע' נה ובהערה לשם: ראה הוריות י, א. ואולי גם כאן צ\"ל שיכולים לשער. וע\"ד מ\"ש בסהמ\"צ להצ\"צ<sup data-n=\"e307\">ו</sup>. ח\"ב ע' ל."],["4434","118","<b>אור של תולדה (וכמ\"ש בתו\"א בד\"ה ולא יקרא</b>: לך יב, ריש ע\"ב. ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה להבין שרש ענין מקיפים דבינה ובהערה 57."],["4435","119","<b>כל נהוראין מתחשכאין קמי'</b>: ראה זהר בראשית כג, א."],["4436","120","<b>כ\"ע. . אוכם הוא</b>: ראה ת\"ז ת\"ע קלה, ב. מאמרי אדה\"א דברים ח\"ג ע' תתיא. וש\"נ. המשך והחרים תרל\"א ע' סט. סה\"מ תרל\"ד ע' רמז. המשך תער\"ב ח\"א ע' כא."],["4437","121","<b>דבמקום גדולתו. . ענוותנותו</b>: ראה מגילה לא, א. סה\"מ תרנ\"א ע' עא. ה'ש\"ת ע' 40 בהערה. תו\"ח יתרו ח\"ב רנט, ב הערה 122."],["4438","122","<b>בכהאריז\"ל דהכלים. . גבול. . בע\"ח שמ\"א</b>: בדפוסים אחרים שער דרושי אבי\"ע שמ\"ב, פ\"ב. ראה (לעיל בחלק המאמרים) בהמאמר כאן הערה 113."],["4439","123","<b>לדעת העה\"ק שכ' דהוא אינון ואינון הוא</b>: חלק היחוד פ\"ד. ראה גם לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח ובהערה 102."],["4440","124","<b>דהכלים. . בחי' הגבול שבא\"ס</b>: ראה עבודת הקודש ח\"א רפ\"ח. לעיל הנחה ד\"ה אני לדודי הב' ובהערה 59.\n\n<b>ו</b>  צא, ריש ע\"ב."]]],[2000480434,"כ\"א בחי' חסד דמה היינו החסד מצד הביטל, והמקובלים שקראו אותו גדולה היינו בחי' הגדולה שבא\"ס אבל בעולם אינו שייך גדולה דכולא קמי' כ\"ח, הגם שאנו מוצאים גדולה בעולמות ג\"כ (בפ\"א עולם התהו) אך שם ההשפעה הוא מצד הגדולה והוא ההיפך מבחי' חסד דאברהם בחי' חסד דמ\"ה וכמו מי שהקב\"ה משפיע לו בריבוי הרי נותן לזולתו וכמו פירורים מסעודה גדולה (של מלכים) הוא יותר מעשירות של אדם פשוט, ובחי' השפעה זו הוא מה שנפל בבחי' שבירה ונפילה, לכן ויוציאנו ה' אלקינו משם<sup data-n=\"4441\">125</sup> היינו או\"א שהלבישו לזרועות דא\"א<sup data-n=\"4442\">126</sup> דכשנמשך באו\"א הי' יצי\"מ, וזהו לעולם יהא אדם רך כקנה שיתנהג ע\"פ מדת דתקון מה הוא רחום<sup data-n=\"4443\">127</sup> אף אתה רחום וענין רחום הוא התכללות דחו\"ג<sup data-n=\"4444\">128</sup> וע\"י ההתכללות נמשך מבחי' אנת הוא שלימותא דכולהו והוא בחי' תיקון, דבתהו לא הי' התכללות<sup data-n=\"4445\">129</sup>, ואל יהא קשה כארז שהו\"ע מדות דתהו השפעה מצד הגדולה וזהו רק בדרך שבירה. וזהו לשארית נחלתו ולא לכל נחלתו למי שמשים עצמו כשריים וצ\"ל למה לא לכל נחלתו, והלא באמת כמה א\"א לפניו, אך הענין הוא דמצד א\"ס אינו שייך דקדוק זה, אך מ\"מ צריכים להיות כלי לקבל גילוי זה וזהו מי שמשים עצמו כשריים בחי' חותם שוקע עי\"ז נמשך בחי' חותם בולט.\n<b>וזהו\"ע</b> ך\"ו הודו שא' דוד, וצ\"ל למה דוד דוקא, והענין דהנה דוד הי' בבחי' ביטל וכמ\"ש לא גבה לבי ולא רמו עיני<sup data-n=\"4446\">130</sup> לא הלכתי בגדולות ונפלאות ממני אם לא שויתי ודוממתי<sup data-n=\"4447\">131</sup>, שהי' בבחי' דומם, ופעם א' ע\"ע, כי עני ואביון אני<sup data-n=\"4448\">132</sup>, וגם א' ע\"ע ואנכי תולעת ולא איש<sup data-n=\"4449\">133</sup>, שהוא מהנבראים הרומשים ע\"פ הארץ ועיקר המשל מהרמשה שבעת שהי' לומד תורה הי' מעדן עצמו כתולעת<sup data-n=\"4450\">134</sup>, לכן אמר ך\"ו כי לעולם חסדו, שאפי' עתה בהעולם יומשך בחי' חסד שבלי גבול, וזהו ונפשי כעפר לכל תהי' פתח לבי בתורתך<sup data-n=\"4451\">135</sup>, דאורייתא מחכ' נפקת ויש שם הגבלה וצמצומים, וכדי שיהי' פתיחה בתורה היינו שיומשך בחי' ורב חסד בתורה, זהו ע\"י ונפשי כעפר",[["4441","125","<b>ויוציאנו ה' אלקינו משם</b>: הגדה של פסח פיסקא עבדים היינו."],["4442","126","<b>או\"א שהלבישו לזרועות דא\"א</b>: ראה פע\"ח שער חה\"מ שכ\"א, פ\"ז. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה צאינה וראינה הערה 27."],["4443","127","<b>מה הוא רחום</b>: ראה לקו\"ת פינחס פ, ג. שבת קלג, ב. ספרי עקב יא, כב."],["4444","128","<b>רחום הוא התכללות דחו\"ג</b>: ראה ביאוה\"ז תרומה נ, ג. תו\"ח בראשית מ, א ובהערה 4. וארא ח\"א פה, ד. וש\"נ."],["4445","129","<b>התכללות. . תיקון דבתהו לא הי' התכללות</b>: ראה תו\"א בשלח סה, ד. תו\"ח בראשית מא, א הערה 5. שמות ח\"א מד, ג ואילך. לעיל ח\"א (בחלק המאמרים) המשך מצה זו פ\"נ."],["4446","130","<b>לא גבה לבי ולא רמו עיני</b>: תהלים קלא, א."],["4447","131","<b>אם לא שויתי ודוממתי</b>: תהלים קלא, ב. ראה גם סהמ\"צ להצ\"צ ע' קח. אוה\"ת פסח כרך ב ע' תמד."],["4448","132","<b>כי עני ואביון אני</b>: תהלים פו, א. ראה גם סה\"מ תרל\"ח ע' נד. וש\"נ."],["4449","133","<b>ואנכי תולעת ולא איש</b>: תהלים כב, ז."],["4450","134","<b>מעדן עצמו כתולעת</b>: ראה מוע\"ק טז, ב. ראה גם לקו\"ת חוקת נז, א ואילך."],["4451","135","<b>ונפשי כעפר. . פתח לבי בתורתך</b>: ברכות יז, א. סיום תפלת העמידה (אלקי נצור). ראה מאמרי אדה\"ז תקס\"ח ח\"א ע' קכח. מאמרי אדה\"א קונטרסים ע' שפא. וש\"נ. שערי אורה ע' לו ובהערה 3."]]],[2000480435,"לכל תהי' הו\"ע הביטל, וזהו דוד שהי' בבחי' ביטל א' כי לעולם חסדו, וה\"ז כמו משה שא' ונפלינו אני ועמך<sup data-n=\"4452\">136</sup>, שאפי' מבחי' ונפלינו<sup data-n=\"4453\">137</sup> ששם כחשיכא כאורה<sup data-n=\"4454\">138</sup> בב' כפין שלא די שהחשך שוה להאור אלא שגם האור שוה לחשך מ\"מ יהי' אני ועמך דוקא, וע\"ז א' דוד כי לעולם חסדו, שאפי' מבחי' חסדו יומשך בעולם, ונמצא בקשת משה אם<sup data-n=\"4455\">139</sup> ך\"ו הודו שא' דוד הם ענין אחד, וזהו משה עבדי<sup data-n=\"4456\">140</sup> ודוד עבדי<sup data-n=\"4457\">141</sup>, רק שבחי' משה עבדי הוא בחי' ואנחנו<sup data-n=\"4458\">142</sup> מ\"ה<sup data-n=\"4459\">143</sup> ודוד עבדי הוא בחי' דומם, אך באמת ה' בחכ' יסד ארץ וא\"כ ה\"ה ג\"כ בחי' מ\"ה לכן נק' שניהם עבדים.\n<b>וזהו</b> וילבש צדקה כשריון וכובע ישועה בראשו<sup data-n=\"4460\">144</sup>, כוב\"ע הוא ך\"ו ע\"ב<sup data-n=\"4461\">145</sup> והו\"ע חסד הוי'<sup data-n=\"4462\">146</sup> דא\"א דאית חסד דלבר וחסד דלגאו<sup data-n=\"4463\">147</sup> וכובע הוא בחי' חסד דלגאו וכדי שיומשך בחי' זו הוא ע\"י וילבש צדקה כשריון שהוא בחי' בכל מאדך<sup data-n=\"4464\">148</sup> וכמשנת\"ל<sup data-n=\"4465\">149</sup> שבצדקה יש הגבלה חומש וזהו המבזבז<sup data-n=\"4466\">151</sup> ומדה בינונית הוא מעשר<sup data-n=\"4467\">150</sup> אך ע\"י שנותן צדקה בלי הגבלה ה\"ז בחי' בכל מאדך דאפי' כשבא לבחי' מאד שלו<sup data-n=\"4468\">152</sup> הרי צריכים לבחי' חסד ה' שיעורר<sup data-n=\"4469\">153</sup> בחי' מאד העליון וכמו\"כ כשנותן צדקה בלי הגבלה נמשך בחי' חסד ה' דהצמצום הוא רק לגבינו אבל לגבי א\"ס אינו שייך צמצום. וזהו אריב\"ל הנהו ך\"ו הודו כנגד מי אמרן דוד, כנגד ך\"ו דור שהי' נזונין מחסדו שבלי גבול דכמה א\"א לפניו, וע\"ז אמר דוד ך\"ו הודו שגם עתה יומשך בחי' זו לכן א' דברי' שאחר מ\"ת ג\"כ, ופתח בהודאה הודו לה'<sup data-n=\"4470\">154</sup> שהוא בחי'",[["4452","136","<b>ונפלינו אני ועמך</b>: תשא לג, טז."],["4453","137","<b>שאפי' מבחי' ונפלינו</b>: ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה כי הנה יוצר הרים בסופה ובהנסמן שם."],["4454","138","<b>כחשיכא כאורה</b>: תהלים קלט, יב. ראה לקו\"ת צו יב, א. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה כי הנה יוצר הרים ובהערה 30."],["4455","139","<b>אם</b>: כ\"ה בכ\"מ — ראה גם סה\"מ תרל\"ח ע' ה. וש\"נ."],["4456","140","<b>משה עבדי</b>: יהושע א, ב. ז. מלאכי ג, כב. ראה בהערה הבאה."],["4457","141","<b>ודוד עבדי</b>: שמואל-ב ג, יח. ועוד. ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו פרק ג\"ל."],["4458","142","<b>ואנחנו</b>: ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה הנה אנכי כורת ברית ובהערה 29."],["4459","143","<b>ואנחנו מ\"ה</b>: בשלח טז, ז. ח. ראה גם לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח ספכ\"א הערה 593."],["4460","144","<b>וילבש צדקה כשריון וכובע ישועה בראשו</b>: ישע' נט, יז."],["4461","145","<b>כובע הוא ך\"ו ע\"ב</b>: ראה מאו\"א מערכת כובע סי\"א. (לעיל בחלק המאמרים) מאמר ד\"ה עשה צדקה ומשפט על יד הערה 107 ואילך."],["4462","146","<b>חסד הוי'</b>: שמואל-א כ, יד. תהלים לג, ו."],["4463","147","<b>חסד דלבר וחסד דלגאו</b>: ראה זהר אד\"ר נשא קלג, ב."],["4464","148","<b>בכל מאדך</b>: ע\"פ ואתחנן ו, ה."],["4465","149","<b>וכמשנת\"ל</b>: בהנחה ד\"ה עשה צדקה ומשפט."],["4466","151","<b>המבזבז</b>: כתובות סז, סע\"ב. ראה גם לעיל הנחה ד\"ה עשה צדקה ומשפט ובהערה 93."],["4467","150","<b>שבצדקה. . חומש. . מעשר</b>: ראה שו\"ע יו\"ד רסרמ\"ט. אגה\"ק ס\"י. מאמרי אדה\"א הנחות תקע\"ז ע' ס. סה\"מ תש\"י ע' 177 ובהערה לשם."],["4468","152","<b>בכל מאדך. . מאד שלו</b>: ראה גם לעיל ח\"א (בחלק ההנחות) הנחה ד\"ה תכון תפלתי קטורת לפניך ובהערה 30."],["4469","153","<b>צריכים לבחי' חסד ה' שיעורר</b>: ראה גם לקו\"ת שמע\"צ פג, ב. שה\"ש יב, א. סה\"מ תרכ\"ז ס\"ע שצד ואילך. וש\"נ."],["4470","154","<b>הודו לה'</b>: תהלים קלו, א."]]],[2000480436,"ביטל ועי\"ז ממשיכים בחי' חסד הוי', וזה כי לעולם חסדו שאפי' עתה בהעולם יומשך בחי' חסד הוי' שבלי גבול כו'.",[]],[2000480437,"<h3>אשריכם זרעי על כל מים</h3>\n<b>ש\"פ ויצא תאמ\"ר לפ\"ק</b>\n<b>אשריכם</b> זרעי על כל<sup data-n=\"4471\">1</sup> מים<sup data-n=\"4472\">2</sup>, ואמרז\"ל אין זריעה אלא צדקה<sup data-n=\"4473\">3</sup> שנא' זרעו לכם צדקה וקצרו לפי חסד<sup data-n=\"4474\">4</sup>, וצ\"ל מהו\"ע חסד זה והלא יש ב' מדרי' בחסד וכמ\"ש בזהר אית חסד ואית חסד<sup data-n=\"4475\">5</sup> ועל איזה חסד הכוונה כאן, והנה כתי' זורע צדקות מצמיח ישועות<sup data-n=\"4476\">6</sup> והו\"ע מ\"ש וכובע ישועה בראשו<sup data-n=\"4477\">7</sup> ונת\"ל<sup data-n=\"4478\">8</sup> כוב\"ע ך\"ו ע\"ב<sup data-n=\"4479\">9</sup>, ך\"ו הוא מספר ש' הוי'<sup data-n=\"4480\">10</sup> וע\"ב<sup data-n=\"4481\">11</sup> הוא חס\"ד שהוא בגימ' ע\"ב<sup data-n=\"4482\">12</sup> וא\"כ ה\"ז חסד הוי'<sup data-n=\"4483\">13</sup> שנק' בזהר רב חסד<sup data-n=\"4484\">14</sup> ועז\"א ריב\"ל הנהו ך\"ו הודו<sup data-n=\"4485\">16</sup> כנגד מי כנגד ך\"ו דור שלא נתן להם את התורה וזן אותם בחסדו<sup data-n=\"4486\">15</sup> שנמשך להם מבחי' חסד ה' דכמה א\"א לפניו<sup data-n=\"4487\">17</sup>, ובקש דוד שגם עתה בב' אלפים תורה<sup data-n=\"4488\">18</sup> דכתי' ונתתי גשמיכם בעתם<sup data-n=\"4489\">19</sup> שגם גשמיות ההשפעה תלוי בתורה דאם מטיבים מעשיהם<sup data-n=\"4490\">20</sup> כו' ומ\"מ יומשך בחי' חסד ה'",[["4471","1","<b>אשריכם זרעי על כל מים</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב מחלקו הראשון<sup data-n=\"e308\">*</sup> של מאמר ד\"ה והנה כובע שנדפס לעיל בחלק המאמרים. וש\"נ."],["4472","2","<b>אשריכם זרעי על כל מים</b>: ישעי' לב, כ."],["4473","3","<b>אין זריעה אלא צדקה</b>: ראה תד\"א זוטא פ\"א."],["4474","4","<b>זרעו לכם צדקה וקצרו לפי חסד</b>: הושע י, יב [ושם: לצדקה. קצרו — ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה הנה אנכי כורת ברית ובהערה 40]."],["4475","5","<b>אית חסד ואית חסד</b>: זהר ויחי ריט, א. ראה אגה\"ק ס\"י. סי\"ג. מאמרי אדה\"א ויקרא ח\"ב ע' תשעז. וש\"נ."],["4476","6","<b>זורע צדקות מצמיח ישועות</b>: נוסח ברכת יוצר."],["4477","7","<b>וכובע ישועה בראשו</b>: ישעי' נט, יז."],["4478","8","<b>ונת\"ל</b>: הנחה ד\"ה עשה צדקה ומשפט וד\"ה אריב\"ל הנהו ך\"ו הודו (ובמקבילו בחלק המאמרים שם)."],["4479","9","<b>כובע ך\"ו ע\"ב</b>: ראה מאו\"א מערכת כובע סי\"א. (לעיל בחלק המאמרים) מאמר ד\"ה עשה צדקה ומשפט על יד הערה 107 ואילך."],["4480","10","<b>ך\"ו הוא מספר ש' הוי'</b>: ראה שו\"ע (ואדה\"ז) או\"ח הל' ציצית סכ\"ד, ס\"ה (ס\"ז). לעיל שם הערה 108."],["4481","11","<b>וע\"ב</b>: שם ע\"ב — ראה לעיל הנחה ד\"ה עשה צדקה ומשפט ובהערה 83."],["4482","12","<b>חס\"ד שהוא בגימ' ע\"ב</b>: ראה זהר רע\"מ תצא רעו, ב. הקדמת ת\"ז ח, סע\"ב. י, ריש ע\"ב. תכ\"ב סז, א. פרדס שעה\"כ שכ\"ג, פ\"ח מערכת חסד. לקו\"ת להאריז\"ל שמות (ג, ד) עה\"פ וירא ה' כי סר לראות."],["4483","13","<b>חסד הוי'</b>: שמואל-א כ, יד. תהלים לג, ו."],["4484","14","<b>חסד הוי'. . רב חסד</b>: ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה עשה צדקה ומשפט ובהערה 114."],["4485","16","<b>ך\"ו הודו</b>: תהלים פרק קלו."],["4486","15","<b>ריב\"ל הנהו ך\"ו הודו. . וזן אותם בחסדו</b>: ראה פסחים קיח, א."],["4487","17","<b>דכמה א\"א לפניו</b>: אבות פ\"ה, מ\"ב."],["4488","18","<b>בב' אלפים תורה</b>: ע\"ז ט, א."],["4489","19","<b>ונתתי גשמיכם בעתם</b>: בחוקותי כו, ד."],["4490","20","<b>דאם מטיבים מעשיהם</b>: ראה ר\"ה יז, ב."],["e308","*","והנחת כ\"ק אדמו\"ר מהורש\"ב מחלקו השני של המאמר נמצא בהנחה ד\"ה למה קדמה שמע לוהי' אם שמוע שנדפס לאח\"ז."]]],[2000480438,"גם עכשיו, ודוקא דוד הי' בכחו לבקש בחי' זו שהי' בטל בתכלית וכמ\"ש לא גבה לבי ולא רמו עיני<sup data-n=\"4491\">21</sup> כו' וכתי' מרום וקדוש אשכן את דכה ושפל רוח<sup data-n=\"4492\">22</sup> שבחי' מרום וכמ\"ש ואתה מרום לעולם ה'<sup data-n=\"4493\">23</sup> אשכון את דכה כו' וזהו כובע ישועה בראשו, וכמו\"כ הוא לפי חסד שיומשך בחי' חסד ה', ועפ\"ז יובן עוד ענין א' דכוב\"ע בגימ' חנ\"ם<sup data-n=\"4494\">24</sup>, דהנה כתי' זכרנו את הדגה<sup data-n=\"4495\">25</sup> אשר נאכל במצרים חינם ואי' בספרי וכ\"פ רש\"י חנם בלא מצות ופי' המגיד ממעזריטש<sup data-n=\"4496\">26</sup> שהוא בחי' אתעדל\"ע שאין אתעדל\"ת מגעת שם, וצ\"ל והלא אמרז\"ל פליגי בה רב ושמואל<sup data-n=\"4497\">27</sup> כו' ומ\"ד עריות דכתי' חנם וא\"כ הרי דרשו זה על ההיפך כו'.\n<b>ולהבין</b> זה צלה\"ק תחילה מ\"ש בזהר ההפרש בין סט\"א לסט' דקדושה דסט\"א הוא במגנא וברקניא ולא עוד אלא דמפתה לו כו' וסט' דקדושה הוא בא באשתדלותא<sup data-n=\"4498\">28</sup> רב וסגי כפום חילי' והלואי דיזכה, וחשיב כאן ג' דברים<sup data-n=\"4499\">29</sup> בסט' דקדושה באשתדלותא רב וסגי שצ\"ל עבודה והלואי דיזכה, ובסט\"א חשיב ב' דברים א' במגנא וברקניא ב' ולא עוד דמפתה לו והוא גרוע יותר דמפתה לו וענש לי' לבר נש, והענין דהנה מ\"ש זכרנו כו' חנם טענו זאת יוצאי מצרים, ובמצרים הי' פרעה מלך מצרים, והוא הי' באותן ך\"ו דור שהיו נזונים בחסדו שנמשך להם מבחי' חסד ה' דא\"א, ופרע\"ה אותיות העור\"ף<sup data-n=\"4500\">30</sup> שקיבל מבחי' אחורים, ודוגמא לזה הוא מ\"ש גבי יעקב ויאבק איש עמו<sup data-n=\"4501\">31</sup> עד עלות השחר והוא בחי' מ\"ש אז יבקע כשחר אורך<sup data-n=\"4502\">32</sup> והו\"ע בקיעת החשך דבחי' ישת חשך סתרו<sup data-n=\"4503\">33</sup> וארוכתך מהרה תצמח היינו גילוים דא\"א<sup data-n=\"4504\">34</sup>, וזהו ויאבק איש עמו עד עלות השחר, והוא טעה בדמיונו דאבות הם המרכבה<sup data-n=\"4505\">35</sup> אברהם הוא מרכבה למדת החסד<sup data-n=\"4506\">36</sup> ויצחק מרכבה למדת הפחד<sup data-n=\"4507\">37</sup> ויעקב מרכבה למדת הת\"ת<sup data-n=\"4508\">38</sup>",[["4491","21","<b>לא גבה לבי ולא רמו עיני</b>: תהלים קלא, א."],["4492","22","<b>מרום וקדוש אשכון את דכא ושפל רוח</b>: ישעי' נז, טו [ושם: ואת — אבל כ\"ה גם בסה\"מ תרכ\"ז ע' קמג וע' רא. תרל\"ח ס\"ע נד]."],["4493","23","<b>ואתה מרום לעולם ה'</b>: תהלים צב, ט."],["4494","24","<b>דכוב\"ע בגי' חנ\"ם</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 2."],["4495","25","<b>זכרנו את הדגה</b>: בהעלותך יא, ה."],["4496","26","<b>ופי' המגיד ממעזריטש</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 8."],["4497","27","<b>פליגי בה רב ושמואל</b>: ראה יומא עה, א."],["4498","28","<b>בזהר ההפרש. . במגנא וברקניא. . באשתדלותא</b>: ראה זהר תרומה קכח, א. ראה גם (לעיל בחלק המאמרים) בהמאמר כאן פיסקא והנה בפע\"ח ובהנסמן שם."],["4499","29","<b>וחשיב כאן ג' דברים</b>: ראה גם בענין ג' דברים בזהר שם. בפיסקא הבאה. בהמאמר (כאן) שם ואילך (ובהנסמן שם)."],["4500","30","<b>ופרעה אותיות העורף</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן הערה 38."],["4501","31","<b>ויאבק איש עמו</b>: וישלח לב, כה."],["4502","32","<b>אז יבקע כשחר אורך</b>: ישעי' נח, ח. ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה בן פורת יוסף הא' בהערות 21-22."],["4503","33","<b>ישת חשך סתרו</b>: תהלים יח, יב."],["4504","34","<b>וארוכתך מהרה תצמח. . דא\"א</b>: המשך הכתוב אז יבקע — ישעי' נח, ח. לקו\"ת צו ט, א."],["4505","35","<b>דאבות הם המרכבה</b>: ב\"ר פמ\"ז, ו. פפ\"ב, ו. ראה מאמרי אדה\"א דברים ח\"א ע' רטו. וש\"נ. תו\"ח נח מט, ד ובהערה 42. משפטים ח\"ב ש, ג. סה\"מ תרכ\"ט ע' רלח. וש\"נ."],["4506","36","<b>אברהם הוא מרכבה למדת החסד</b>: ראה זהר בראשית מז, ב. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקפ ובהנסמן במ\"מ לשם."],["4507","37","<b>ויצחק מרכבה למדת הפחד</b>: ראה לעיל הנחה ד\"ה יונתי ובהערות 131-132."],["4508","38","<b>ויעקב מרכבה למדת הת\"ת</b>: ראה זהר סתרי תורה ויצא קנז, ב. ח\"ג תוספות שב, א. לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול ובהערה 16."]]],[2000480439,"וזלעו\"ז עשה אלקים<sup data-n=\"4509\">39</sup> וכמו\"כ יש אדם בליעל<sup data-n=\"4510\">40</sup> והוא כדרך המלחמה, אבל כתי' אח\"כ וירא כי לא יכול לו<sup data-n=\"4511\">41</sup> דיעקב הוא יו\"ד עקב<sup data-n=\"4512\">42</sup> שהוא בחי' חכ' וכתי' וימותו ולא בחכ'<sup data-n=\"4513\">43</sup> (וזהו וירא שהוא בחי' חכ'<sup data-n=\"4514\">44</sup> ), והנה אמרז\"ל ע\"פ ויאבק מלמד שהעלו אבק עד תחת כסא הכבוד<sup data-n=\"4515\">45</sup>, דיש אבק ואפר ועפר, עפר הוא שיש בו צמיחה אף שאין זורעין בו וכידוע שיש זרעונים ועשבים שצומחים אף שאין זורעין אותם<sup data-n=\"4516\">46</sup>, ואפר יש בו צמיחה כשזורעים בו ולכן הוא כשר לכסוי הדם<sup data-n=\"4517\">47</sup> דכתי' וכסהו בעפר<sup data-n=\"4518\">48</sup> והוא מפני שגם באפר יש צמיחה, ואבק אין בו צמיחה כלל<sup data-n=\"4519\">49</sup>, וזהו שהעל\"ו אבק עד תחת כסה\"כ והוא מצד המברר והמתברר<sup data-n=\"4520\">50</sup> דכמו שיש בירורים דלעו\"ז דז\"א דקדושה כמו\"כ יש בירורים דלעו\"ז דמל' דקדושה (ובפ\"א<sup data-n=\"4521\">51</sup> אבק הוא מל' דלעו\"ז<sup data-n=\"4522\">52</sup> והעלו אותה עד כסה\"כ שהוא מל'<sup data-n=\"4523\">53</sup> דקדושה, וכן עכשיו יש מלחמת עמלק לדור דור<sup data-n=\"4524\">54</sup> ) וכמו\"כ יש עכשיו הבירור במצות וכמ\"ש מי מנה עפר יעקב<sup data-n=\"4525\">55</sup> הם מצות התלוים בעפר ויש מצות התלוים באפר<sup data-n=\"4526\">56</sup>",[["4509","39","<b>וזלעו\"ז עשה אלקים</b>: ע\"פ קהלת ז, יד. ראה גם סה\"מ תרל\"ח ע' קלד."],["4510","40","<b>אדם בליעל</b>: משלי ו, יב."],["4511","41","<b>וירא כי לא יכול לו</b>: וישלח לב, כו. ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ערבים עלי דברי דודיך על יד [וב]הערה 19 ואילך."],["4512","42","<b>דיעקב הוא יו\"ד עקב</b>: ע\"ח שער סדר אצי' ש\"ג, פ\"ב. ראה תו\"א ר\"פ ויצא. מאמרי אדה\"א דברים ח\"ג ע' תתמז. וש\"נ. תו\"ח שמות ח\"א יח, ב. וש\"נ."],["4513","43","<b>וימותו ולא בחכ'</b>: איוב ד, כא [ושם: ימותו]. ראה גם לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח פי\"ג ובהערה 261."],["4514","44","<b>וירא. . חכ'</b>: ראה גם שערי אורה מ, א ובהנסמן במ\"מ לשם."],["4515","45","<b>שהעלו אבק. . כסא הכבוד</b>: ראה חולין צא, א."],["4516","46","<b>עפר. . צמיחה. . זרעונים ועשבים. . שאין זורעין אותם</b>: ראה גם מאמרי אדה\"ז תקס\"ו (כאן) ע' פט. אגה\"ק ס\"כ (קלב, ב). לקו\"ת בחוקותי מט, ג. נצבים נ, ד (ובסופו). תו\"א ויגש מד, ג."],["4517","47","<b>ואפר. . כשר לכסוי הדם</b>: ראה חולין פח, ב. תוד\"ה מצינו שם. שו\"ע יו\"ד הל' שחיטה סכ\"ח, סכ\"ג. תו\"א וישלח כו, רע\"ד."],["4518","48","<b>וכסהו בעפר</b>: אחרי יז, יג."],["4519","49","<b>ואבק אין בו צמיחה כלל</b>: בתו\"א שבהערה 47, וכן (לעיל בחלק המאמרים) בהמאמר כאן לא הובאה דוגמא זו."],["4520","50","<b>שהעל\"ו אבק. . המברר והמתברר</b>: ראה תו\"א שם."],["4521","51","<b>ובפ\"א</b>: ראה גם לעיל הנחה ד\"ה ואהבת את ה' אלקיך הא' ובהערה 74."],["4522","52","<b>אבק הוא מל' דלעו\"ז</b>: ראה תו\"א וישלח כו, ד: מל' דקליפה. מאמרי אדה\"ז תקס\"ו ע' פט. שע\"ת קטו, א: נוגה דאצי' ובהערה 11."],["4523","53","<b>כסה\"כ שהוא מל'</b>: ראה תו\"א שם. ש\"א כו, א ובהערה 11. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה גן נעול הב' קרוב לסופו."],["4524","54","<b>עכשיו יש מלחמת עמלק לדור דור</b>: בשלח יז, טז. ראה תו\"א תצוה פג, א."],["4525","55","<b>מי מנה עפר יעקב</b>: בלק כג, י. ראה פרש\"י שם. במד\"ר פ\"כ, יט. תנחומא בלק יב."],["4526","56","<b>מצות התלוים באפר</b>: לדוגמא (בנוסף לכיסוי הדם) אפר פרה<sup data-n=\"e309\">א</sup>־ אפר לכתובת קעקע<sup data-n=\"e310\">ב</sup>־ אפר לסוטה<sup data-n=\"e311\">ג</sup>־ אפר בראש חתנים<sup data-n=\"e312\">ד</sup>־ בתענית צבור<sup data-n=\"e313\">ה</sup>־ בערב תשעה באב<sup data-n=\"e314\">ו</sup>־ בתיקון חצות<sup data-n=\"e315\">ז</sup>.\n\n<b>א</b>  חוקת יט, ה ואילך.\n\n<b>ב</b>  מכות כא, א לדעת רב מלכיאל.\n\n<b>ג</b>  סוטה טז, ב.\n\n<b>ד</b>  ב\"ב ס, ב.\n\n<b>ה</b>  תענית טו, א (במשנה).\n\n<b>ו</b>  שו\"ע או\"ח סתקנ\"ב, ס\"ו ברמ\"א.\n\n<b>ז</b>  משנת חסידים מסכת חצות פ\"ד, מ\"ב. סידור אדה\"ז סדר תיקון חצות."]]],[2000480440,"ויש מצות שהם באבק וכמארז\"ל ג' דברים אין אדם ניצול מהם בכל יום כו' אבק לה\"ר<sup data-n=\"4527\">57</sup> וצריכים לברר את זה ג\"כ וכ\"ש אבק ריבית שהוא חמור יותר.\n<b>והענין</b> דהנה במצות צ\"ל ג' דברים גוף ונפש וממון וזהו שאמרו על אברהם שהי' נדיב בין בנפשו בין בגופו בין בממונו<sup data-n=\"4528\">58</sup>, ובעבודה הו\"ע בכל לבבך ובכל נפשך ובכל מאדך<sup data-n=\"4529\">59</sup>, בכל לבבך הוא גוף דליבא פליג לכל שייפין<sup data-n=\"4530\">60</sup> שהוא שולח חיות לכל האברים וגם למוח נמשך מהלב, ובכל נפשך בכל כחות נפשו לתקן נפשו והוא מ\"ש כי הדם הוא הנפש<sup data-n=\"4531\">61</sup> ולא זו לבד וכמשית\"ל, ובכל מאדך פי' במשנה בכל ממונך<sup data-n=\"4532\">62</sup>, דמחטא אדה\"ר נפגמו דצח\"מ ג\"כ ואי' בכהאריז\"ל דנתפזרו ניצוצי נשמות ונפלו בדצח\"ם<sup data-n=\"4533\">63</sup> והאדם ע\"י עבודתו יכול לברר דצח\"ם, ועוד אי' בכהאריז\"ל דע\"י הבירורים נשלם הנפש האדם ג\"כ<sup data-n=\"4534\">64</sup>, והענין דמצות נתלבשו בדברים גשמים בדומם ג\"כ וכלליות המעשה נק' דומם לכן ע\"י עשיות המצות מברר בחי' נפש וע\"י לימוד התורה שעיקרו בדיבור מזכך בחי' רוח, וע\"י עיון התורה מזכך בחי' נשמה<sup data-n=\"4535\">65</sup> דאי' במדרש ה' שמות נק' לה נר\"ן ח\"י<sup data-n=\"4536\">66</sup>, ח\"י הם מקיפים ונר\"ן הם פנימים<sup data-n=\"4537\">67</sup> וע\"י תומ\"צ מזככי' אותם, והנה כסף וזהב הגשמים הם מתחתיות העשי' רק שהשמש פועל בהם כשמאירה במקום זה נעשה זהב<sup data-n=\"4538\">68</sup> ובמקום זה נעשה כסף<sup data-n=\"4539\">69</sup>, והם מיני מתכת שהוא דומם וכשלוקח המעות וקונה מהם מצוה הרי נתוסף על עצם המצוה שהיא<sup data-n=\"4540\">70</sup> רצה\"ע, והוא כמשנת\"ל שיש ניצוצי נשמות בדומם ג\"כ, ולכן מעות בל' הגמ' דמים<sup data-n=\"4541\">71</sup> דדמים תרתי משמע, הבירור דעצם הדומם וגם הבירור דהדם הוא הנפש<sup data-n=\"4542\">72</sup>, (בפ\"א ועוד זאת יש בדומם לבד מה שנמשך להם מקדושה להחיותם, יש בהם תוס' הארה מקדושה וכמ\"ש גבי יעקב ויקח מאבני המקום<sup data-n=\"4543\">73</sup> וישם מראשותיו שכל אבן אמר עלי",[["4527","57","<b>ג' דברים. . אבק לה\"ר</b>: ב\"ב קסד, סע\"ב ואילך."],["4528","58","<b>אברהם שהי' נדיב. . בממונו</b>: ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול ובהערה 12."],["4529","59","<b>בכל לבבך ובכל נפשך ובכל מאדך</b>: ואתחנן ו, ה."],["4530","60","<b>דליבא פליג לכל שייפין</b>: ראה זהר שלח קסא, ב. שע\"ת סט, ב הערה 12."],["4531","61","<b>כי הדם הוא הנפש</b>: פ' ראה יב, כג."],["4532","62","<b>ובכל מאדך. . בכל ממונך</b>: ואתחנן ו, ה. ברכות נד, א. ראה (לעיל בחלק המאמרים) מאמר ד\"ה ולהבין שרש ענין בחי' מזבח הפנימי ובהערה 102."],["4533","63","<b>דמחטא אדה\"ר. . בכהאריז\"ל. . נשמות ונפלו בדצח\"ם</b>: ראה רמ\"ז לזהר תרומה קכח, א. (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 55."],["4534","64","<b>דע\"י הבירורים נשלם הנפש האדם ג\"כ</b>: ראה רמ\"ז שם. ראה גם לעיל שם."],["4535","65","<b>המעשה. . נפש. . לימוד התורה. . רוח. . עיון. . נשמה</b>: ראה הערה שלפנ\"ז."],["4536","66","<b>ה' שמות נק' לה נר\"ן ח\"י</b>: ראה ב\"ר פי\"ד, ט. הנסמן במאמרי אדה\"א דברים ח\"ב ע' תכח."],["4537","67","<b>ח\"י הם מקיפים ונר\"ן הם פנימים</b>: ראה ע\"ח שער פנימיות וחיצוניות ש\"מ, ד\"א. ד\"י. שעה\"י קכח, ב ובהערה 51. מאמרי אדה\"א קונטרסים ע' רנג. וש\"נ."],["4538","68","<b>שהשמש. . נעשה זהב</b>: ראה זהר ויחי רמט, סע\"ב ואילך פקודי רלו, ב."],["4539","69","<b>שהשמש. . נעשה כסף</b>: כ\"ה בגוכתי\"ק. (לעיל בחלק המאמרים) בהמאמר כאן לא הובאה דוגמא זו. ולהעיר מאור יקר — כרך יא — פ' פקודי ס\"ה (קס, סע\"א)."],["4540","70","<b>שהיא</b>: אולי השי\"ן נמחק, וכתוב היא."],["4541","71","<b>מעות בל' בגמ' דמים</b>: מעשר שני פ\"א, מ\"ה. שבת יט, א."],["4542","72","<b>דהדם הוא הנפש</b>: פ' ראה יב, כג."],["4543","73","<b>ויקח מאבני המקום</b>: ויצא כח, יא."]]],[2000480441,"יניח צדיק את ראשו<sup data-n=\"4544\">74</sup> הרי הי' בהם הרגש, וכן אבני בהמק\"ד היו מתרחבים ומתצמצמים<sup data-n=\"4545\">75</sup> דזה שייך בצומח הרי הי' בהם הרגש, וכ\"כ בנחמי' שא' סנבלט היחיו האבנים מערמות עפר<sup data-n=\"4546\">76</sup> והמה שרופות, דנשרפו בשריפות ירושלים וא' בהם היחיו הרי שייך בהם חיות, וכשלוקח מצוה מדומם הרי מתוסף הארת הקדושה שבהדומם) וזהו שכ' בזהר שלא יהי' במגנא וברקניא דיש מצות שע\"פ תורה הנגלית יוצא י\"ח בשל חבירו, כמו תפילין שיוצאים י\"ח בתפילין שאולים<sup data-n=\"4547\">77</sup> (בפ\"א וכן לולב במתנה ע\"מ להחזיר<sup data-n=\"4548\">78</sup> ) ובזהר אי' שאסור במגנא וצריך להוציא ע\"ז מעות, וברקניא לכאו' הוא יתור לשון אך הכוונה כשצריך לקנות איזה מצוה יכין מתחילה המעות ע\"ז דההכנה הוא ג\"כ ענין וכמ\"ש וביום השישי והכינו<sup data-n=\"4549\">79</sup>.\n<b>וזהו</b> שא' במגנא וגם לא ברקניא היינו שלא יהי' ריקן מזה מקודם, וה\"ז כמארז\"ל הדור מצוה עד שליש<sup data-n=\"4550\">80</sup>, הדר הוא בתפארת<sup data-n=\"4551\">81</sup>, ומצוה הוא מצות המלך<sup data-n=\"4552\">82</sup> שהוא במל'<sup data-n=\"4553\">83</sup>, וזהו הדור מצוה עד שליש, שעי\"ז נמשך משליש האמצעי דת\"ת במל' וכשמהדר יותר משליש זוכה שיומשך גם משליש העליון דת\"ת במל', וזהו מ\"ש איש כמתנת ידו<sup data-n=\"4554\">84</sup> כברכת ה' אלקיך אשר נתן לך, מתנת ידו היינו הדור מצוה שהוא מתנה דכל מצוה יש לה שיעור עד כמה הוא החיוב וכשמהדר עוד עד שליש ה\"ז מתנה, כברכת ה' אלקיך אשר נתן לך היינו כשמהדר יותר נמשך גם משליש העליון דת\"ת במל', וזהו שמזהיר כ\"כ בזהר ע\"ז וא' אסור כו' וע\"פ גליא דתורה אי\"ז חיוב כלל, שעי\"ז ממשיכים ממדרי' גבוה, ועפ\"ז יובן משארז\"ל מ\"ד עריות דכתי' חנם וכן בספרי אמרו חנם בלא מצות הכוונה שע\"י מצוה אינו יכולים לבוא לבחי' זו, רק ע\"י בחי' בכל מאדך בכל ממונך שלא בהגבלת חומש או מעשר, ועי\"ז רחבה מצותך מאד<sup data-n=\"4555\">85</sup> שמצות נעשים כלים רחבים לקבל מאד העליון שבלי גבול דהנה מאד\"ך כתי' היינו מאד האדם<sup data-n=\"4556\">86</sup> שאין ערוך לו לגבי עולם שלמעלה ממנו וכ\"ש לגבי מאד העליון אך בחסד ה' עלינו כשהוא מבקש אינו מבקש אלא לפי כוחן<sup data-n=\"4557\">87</sup> וכמ\"ש שור או כשב<sup data-n=\"4558\">88</sup> כו' ועי\"ז מעורר מאד העליון שהוא באמת בלי גבול.",[["4544","74","<b>עלי יניח צדיק את ראשו</b>: רש\"י ויצא שם. חולין צא, ב."],["4545","75","<b>אבני בהמק\"ד היו מתרחבים ומתצמצמים</b>: ראה גם אבות פ\"ה, מ\"ה. ערובין כא, א."],["4546","76","<b>היחיו האבנים מערמות עפר</b>: נחמי' ג, לד [ושם: את האבנים. . העפר]."],["4547","77","<b>שיוצאים י\"ח בתפילין שאולים</b>: ראה שו\"ע אדה\"ז הל' תפילין סכ\"ה, סל\"ה."],["4548","78","<b>לולב במתנה ע\"מ להחזיר</b>: ראה שו\"ע או\"ח הל' לולב סתרנ\"ח, ס\"ד."],["4549","79","<b>וביום השישי והכינו</b>: בשלח טז, ה [ושם: והי' ביום]."],["4550","80","<b>הדור מצוה עד שליש</b>: ב\"ק ט, ב."],["4551","81","<b>הדר הוא בתפארת</b>: רמ\"ז תרומה כאן."],["4552","82","<b>ומצוה. . מצות המלך</b>: ראה אסתר ג, ג. מאמרי אדה\"א שמות ח\"א ע' יא. וש\"נ. נ\"ך ע' רלה. ש\"א ע' נו."],["4553","83","<b>ומצוה. . במל'</b>: ראה רמ\"ז כאן. לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 1702."],["4554","84","<b>איש כמתנת ידו</b>: פ' ראה טז, יז."],["4555","85","<b>רחבה מצותך מאד</b>: תהלים קיט, צו. ראה אגה\"ק סי\"ז. (לעיל בחלק המאמרים) בהמאמר כאן שולי הגליון הד'."],["4556","86","<b>מאד\"ך. . מאד האדם</b>: ראה גם תו\"א מקץ לט רע\"ד. לעיל ח\"א (בחלק ההנחות) הנחה ד\"ה תכון תפלתי קטורת לפניך ובהערה 30."],["4557","87","<b>כשהוא מבקש. . כוחן</b>: ראה במדב\"ר פכ\"א, כא. לקו\"ש ר\"ה כרך ט ע' 452 בהערה."],["4558","88","<b>שור או כשב</b>: אמור כב, כז."]]],[2000480442,"<b>וביאור</b> הענין דהנה כתי' חנון ורחום ה' א\"א וגדל חסד<sup data-n=\"4559\">89</sup> וכתי' ה' רחום וחנון<sup data-n=\"4560\">90</sup>, והענין דהנה הוי' הוא ל' מהווה<sup data-n=\"4561\">91</sup> אך הוא הי' הוה ויהי' כאחד<sup data-n=\"4562\">92</sup> וא\"ז מושג לנבראים דנברא הוא מוגבל בזמן שהוא ג\"כ מחודש<sup data-n=\"4563\">93</sup> והי' הוה ויהי' הם מרוחקי' זמ\"ז שהוא עבר הוה ועתיד, אף שהוא עיקר ההתהוות מ\"מ ענין ההתהוות הוא כמ\"ש יהללו שם הוי' כי הוא צוה ונבראו<sup data-n=\"4564\">94</sup> ולא ברא כמ\"ש בראשית ברא אלקי'<sup data-n=\"4565\">95</sup> שהוא התלבשות כח הפועל<sup data-n=\"4566\">96</sup> בנפעל<sup data-n=\"4567\">97</sup>, משא\"כ כאן כתי' ונבראו בדרך מאיליו וממילא<sup data-n=\"4568\">98</sup>, וזהו ה' רחום וחנון וחנון ורחום ה' וה\"ז ההפרש בין אב הרחמן לאב הרחמים<sup data-n=\"4569\">99</sup>, אב הרחמן שאומרים בנוסח דברכת ק\"ש היינו רחמים דסדר השתל', וזהו ה' רחום וחנון שמשם ה' נמשך שיהי' רחום וחנון, ומ\"ש רחום וחנון ה' היינו רחמים שלמעלה מסדר השתל' והו\"ע רחמים גדולים דכתי' ע\"ז לע\"ל ברחמים גדולים אקבצך<sup data-n=\"4570\">100</sup> והם רחמים פשוטים ור\"ר וזהו מ\"ש בעשי\"ת במוספים ובמנחה דשבת ובנעילה אב הרחמים שלמעלה מסדר השתל' ומזה נמשך שיהי' הוי' יוד צמצום ה' התפשטות ו' המשכה<sup data-n=\"4571\">101</sup>, וכמ\"ש בע\"ח כשעלה ברצונו הפשוט להיטיב לברואיו<sup data-n=\"4572\">102</sup> ואח\"כ נעשה הצמצום ותחלה הי' ההטבה שהוא בחי' רחמים ומבחי' זו נמשך להיות נושא עון ועובר על פשע<sup data-n=\"4573\">103</sup> דמצד א\"ס אם חטאת מה תפעל<sup data-n=\"4574\">104</sup> בו ורבו פשעיך מה תעשה לו אם צדקת מה תתן לו<sup data-n=\"4575\">105</sup> ומה מידך יקח<sup data-n=\"4576\">106</sup>, וכחשיכה כאורה<sup data-n=\"4577\">107</sup> בב' כפי\"ן",[["4559","89","<b>חנון ורחום ה'. . חסד</b>: תהלים קמה, ח."],["4560","90","<b>ה' רחום וחנון</b>: תשא לד, ו [בדילוג]."],["4561","91","<b>הוי' הוא ל' מהווה</b>: ראה זהר רע\"מ פינחס רנז, סע\"ב. (לקמן בחלק ההנחות) הנחה ד\"ה ביום השמיני עצרת ובהערה 13."],["4562","92","<b>הוי'. . הי' הוה ויהי' כאחד</b>: ראה שער היחוד והאמונה פ\"ז. תו\"ח מקץ ריט, ד הערה 62."],["4563","93","<b>בזמן שהוא ג\"כ מחודש</b>: ראה סידור שער הק\"ש עה, סע\"ד בשם הה\"מ. שער היחוה\"א פ\"ז ובמ\"מ, הגהות והע\"ק שם ע' שעה. מאמרי אדה\"א דברים ח\"ג ע' תשצג. וש\"נ."],["4564","94","<b>יהללו. . צוה ונבראו</b>: תהלים קמח, ה [ושם: את שם]. ראה סה\"מ תרל\"ג ח\"ב ע' תלא. וש\"נ. לקמן הערה 98."],["4565","95","<b>בראשית ברא אלקי'</b>: בראשית א, א."],["4566","96","<b>אלקי'. . כח הפועל בנפעל</b>: ראה גם לקו\"ת בחוקותי מט, ב. מאמרי אדה\"ז תקס\"ז ע' רי. ש\"א לו, א. פח, ב. פט, ב."],["4567","97","<b>כח הפועל בנפעל</b>: בלקו\"ת שלח מז, א: בספרים. ראה הנסמן במ\"מ לשם. ספר הישר (לר\"ת ) סוף ש\"ג."],["4568","98","<b>ונבראו בדרך מאיליו וממילא</b>: ראה גם לקו\"ת שה\"ש יד, ג. (לעיל בחלק המאמרים) מאמר ד\"ה ביום השמיני עצרת ובהערה 12. לעיל הערה 94."],["4569","99","<b>ההפרש בין אב הרחמן לאב הרחמים</b>: ראה לקו\"ת ר\"ה סב, ד. נשא כג, א. שה\"ש י, סע\"ג ואילך. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ישקני מנשיקות פיהו ובהערה 14."],["4570","100","<b>ברחמים גדולים אקבצך</b>: ישעי' נד, ז [ושם: וברחמים — אבל כ\"ה גם לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח ובהערה 518]."],["4571","101","<b>הוי' יוד צמצום ה' התפשטות ו' המשכה</b>: ראה אגה\"ת פ\"ד. סה\"מ תרל\"ח ע' קו. וש\"נ."],["4572","102","<b>וכמ\"ש בע\"ח כשעלה ברצונו הפשוט להיטיב לברואיו</b>: ראה דרוש עגו\"י ש\"א, ענף ב (כשעלה ברצונו הפשוט). שער הכללים בתחילתו (להיטיב לברואיו)."],["4573","103","<b>נושא עון ועובר על פשע</b>: מיכה ז, יח."],["4574","104","<b>אם חטאת מה תפעל בו</b>: איוב לה, ו."],["4575","105","<b>אם צדקת מה תתן לו</b>: איוב שם, ז."],["4576","106","<b>ומה מידך יקח</b>: סיום הכתוב אם צדקת [ושם: או מה — ראה לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ויהי בימי אחשורוש הערה 19]."],["4577","107","<b>וכחשיכה כאורה</b>: תהלים קלט, יב. ראה לקו\"ת צו יב, א. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה כי הנה יוצר הרים ובהערה 30."]]],[2000480443,"דלא די דהאור שוה לחשך אלא שגם החשך שוה שכל נהוראין מתחשכאין קמי'<sup data-n=\"4578\">108</sup>, ולכן נמשך משם להיות נושא עון ועובר על פשע, ומ\"ש לשארית נחלתו ולא לכל נחלתו, למי שמשים עצמו כשריים<sup data-n=\"4579\">109</sup> היינו שיהי' כלי לקבל בחי' זו, אבל מצד קמי' אינו נוגע כלל.\n<b>וזה</b> חנם בלא מצות שאין אתעדל\"ת דמצות מגעת לשם דמה איכפת לו להקב\"ה אם שוחט מן העורף או אם שוחט מן הצואר לא נתנו המצות אלא לצרף בהם את הבריות<sup data-n=\"4580\">110</sup>, בריות הם נשמות דבי\"ע, ולצר\"ף את הבריות היינו לברר הניצוצות שנת\"ל, אבל לגבי א\"ס אינו נוגע כלל, דמצות הם מצות המלך וכמו מלך שגוזר אומר שיהי' באופן זה דוקא ולא באופן אחר, כמו\"כ מצות נק' רמ\"ח פקודי\"ן<sup data-n=\"4581\">111</sup> שהוא פקודה בדקדוקי' וע\"י א\"א להמשיך בחי' חסד ה' שבלי גבול, וזהו חנם בלא מצות, וכדי להמשיך בחי' זו העיקר הוא ע\"י תפלה שהו\"ע ביטל וכמ\"ש ואל זה אביט אל עני ונכה רוח<sup data-n=\"4582\">112</sup> דוקא, שאפי' כשלומד לא יחזיק טיבותא לנפשי' שאם מחזיק טובה לעצמו הגם שא\"א לומר שהוא כמו שאינו, אך ה\"ז שיוצא עצם חיוב לימוד התורה, אבל באמת א\"צ להחזיק טובה לעצמו כלל, וכמו שא' דוד ע\"ע אם לא שויתי ודוממתי<sup data-n=\"4583\">113</sup> שהי' בבחי' דומם וא' ע\"ע אנכי תולעת ולא איש<sup data-n=\"4584\">114</sup> והמשל הוא שבעת עסקו בתורה מעדן עצמו כתולעת<sup data-n=\"4585\">115</sup> וא\"כ למד תורה ומ\"מ אמר שלא גבה לבי ולא רמה<sup data-n=\"4586\">116</sup> עיני ולא הלכתי בגדולות כו' אם לא שויתי ודוממתי שהי' בטל בתכלית, וזהו ונפשי כעפר לכל תהי' פתח לבי בתורתך<sup data-n=\"4587\">117</sup> דאורייתא מחכ' נפקית<sup data-n=\"4588\">118</sup> וכדי שיהי' פתיחה בתורה שיאיר מבחי' ורב חסד הוא ע\"י ונפשי כעפר לכל תהי' שהו\"ע הביטל, וענין התפלה העיקר כריעות והשתחואות<sup data-n=\"4589\">119</sup> וה\"ז כמו מלך מצד עוצם",[["4578","108","<b>שכל נהוראין מתחשכאין קמי'</b>: ראה זהר בראשית כג, א."],["4579","109","<b>לשארית נחלתו ולא לכל נחלתו. . כשריים</b>: מיכה ז, יח. ר\"ה יז סע\"א ואילך."],["4580","110","<b>דמה איכפת. . לצרף בהם את הבריות</b>: ראה תנחומא שמיני ז-ח. ב\"ר רפמ\"ד. אוה\"ת שמיני ע' נב ואילך. המשך מים רבים תרל\"ו ע' קטו. סה\"מ תרל\"ח ע' מח ואילך. לקו\"ש אבות כרך יז ע' 415 הערה 53. שופטים כרך יט ע' 182 הערה 42."],["4581","111","<b>רמ\"ח פקודי\"ן</b>: ראה לעיל הנחה ד\"ה יונתי בחגוי הסלע הערה 77."],["4582","112","<b>ואל זה אביט. . ונכה רוח</b>: ישעי' סו, ב."],["4583","113","<b>אם לא שויתי ודוממתי</b>: תהלים קלא, ב. ראה גם סהמ\"צ להצ\"צ ע' קח. אוה\"ת פסח כרך ב ע' תמד."],["4584","114","<b>אנכי תולעת ולא איש</b>: תהלים כב, ז [ושם: ואנכי — ראה גם (לקמן בחלק ההנחות] הנחה ד\"ה שובה ישראל הא' על יד הערה 113. לעיל ח\"א (בחלק ההנחות] הנחה ד\"ה וביום הביכורים על יד הערה 79."],["4585","115","<b>מעדן עצמו כתולעת</b>: ראה מוע\"ק טז, ב. ראה גם לקו\"ת חוקת נז, א ואילך."],["4586","116","<b>רמה</b>: לעיל על יד הערה 21: רמו."],["4587","117","<b>ונפשי כעפר. . פתח לבי בתורתך</b>: ברכות יז, א. סיום תפלת העמידה (אלקי נצור). ראה מאמרי אדה\"ז תקס\"ח ח\"א ע' קכח. מאמרי אדה\"א קונטרסים ע' שפא. וש\"נ. שערי אורה ע' לו ובהערה 3."],["4588","118","<b>דאורייתא מחכ' נפקית</b>: זהר בשלח סב, א. יתרו פה, א. רע\"מ משפטים קכא, א. קדושים פא, א. חוקת קפב, א. ואתחנן רסא, א."],["4589","119","<b>התפלה העיקר כריעות והשתחואות</b>: ראה תו\"א בראשית א, ג."]]],[2000480444,"רוממות המלך אינו שייך שיקרב אליו בתביעות ובקשות כ\"א בכריעות והשתחואות ועי\"ז יכול להגיע אפי' למדרי' גבוה.\n<b>וזהו</b> אשריכם זרעי על כל מים אין זריעה אלא צדקה, דכל המצות הם זריעה<sup data-n=\"4590\">120</sup> וכמ\"ש אור זרוע לצדיק<sup data-n=\"4591\">121</sup> ואמרז\"ל זרע הקב\"ה את התורה והמצות כדי להנחילם לישראל לעוה\"ב<sup data-n=\"4592\">122</sup> ולא הניח דבר שאין בו מצוה כו' אבל צדקה וגמ\"ח הרי אוכלין פירותיהן בעוה\"ז<sup data-n=\"4593\">123</sup>, דע\"י זריעה דצדקה מצמיח ישועה שהם ש\"ע נהורין (בפ\"א שע\"ה<sup data-n=\"4594\">124</sup> ותכ\"ד חזר וא' ש\"ע) וכמ\"ש וישע ה' אל הבל<sup data-n=\"4595\">125</sup>, וזהו לפי חסד דא\"א, ועפ\"ז יובן מה שפעמים אי' דהמצות הם להוסיף אורות באצי'<sup data-n=\"4596\">126</sup>, ופעמים מבואר שהמצות הם לברר בירורים למטה וכמו כאן, אך הענין דבצ\"ג המצות שעושים הוא להוסיף אורות באצי', אבל מי שלא נתברר עדיין אינו שייך שימשיך להוסיף כו' והוא בעצמו עדיין אינו מבורר, אבל ע\"י צדקה נמשך למטה (בפ\"ג דמשנת\"ל דלפעמים מבו' שהוא להוסיף כו' ופעמים מבו' שהוא לצורך הבירורים היינו בכל המצות ובזה יש הפרש בין צ\"ג למי שצריך לברר בירורים, אבל אין זריעה אלא צדקה שעי\"ז נמשך בחי' חסד דקשוט<sup data-n=\"4597\">127</sup> למטה) והיינו שיתן צדקה למעלה מהגבלת חומש ומעשר<sup data-n=\"4598\">128</sup> והוא בחי' בכל מאדך בכל ממונך ואין הכוונה על מ\"ש וחטאך בצדקה פרוק<sup data-n=\"4599\">129</sup> שע\"ז אינו שייך ליתן הגבלה דאפי' על צרכי הגוף מפזרים מעות הרבה כ\"ש על צרכי הנפש<sup data-n=\"4600\">130</sup>, אלא הכוונה על מי שהוא אדם נקי וע\"י הצדקה למעלה מההגבלה הוא בחי' בכל מאדך וממשיכים מבחי' ורב חסד וזהו זרעו לכם לצדקה ועי\"ז קצרו לפי חסד שיומשך בחי' חסד ה' למטה.",[["4590","120","<b>דכל המצות הם זריעה</b>: ראה גם תו\"א שמות נג, ג. לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 1821."],["4591","121","<b>אור זרוע לצדיק</b>: תהלים צז, יא."],["4592","122","<b>זרע הקב\"ה. . לעוה\"ב</b>: ראה במדב\"ר פי\"ז, ה. תנחומא שלח טו. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה בן פורת יוסף הא' ובהערה 47."],["4593","123","<b>צדקה וגמ\"ח. . פירותיהן בעוה\"ז</b>: ראה פאה בתחילתה. מאמרי אדה\"א דברים ח\"ג ע' תתמו. וש\"נ."],["4594","124","<b>ישועה ש\"ע נהורין. . שע\"ה</b>: ראה גם בענין ש\"ע נהורין (לעיל בחלק המאמרים) מאמר ד\"ה עשה צדקה ובהערות 41. *106. ובענין שע\"ה נהורין לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח פ\"ז ובהערה 121."],["4595","125","<b>וישע ה' אל הבל</b>: בראשית ד, ד."],["4596","126","<b>דהמצות הם להוסיף אורות באצי'</b>: ראה פע\"ח בהקדמה. ע\"ח שער מ\"ן ומ\"ד של\"ט, דרוש יא כלל טז. מאמרי אדה\"א דברים ח\"ד ע' א'תסז. וש\"נ. תו\"ח בשלח ח\"א קנו, ב הערה 312."],["4597","127","<b>חסד דקשוט</b>: זהר אד\"ר נשא קלג, ב. ראה לקו\"ת נשא כה, ג. שלח נא, א."],["4598","128","<b>צדקה. . חומש ומעשר</b>: ראה שו\"ע יו\"ד רסרמ\"ט. אגה\"ק ס\"י. מאמרי אדה\"א הנחות תקע\"ז ע' ס. סה\"מ תש\"י ע' 177 ובהערה לשם."],["4599","129","<b>וחטאך בצדקה פרוק</b>: דניאל ד, כד [ושם: וחטיך — ראה גם לעיל הנחה ד\"ה עשה צדקה ומשפט ובהערה 120]."],["4600","130","<b>וחטאך בצדקה פרוק. . על צרכי הנפש</b>: ראה אגה\"ת פ\"ג. אגה\"ק ס\"י (קטו, ב ואילך). וראה גם לקו\"ש בחוקותי כרך כז ע' 217 ואילך ובהנסמן שם."]]],[2000480445,"<h3>למה קדמה שמע לוהי' אם שמוע</h3>\n<b>ש\"פ וישלח תאמ\"ר לפ\"ק</b>\n<b>למה</b> קדמה שמע לוהי' אם שמוע<sup data-n=\"4601\">1</sup> כדי שיקבל עליו עול מל' שמים תחילה ואח\"כ יקבל עליו עול מצות<sup data-n=\"4602\">2</sup>, וצ\"ל מה שמחלק אותם לב' דברים ולכאו' הם דבר א', דעומ\"ש היינו עול מצות דעל כל מצוה מברכים אשר קדשנו במצותיו וצונו, וסור מרע ועשה טוב<sup data-n=\"4603\">3</sup> דהיינו קיום מ\"ע ומל\"ת היינו קבלת עומ\"ש, והנה צ\"ל תחילה שרש המצות הנה תרי\"ג מצות מבואר במ\"א שהם תרי\"ג ארחין (בפ\"א דגולגלתא<sup data-n=\"4604\">4</sup> דז\"א) ושרש שרשן מחד ארחי (בפ\"א<sup data-n=\"4605\">5</sup> דא\"א), וצ\"ל ההפרש בין תרי\"ג ארחין לחד ארחי, והענין דהנה כתי' מגיד דבריו ליעקב חוקיו ומשפטיו לישראל מה שהוא עושה אומר לישראל לעשות<sup data-n=\"4606\">6</sup> פי' מה שהוא עושה מצות הוא ע\"י מה שאומר לישראל לעשות, דהנה אמרז\"ל מנין דהקב\"ה מניח תפילין<sup data-n=\"4607\">7</sup> והקב\"ה מתעטף בציצית<sup data-n=\"4608\">8</sup> ואמרז\"ל הקב\"ה מצלי<sup data-n=\"4609\">9</sup> (בפ\"א מאי מצלי יה\"ר<sup data-n=\"4610\">10</sup> כו') הקב\"ה יושב ועוסק בתורה<sup data-n=\"4611\">11</sup>, וצ\"ל איך שייך מצות למעלה דהנה כל המצות הם שניתנו למטה צו אל בנ\"י<sup data-n=\"4612\">12</sup> דבר אל בנ\"י<sup data-n=\"4613\">13</sup> שיעשו מצוה זו כו', אבל למעלה מה שייך מצות.\n<b>והענין</b> דבאמת כלליות השתל' עולם האצי' לגבי א\"ס אינו תופס מקום כלל וכמ\"ש כולם בחכ' עשית<sup data-n=\"4614\">14</sup> שגם נחשבת<sup data-n=\"4615\">15</sup> כעשי' גשמיות, וכשנאצל האצי' הוא רק מקו שהוא הארה מא\"ס וגם לאחר הקו יש כמה צמצומים עד שנעשה בחי' חכ' (בפ\"א וחסד) וזהו אבא יונק ממזלא<sup data-n=\"4616\">16</sup> היינו שערות דא\"א והוא מורה על",[["4601","1","<b>למה קדמה שמע לוהי' אם שמוע</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב מחלק שני של המאמר ד\"ה והנה כובע שנדפס לעיל בחלק המאמרים [ושם הפתיחא: ויובן זה עוד בהקדם מארז\"ל למה קדמה שמע לוהא\"ש]. וש\"נ."],["4602","2","<b>למה קדמה שמע לוהי' אם שמוע. . עול מצות</b>: ראה ברכות פ\"ב, מ\"ב (יג, א)."],["4603","3","<b>וסור מרע ועשה טוב</b>: ע\"פ תהלים לד, טו."],["4604","4","<b>תרי\"ג מצות. . שהם תרי\"ג ארחין. . דגולגלתא</b>: ראה זהר אד\"ר נשא קכט, א. קלו, א. אגה\"ק ס\"כ (קלא, א). לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח פי\"א ובהערה 219."],["4605","5","<b>בפ\"א</b>: ראה גם לעיל הנחה ד\"ה ואהבת את ה' אלקיך הא' ובהערה 74."],["4606","6","<b>מגיד דבריו ליעקב. . לישראל לעשות</b>: תהלים קמז, יט. ראה שמו\"ר פ\"ל, ט. ראה גם סה\"מ תרכ\"ח ע' פח."],["4607","7","<b>מנין דהקב\"ה מניח תפילין</b>: ברכות ו, א. ראה גם תו\"א מקץ (כאן) לה, ב ואילך. סה\"מ תרכ\"ז ע' מה. וש\"נ. ע' קיא. וש\"נ. תרל\"ג ח\"ב ע' תלד. וש\"נ."],["4608","8","<b>והקב\"ה מתעטף בציצית</b>: ראה ר\"ה יז, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תסז. וש\"נ."],["4609","9","<b>הקב\"ה מצלי</b>: נסמן בהערה הבאה."],["4610","10","<b>מאי מצלי יה\"ר</b>: ראה ברכות ז. א."],["4611","11","<b>הקב\"ה יושב ועוסק בתורה</b>: ע\"ז ג, ב."],["4612","12","<b>צו אל בנ\"י</b>: אוצ\"ל: צו את בנ\"י — ויקרא כד, ב. ועוד. ראה גם לעיל הנחה ד\"ה אני לדודי הא' ובהערה 63."],["4613","13","<b>דבר אל בנ\"י</b>: בשלח יד, ב. טו. תרומה כה, ב. תשא לא, יג. ויקרא א, ב. ועוד."],["4614","14","<b>כולם בחכ' עשית</b>: תהלים קד, כד."],["4615","15","<b>שגם נחשבת</b>: אוצ\"ל: שגם אצי' נחשבת<sup data-n=\"e316\">א</sup>. או שצ\"ל: שגם חכ' נחשבת<sup data-n=\"e317\">ב</sup>."],["4616","16","<b>אבא יונק ממזלא</b>: ראה זהר אד\"ז האזינו רפט, ב. ע\"ח שער הכללים פ\"ה. תו\"ח שמות ח\"א לו, א הערה 455.\n\n<b>א</b>  ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה גן נעול הב' ובהערה 22.\n\n<b>ב</b>  ראה גם לעיל הנחה ד\"ה עשה צדקה ומשפט ובהערה 131."]]],[2000480446,"השפעה מאוא\"ס בדילוג הערך (בפ\"א וכדי שיהי' דילוג וירידה זו) וזהו\"ע הקב\"ה מניח תפילין, היינו המשכות אוא\"ס במוחין (בפ\"א דז\"א), ואמרז\"ל תפילין דמארי עלמא<sup data-n=\"4617\">17</sup> מה כתי' בהו כי מי גוי גדול<sup data-n=\"4618\">18</sup> כו' ומי גוי גדול<sup data-n=\"4619\">19</sup> כו' בחד ביתא<sup data-n=\"4620\">20</sup> אשריך ישראל<sup data-n=\"4621\">21</sup> כו' בחד ביתא כו' דתפילין הוא ל' התקשרות<sup data-n=\"4622\">22</sup> דעי\"ז נמשך המשכת אוא\"ס במוחין שיומשך לישראל למטה, וה\"ז כבקשת משה ונפלינו אני ועמך<sup data-n=\"4623\">23</sup> שאפי' מבחי' פלא (בפ\"א אשר שם כחשיכא כאורה<sup data-n=\"4624\">24</sup> ) מ\"מ יהי' אני ועמך דוקא, ואיך יהי' זה היינו שיומשך דרך חכ' וממילא יומשך למקום הראוי אם בחוקותי תלכו<sup data-n=\"4625\">25</sup> כו'.\n<b>וענין</b> מצות הצדקה למעלה, הנה כמו שלמטה ענין הצדקה הוא להחיות רוח שפלים<sup data-n=\"4626\">26</sup>, כמו\"כ למעלה לגבי אוא\"ס הכל כשפלים ודלים שאינם תופסים מקום כלל וכמ\"ש עושה פלא<sup data-n=\"4627\">27</sup> שאפי' בחי' פלא הוא ג\"כ עשי' גשמית וכללות השתל' אינם תופסים מקם כלל, וזהו\"ע הצדקה למעלה שיהי' בנין החסד באצי' וכמ\"ש כי אמרתי עולם חסד יבנה<sup data-n=\"4628\">28</sup> שנעשה בנין החסד והיינו ע\"י שנמשך מחסדו שבלי גבול נבנה מדת החסד, ואח\"כ מכלכל חיים בחסד<sup data-n=\"4629\">29</sup> שיומשך השפעת החסד למטה, דחסד למעלה אינו דומה כמו חסד למטה דלמטה החסד גורם השפעה דמי שהוא חסדן הוא משפיע ה\"ז גרם השפעה (בפ\"א לא שהחסד עצמו נשפע למטה ומי שהוא כילי<sup data-n=\"4630\">30</sup> אינו משפיע כו' הרי החסד גרם השפעה) משא\"כ למעלה החסד עצמו נשפע למטה וזהו מכלכל חיים בחסד שנשפע בחי' החסד למטה היינו השפעות החיים לעולם, וזהו\"ע צדקה למעלה, וכמו\"כ מה שהקב\"ה מניח תפילין שהו\"ע המשכות ד' מוחין חו\"ב ודעת שנחלק לחו\"ג<sup data-n=\"4631\">31</sup>, שזהו ג\"כ מצד חסד ה'.\n<b>אך</b> צ\"ל והלא כשנאצל אצי' נאצל ע\"ס ויש בהם מוחין מהו\"ע המשכת המוחין, והענין דהנה מבשרי אחזה<sup data-n=\"4632\">32</sup> כמו תפילין שלמטה גם כשהם מונחים על",[["4617","17","<b>תפילין דמארי עלמא</b>: ראה ברכות ו, א. סה\"מ מלוקט ב' ע' פז בהערה."],["4618","18","<b>כי מי גוי גדול</b>: ואתחנן ד, ז."],["4619","19","<b>ומי גוי גדול</b>: ואתחנן ד, ח."],["4620","20","<b>בחד ביתא</b>: ברכות שם."],["4621","21","<b>אשריך ישראל</b>: ברכה לג, כט."],["4622","22","<b>דתפילין הוא ל' התקשרות</b>: ראה גם תו\"א מקץ (כאן) לה, ב."],["4623","23","<b>ונפלינו אני ועמך</b>: תשא לג, טז. ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה כי הנה יוצר הרים בסופה ובהנסמן שם."],["4624","24","<b>כחשיכא כאורה</b>: תהלים קלט, יב."],["4625","25","<b>אם בחקתי תלכו</b>: בחוקותי כו, ג."],["4626","26","<b>להחיות רוח שפלים</b>: ישעי' נז, טו. ראה גם סה\"מ תרל\"ג ח\"ב ע' תסה ובהנסמן שם."],["4627","27","<b>עושה פלא</b>: בשלח טו, יא. ראה תו\"א בשלח סג, א. מאמרי אדה\"א דברים ח\"ג ע' תתמט. וש\"נ."],["4628","28","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג. ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 94."],["4629","29","<b>מכלכל חיים בחסד</b>: נוסח שמו\"ע. ראה גם לעיל שם ובהערה 95."],["4630","30","<b>כילי</b>: אולי כצ\"ל."],["4631","31","<b>תפילין. . ד' מוחין חו\"ב. . לחו\"ג</b>: ראה זהר ואתחנן רסב, א. סידור שער התפילין ז, א. אמרי בינה שער התפילין קיב, א ואילך. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשח ובהנסמן במ\"מ לשם. מאמרי אדה\"א דברים ח\"ד ע' א'רמא. וש\"נ."],["4632","32","<b>מבשרי אחזה</b>: ע\"פ איוב יט, כו."]]],[2000480447,"השולחן יש בהם ד' פרשיות קדש והי' כי יביאך<sup data-n=\"4633\">34</sup> שהם חו\"ב שמע והי' אם שמוע<sup data-n=\"4634\">35</sup> שהם דעת שנחלק לחו\"ג ויש בהם קדושה שנק' תשמישי קדושה<sup data-n=\"4635\">33</sup> אפי' בלילה דלאו זמן תפילין הוא<sup data-n=\"4636\">36</sup> וביום כשמונחים על השולחן, וכן בגד שהוא מצוייץ נק' תשמישי מצוה<sup data-n=\"4637\">37</sup>, ומ\"מ דוקא כשישראל מניח תפילין<sup data-n=\"4638\">38</sup> בזרוע ובראשו וכשלובש הציצית אז ה\"ז מצוה, וכמו שאמרז\"ל גבי קרבנות נח\"ר לפני שאמרתי ונעשה רצוני<sup data-n=\"4639\">39</sup> (בפ\"א דוקא כשנעשה המצוה אז הוא רצוני) שהוא בחי' רצה\"ע וכמו\"כ כל המצות הם רצה\"ע ודוקא ע\"י העשי' אז נמשך בהם בחי' רצה\"ע (וכמ\"ש ועשיתם אותם<sup data-n=\"4640\">40</sup> שישראל עושה אותם למצות) שהוא למעלה מחכ', וכמו\"כ יובן למעלה הגם שיש מוחין היינו מוחין בעצם אבל ענין הקב\"ה מניח תפילין היינו שיומשך המשכת אוא\"ס במוחין<sup data-n=\"4641\">41</sup>. אך עדיין צ\"ל דלכאורה המשל אינו דומה לנמשל, דלמטה שהתפילין הם מציאות בפ\"ע והאדם הוא מציאות בפ\"ע שייך לומר דאפי' בלילה דלאו זמן תפילין יש בהם ד' פרשיות ויש בהם קדושה ג\"כ וע\"י שהאדם מניח תפילין נמשך בהם בחי' רצה\"ע, אבל למעלה אינו שייך זה דממך הכל<sup data-n=\"4642\">42</sup> (בפ\"א ואין לך דבר שחוץ ממנו) ומה שייך שם תפילין וענין הקב\"ה מניח תפילין שהוא המשכה כו'<sup data-n=\"4643\">43</sup>.\n<b>והענין</b> דהנה אי' בת\"ז כד אנת אסתלק מנייהו<sup data-n=\"4644\">44</sup> אשתארו כולהו שמהן כגופא בלא נשמתא, ולכאורה צ\"ל והלא ממך הכל ואין לך דבר שחוץ ממנו וא\"כ כשנסתלק בחי' אוא\"ס איך אשתארו כגופא כו' דבחי' גופים למעלה אינו כמו למטה שהגוף יש לו שרש בפ\"ע<sup data-n=\"4645\">45</sup> והתהוותו מחלק או\"א והקב\"ה נותן בו נשמה<sup data-n=\"4646\">46</sup> שהוא מחי' את הגוף ולא מהווה, אבל למעלה בבחי' אוא\"ס דממך הכל, וכשנסתלק בחי' אוא\"ס איך אשתארו כגופים. ומבואר במ\"א ע\"ז ב' תירוצים<sup data-n=\"4647\">47</sup>, א' דמ\"ש כד אנת",[["4633","34","<b>קדש והי כי יביאך</b>: בא יג, א ואילך. בא שם, יא ואילך."],["4634","35","<b>שמע והי' אם שמוע</b>: ואתחנן ו, ד ואילך. עקב יא, יג ואילך."],["4635","33","<b>התפילין. . שנק' תשמישי קדושה</b>: כ\"ה בכ\"מ — ראה לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה בן פורת יוסף הא' ובהערה 55. ראה שו\"ע אדה\"ז הל' תפילין סמ\"ב, ס\"ו."],["4636","36","<b>בלילה דלאו זמן תפילין הוא</b>: ראה שו\"ע אדה\"ז הל' תפילין ס\"ל, ס\"א. אוה\"ת ואתחנן ס\"ע שלב ואילך. סה\"מ תרכ\"ז ע' קיב."],["4637","37","<b>וכן בגד שהוא מצוייץ נק' תשמישי מצוה</b>: ראה שו\"ע אדה\"ז הל' ציצית רסכ\"א. הל' תפילין שם."],["4638","38","<b>דוקא כשישראל מניח תפילין</b>: ראה תו\"א שמות נג, ד (ובהנסמן בריש המאמר שם). לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה בן פורת יוסף הא' ובהערה 54."],["4639","39","<b>נח\"ר לפני שאמרתי ונעשה רצוני</b>: ספרי שלח טו, ז. י. ראה לקו\"ש ויקרא כרך לב ע' 1. וש\"נ."],["4640","40","<b>ועשיתם אותם</b>: קדושים כ, ח. בחוקותי כו, ג. ראה סה\"מ תרל\"ח ע' רכ. וש\"נ."],["4641","41","<b>שיומשך המשכת אוא\"ס במוחין</b>: ראה גם תו\"א מקץ (כאן) לה, ב."],["4642","42","<b>דממך הכל</b>: דהי\"א כט, יד."],["4643","43","<b>כו'</b>: אולי כ\"ה בגוכתי\"ק."],["4644","44","<b>כד אנת אסתלק מנייהו</b>: ראה ת\"ז בהקדמה יז, ב. ראה גם (בנוסף לתו\"א כאן לו, רע\"ג) הנסמן (לעיל בחלק המאמרים) במאמר ד\"ה ולהבין שרש ענין בחי' מזבח הפנימי הערה 124."],["4645","45","<b>שהגוף יש לו שרש בפ\"ע</b>: ראה סידור ערב שבת קסה, ד ואילך. אוה\"ת וירא כרך ד ע' תשמב. סה\"מ עזר\"ת ע' קסה."],["4646","46","<b>שהגוף. . מחלק או\"א והקב\"ה. . נשמה</b>: ראה נדה לא, א."],["4647","47","<b>ומבואר. . ב' תירוצים</b>: ראה תו\"א מקץ כאן לה, רע\"ג."]]],[2000480448,"אסתלק מנייהו אין הכוונה על הסתלקות לגמרי אלא כמו מגדלות לקטנות, וכמו האדם בעת השינה יש לו מוחין והראי' מהחלומות שבעת השינה, מ\"מ אנו רואין שבעת החלום יוכל להרכיב ב' ענינים נפרדים והפכים שבהקיץ הם נגד השכל לגמרי<sup data-n=\"4648\">48</sup> ובעת השינה הם מתחברין יחד, והרי יש לו שכל שה\"ה מחשב, אלא שהשכל הוא בקטנות וכמו שהקטן רוצה איזה דבר שגבי הגדול הוא נגד השכל, וכמו\"כ יובן למעלה היינו שנשאר בבחי' קטנות ולפ\"ז יש רשימה מהאור, ותי' הב' הוא, דכלים יש להם שרש בפ\"ע ושרשם מבחי' מטי ולא מטי<sup data-n=\"4649\">49</sup> (בפ\"א בל' הקבלה) ולכן אשתארו כגופא והשראת האור שבהכלים למעלה מבחי' מטי ולא מטי (בפ\"א ושניהם אמת), שהכלים יש להם שרש בפ\"ע וגם מה שנשאר בחי' קטנות ונמצא מה דאשתארו כגופא כו' הוא הן מצד האור הן מצד הכלי, וכמו\"כ יובן ענין הקב\"ה מניח תפילין דמוחין בעצם ה\"ז כגופא בלא נשמתא, והקב\"ה מניח תפילין היינו המשכות אוא\"ס בבחי' תוס' מרובה על העיקר דכל תוספתו של הקב\"ה מרובה על העיקר<sup data-n=\"4650\">50</sup>.\n<b>וזהו</b> מגיד דבריו ליעקב מה שהוא עושה אומר לישראל לעשות ויש בזה ב' פי'<sup data-n=\"4651\">51</sup> אך מה שנוגע לכאן הוא, מה שהוא עושה פי' כדי שיהי' הקב\"ה מניח תפילין הוא ע\"י שאומר לישראל לעשות והם עושים מעורר למעלה שיהי' הקב\"ה מניח תפילין וכן שארי המצות, וזהו מ\"ש ה' צלך והוא משל כמו הצל<sup data-n=\"4652\">52</sup> כל מה שעושין נעשה שם ג\"כ כמו\"כ ע\"י שעושין מצות למטה נעשה למעלה ג\"כ בחי' מצות כו' (תו\"א פ' חיי שרה ד\"ה להבין משארז\"ל יפה שעה א' בתשומע\"ט<sup data-n=\"4653\">53</sup> ) וזהו\"ע לאתקנא רזא דשמי'<sup data-n=\"4654\">54</sup> שיש ז' שמות שאינן נמחקים<sup data-n=\"4655\">55</sup> או יו\"ד שמות<sup data-n=\"4656\">56</sup> כו' והיינו להוסיף אורות באצי', אך זהו דוקא בצדיק גמור שאין רע בנפשו (בפ\"א בנר\"ן שלו) כלל אז העבודה הוא להוסיף אורות באצי', אבל בינונים דזה וזה שופטן<sup data-n=\"4657\">57</sup> שיש רע בנפשם (בפ\"א בנר\"ן שלהם) העבודה הוא לברר הנר\"ן שלהם וזהו משארז\"ל מה איכפת כו' לא ניתנו המצות אלא לצרף בהם את הבריות<sup data-n=\"4658\">58</sup> וצירוף שייך כשיש פסולת והיינו",[["4648","48","<b>שבעת החלום. . נגד השכל לגמרי</b>: ראה גם תו\"א וישב כח, ג. תו\"ח שמות ח\"א לז, ד ואילך ובהנסמן שם."],["4649","49","<b>דכלים. . מטי ולא מטי</b>: ראה ע\"ח שער העקודים ש\"ו, פ\"ג. תו\"א מקץ כאן לה, רע\"ג. מאמרי אדה\"ז אתהלך לאזניא ע' רכב ואילך."],["4650","50","<b>תוספתו של הקב\"ה. . העיקר</b>: ראה ב\"ר פס\"א, ד. לקו\"ש וישלח כרך ה ע' 422 הערה 3. ע' 423 הערה 10. סה\"מ תרל\"ח ע' מט. וש\"נ."],["4651","51","<b>ב' פי'</b>: ראה גם סה\"מ תרכ\"ח ע' פח."],["4652","52","<b>ה' צלך. . הצל</b>: תהלים קכא, ה. ראה גם (לעיל בחלק המאמרים) בהמאמר כאן שולי הגליון ה."],["4653","53","<b>תו\"א פ' חיי שרה. . בתשומע\"ט</b>: טז, ב."],["4654","54","<b>לאתקנא רזא דשמי'</b>: בתו\"א שמות מט, רע\"ד. יתרו סז, ד בשם הזהר."],["4655","55","<b>ז' שמות שאינן נמחקים</b>: שבועות לה, א. רמב\"ם הל' יסודי התורה פ\"ו, ה\"ב. תו\"ח בא ח\"א קיב, א ואילך ובהנסמן בריש המאמר שם. סה\"מ תרכ\"ז ע' יב."],["4656","56","<b>יו\"ד שמות</b>: ראה רדב\"ז הל' ממרים פ\"ה, ה\"ב. פרדס שער עשר ולא תשע ש\"א, פ\"י. שער השמות ש\"כ. לקו\"ת ר\"ה נה, ד. מאמרי אדה\"ז תקס\"ח ח\"א ע' תכב. לקו\"ש פ' זכור כרך כא ע' 195 בהערה."],["4657","57","<b>בינונים דזה וזה שופטן</b>: ברכות סא, ב. ראה גם מאמרי אדה\"ז הקצרים ע' שיז ואילך. שע\"ת עו, רע\"ג (ספ\"א). צה, ב. ד\"ח שער התפלה פס\"ח — פ\"ע."],["4658","58","<b>מה איכפת. . לצרף בהם את הבריות</b>: ראה תנחומא שמיני ז-ח. ב\"ר רפמ\"ד. אוה\"ת שמיני ע' נב ואילך. המשך מים רבים תרל\"ו ע' קטו. סה\"מ תרל\"ח ע' מח ואילך. לקו\"ש אבות כרך יז ע' 415 הערה 53. שופטים כרך יט ע' 182 הערה 42."]]],[2000480449,"בינונים שמעורב בהם רע, ועשיות המצות הוא לברר בירורים, ולכאו' ג\"ז צ\"ל והלא העשי' היא באופן אחד וכמו דור המדבר שהיו דור דעה<sup data-n=\"4659\">59</sup> משה ואהרן ויהושע וכלב ופנחס וכל שבט לוי שהיו צדיקים גמורים<sup data-n=\"4660\">60</sup> ובתפילין שלהם הי' ג\"כ ד' פרשיות<sup data-n=\"4661\">61</sup> קדש והי' כי יביאך שמע והא\"ש, כמו בתפילין שלנו ועבודתם הי' להוסיף אורות באצי', ותפילין שלנו העבודה לברר בירורים, אך באמת הכל הולך למקום אחד דע\"י עבודת הצדיקים שנמשך להוסיף אורות באצי' (בפ\"א בוקע ו)נמשך (בפ\"א תוס' הארה) בבי\"ע לברר הנר\"ן של בינונים שהוא בבי\"ע נפש בעשי' רוח ביצי' נשמה בבריאה<sup data-n=\"4662\">62</sup>.\n<b>אך</b> כ\"ז אינו תכלית המכוון של מצות, רק שהיא הכוונה דמצות בצ\"ג להוסיף אורות באצי' ובבינונים לברר הנר\"ן, אבל תכלית המכוון של מצות שיהי' כעבודת עבד בלי כוונה, דכשעובד בכוונה בצ\"ג להוסיף אורות באצי' ובינונים לברר הנר\"ן ה\"ז שמשיג (בפ\"א דמצוה שהוא ברצון ובחירה כמו מי שהוא משכיל ומשיג) אשר קרבת אלקים לו טוב<sup data-n=\"4663\">63</sup> ה\"ז כוונה, ועיקר המצות הוא שיהי' בעבודת<sup data-n=\"4664\">64</sup> עבד וכמ\"ש כי לי בנ\"י עבדים<sup data-n=\"4665\">65</sup> עבדי הם, כי לי קאי על אוא\"ס עצומ\"ה כאדם האומר כי לי שמורה על עצמותו, וכדי שיבוא לבחי' לי הוא ע\"י עבדים, עבדי הם, ע\"י בחי' עבודת עבד בלא טעם, דשר הולך אחר הכוונה אבל עבד עושה כמו שאמרו לו בלי טעם כלל, והוא משלים הרצון, וזהו\"ע הקדמות נעשה לנשמע<sup data-n=\"4666\">66</sup>, נשמע הם הרצונות פרטים ונעשה הוא ביטול הרצון לגמרי, דמ\"ש נשמע ה\"ה הרצונות פרטים וה\"ז כמו כוונות המצות אבל נעשה הוא שמבטל א\"ע מכל וכל, וכל מה שיאמר לו עשה אפי' אם יהי' או' לחטוב עצים<sup data-n=\"4667\">67</sup> היינו מקיימים כמו הנחת תפילין, רק שהציווי הי' להניח תפילין, וזהו\"ע קבלת עול מ\"ש ועי\"ז אתכפי' סט\"א<sup data-n=\"4668\">68</sup> ואסתלק יקרא דקוב\"ה בכולא עלמין, וזהו בטל רצונך מפני רצונו<sup data-n=\"4669\">69</sup> שיהי'",[["4659","59","<b>דור דעה</b>: ראה זהר בשלח סב, ב. פע\"ח שחה\"מ שכ\"א, פ\"א. מאמרי אדה\"א דברים ח\"א ע' עו. וש\"נ."],["4660","60","<b>וכל שבט לוי שהיו צדיקים גמורים</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן על יד הערה *109: הצד\"ג כדור דיעה."],["4661","61","<b>ובתפילין שלהם הי' ג\"כ ד' פרשיות</b>: ועד\"ז בתו\"א כאן לה, ג. (לעיל בחלק המאמרים) בהמאמר כאן על יד הערה 110. ראה גם לקו\"ש ואתחנן כרך ט ע' 52 ואילך ובהערות שם. ע' 57. ע' 59."],["4662","62","<b>נפש בעשי'. . בבריאה</b>: תק\"ז תכ\"ב בסופו."],["4663","63","<b>קרבת אלקים לו טוב</b>: ע\"פ תהלים עג, כח."],["4664","64","<b>בעבודת</b>: אולי כתוב: כעבודת."],["4665","65","<b>כי לי בנ\"י עבדים</b>: בהר כה, נה. ראה תו\"א מקץ לה, א. מאמרי אדה\"ז תקס\"ג ח\"א ע' סג. ש\"א נב, ב ואילך."],["4666","66","<b>הקדמות נעשה לנשמע</b>: שבת פח, א. ראה גם מאמרי אדה\"ז תקס\"ב ח\"א ע' רח. ש\"א נט, ב. מאמרי אדה\"א נ\"ך ע' רסא. סה\"מ תרכ\"ט ע' רנג."],["4667","67","<b>או' לחטוב עצים</b>: ראה מו\"נ ח\"ג פנ\"א (ד\"ה הערה). סה\"מ תרל\"ח ע' רלז. ע' תמו [שמוסיף: או לשאוב]. וש\"נ. לקו\"ש שמות כרך כא ע' 17 הערה 51."],["4668","68","<b>אתכפי' סט\"א</b>: ראה זהר תרומה קכח, ב. יתרו סז, ב. הנסמן במאמרי אדה\"א שמות ח\"א ע' ה. אוה\"ת שלח כרך ו ע' א'תשעב. וש\"נ. שה\"ש כרך ב ע' תרצט."],["4669","69","<b>בטל רצונך מפני רצונו</b>: אבות פ\"ב, מ\"ד."]]],[2000480450,"בטל הרצון לגמרי כמו שאין לו רצון כלל (בפ\"א הי' זה קודם מ\"ש ועי\"ז אתכפי' כו').\n<b>ושרש</b> ההפרש בין עומ\"ש לעול מצוות, הענין הוא דהנה מצות נתלבשו בדברים גשמים ציצית בצמר גשמי כו' והיינו לברר הרפ\"ח ניצוצין<sup data-n=\"4670\">70</sup> דתהו אשר נפלו בשבירה ועי\"ז נעשה העלאה מלמטלמ\"ע בחי' אור חוזר עד רום המעלות אפי' בבחי' ח\"ס וזהו\"ע בקיעת שערות הראש שהוא או\"ח מלמטלמ\"ע, ואח\"כ המשכה מלמעלה למטה והו\"ע שערות דדיקנא, וזהו ע\"י הבירורים דמצות נתלבשו בדברים גשמים ציצית בצמר גשמי תפילין בקלף גשמי ד\"מ שבלולב בצמחי' גשמים סוכה בסכך גשמי שופר כו', וכשמבררי' אותם ה\"ז העלאה ועי\"ז נמשך המשכה למטה, אך כ\"ז כוונות המצות שנק' עול מצות, אבל ענין עומ\"ש הוא שמבטל רצונו לגמרי ויתאמת אצלו באמת לאמיתו כאילו אין לו רצון בפ\"ע כלל כ\"א רצון הבורא ולא בשביל ההמשכה ויבטל גופו ורצונו מכל וכל, והוא מדרי' נעלה יותר מעו\"מ, דתרי\"ג מצות הם תרי\"ג ארחין דגולגלתא דז\"א, וע\"י קבלת עומ\"ש מגיע לבחי' ומדרי' חד ארחי דא\"א (בפ\"א שהיא בחי' ביטל לא\"ס בעל הרצון) וזהו למה קדמה שמע לוהי' אם שמוע כדי שיקבל עליו עומ\"ש תחילה ואח\"כ יקבל עליו עו\"מ, עו\"מ זהו והי' אם שמוע שלא נא' בכל מאודכם, ושמע הוא קבלת עומ\"ש דשם נא' בכל מאדך שהו\"ע הביטל בלי גבול וזהו שמקבל עליו עול מ\"ש היינו בחי' מל' דא\"ס, דשמים הוא מקור המקיפים, ומל' שמים הוא מל' דא\"ס (בפ\"א שמים הוא מקיפים ומל' שמים הוא מקור דשמים זהו בחי' מל' דא\"ס).\n<b>והנה</b> כ\"ז במצות שעושין בהגבלה אפי' מצות צדקה כשעושה אותה בהגבלה חומש כו'<sup data-n=\"4671\">71</sup> צ\"ל תחילה עומ\"ש ואח\"כ עו\"מ, אבל יש אופן במצות שע\"י עשיות המצות ימשיך בחי' עומ\"ש בעו\"מ, והיינו כשעושה המצוה בלא הגבלה שזהו בכל מאדך ופי' במשנה בכל ממונך<sup data-n=\"4672\">72</sup> ואפשר להקל בזה דלאו דוקא בכל ממונו אלא למעלה מהגבלת חומש<sup data-n=\"4673\">73</sup> ג\"ז נק' מאד וכשצריכין כל ממונו צ\"ל בכל ממונו ועי\"ז מעוררים למעלה בחי' חסד ה' שיומשך למטה, שעומ\"ש יומשך בעול מצות, וזהו עשה צדקה ומשפט נבחר לה' מזבח<sup data-n=\"4674\">74</sup> שהם הפרטי הרצונות משא\"כ צדקה הו\"ע [קבעומ\"ש] ועי\"ז ממשיכים בחי' מקיפים שיאיר בפנימי' וכמשנת\"ל בד\"ה עשה צדקה<sup data-n=\"4675\">75</sup> כו' (בפ\"א דמקיף הוא מה שאינו מאיר בפנימיות וע\"י צדקה ממשיכים",[["4670","70","<b>הרפ\"ח ניצוצין</b>: ראה ע\"ח שער רפ\"ח שי\"ח, פ\"ב. לקו\"ש וישב כרך טו ע' 524 (נדפס גם באג\"ק שלו ח\"ב ע' כא). וש\"נ. מאמרי אדה\"א דברים ח\"ד ע' א'קעד. וש\"נ."],["4671","71","<b>צדקה. . חומש כו'</b>: ראה שו\"ע יו\"ד רסרמ\"ט. לעיל הנחה ד\"ה אשריכם זורעי על כל מים ובהערה 128."],["4672","72","<b>בכל מאדך. . בכל ממונך</b>: ראה ואתחנן ו, ה. ברכות נד, א. (לעיל בחלק המאמרים) מאמר ד\"ה ולהבין שרש ענין בחי' מזבח הפנימי ובהערה 102."],["4673","73","<b>ואפשר להקל. . למעלה מהגבלת חומש</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן על יד הערה 123."],["4674","74","<b>עשה צדקה ומשפט נבחר לה' מזבח</b>: משלי כא, ג."],["4675","75","<b>וכמשנת\"ל בד\"ה עשה צדקה</b>: ראה שם בפיסקא אך מ\"ש."]]],[2000480451,"המקיף בפנימי), וזהו למה קדמה שמע לוהי' אם שמוע כדי שיקבל עליו עומ\"ש תחילה ואח\"כ יקבל עליו עו\"מ, עומ\"ש היינו בחי' ביטל הרצון, בטל רצונך כו', אך ע\"י צדקה נמשך בחי' עומ\"ש בעו\"מ כו' (בפ\"א וזהו וילבש צדקה כשריון<sup data-n=\"4676\">76</sup> וכובע ישועה בראשו כוב\"ע הוא ך\"ו ע\"ב<sup data-n=\"4677\">77</sup> שהוא בחי' חסד ה' שיומשך בראשו היינו בבחי' חכ' שהוא ראשית הספי'<sup data-n=\"4678\">78</sup> וכמ\"ש ראשית חכ'<sup data-n=\"4679\">79</sup> שיומשך תוס' השפעה מא\"ס המאציל יותר מההארה והשפעה שבראשית האצי', וזהו ע\"י וילבש צדקה ע\"י מצות צדקה למעלה מהגבלה נמשך בחי' כובע ישועה בראשו כו').",[["4676","76","<b>וילבש צדקה כשריון</b>: ישעי' נט, יז."],["4677","77","<b>כובע הוא ך\"ו ע\"ב</b>: ראה מאו\"א מערכת כובע סי\"א. (לעיל בחלק המאמרים) מאמר ד\"ה עשה צדקה ומשפט על יד הערה 107 ואילך."],["4678","78","<b>חכ' שהוא ראשית הספי'</b>: ראה רמ\"ז לזהר ואתחנן רסה, ב (קצד, א (ד\"ה לארקא). שם סע\"ב). לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 1248."],["4679","79","<b>ראשית חכ'</b>: תהלים קיא, י."]]],[2000480452,"<h3>פדה בשלום נפשי</h3>\n<b></b><b>יום ב' פ' וישב י\"ט כסלו תאמ\"ר לפ\"ק</b>\nיום ב' פ' וישב י\"ט כסלו\n<b>פדה</b> בשלום נפשי<sup data-n=\"4680\">1</sup> מקרב לי כי ברבים היו עמדי<sup data-n=\"4681\">2</sup>, ואמרז\"ל (ברכות ד\"ח ע\"א) אמר הקב\"ה כל העוסק בתורה ובגמ\"ח ומתפלל עם הציבור מעלה אני עליו כאילו פדאני לי ולבני, ופרש\"י<sup data-n=\"4682\">3</sup> איך למדו זאת מהפסוק, דגבי תורה כתי' וכל נתיבותי' שלום<sup data-n=\"4683\">4</sup> וזהו פדה בשלום נפשי וגמ\"ח נכלל ג\"כ בכלל פדה בשלום כו' דע\"י שמשפיע חסד לחבירו או אפי' גמ\"ח בגופו נעשה שלום בין אדם לחבירו, ומתפלל עם הציבור זהו מ\"ש כי ברבים היו עמדי<sup data-n=\"4684\">5</sup>, והנה ג' דברים אלו הם ענין א' עם משארז\"ל על ג' דברים העולם<sup data-n=\"4685\">6</sup> עומד<sup data-n=\"4686\">7</sup> על התורה ועל העבודה ועל הגמ\"ח, דעבודה הוא קרבנות<sup data-n=\"4687\">8</sup> ועכשיו תפילה כנגד תמידין תקנו<sup data-n=\"4688\">9</sup> זהו ומתפלל עם הציבור, ופי' ענין שעליהם העולם עומד, דהנה כתי' שוקיו עמודי שש ומיוסדים<sup data-n=\"4689\">10</sup> על אדני פז, ואמרז\"ל שוקיו",[["4680","1","<b>פדה בשלום נפשי</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב<sup data-n=\"e318\">*</sup>. ראה מאמר ד\"ה זה בסה\"מ תר\"ל ע' לז ואילך."],["4681","2","<b>פדה בשלום. . עמדי</b>: תהלים נה, יט."],["4682","3","<b>ופרש\"י</b>: ראה ברכות שם ד\"ה פדה בשלום."],["4683","4","<b>וכל נתיבותי' שלום</b>: משלי ג, יז."],["4684","5","<b>ומתפלל עם הצבור. . כי ברבים היו עמדי</b>: ראה פרש\"י ברכות שם ד\"ה כי ברבים היו עמדי (שלפני ד\"ה פדה בשלום). וראה גם ברש\"י על הרי\"ף כאן ד\"ה מצוי בבהכ\"נ (שהוא מארז\"ל זה לגי' הרי\"ף). סה\"מ תר\"ל כאן. ולהעיר שבאוה\"ת (יהל אור) תהלים ע' רד (עה\"פ) אינו מביא זה בשם רש\"י."],["4685","6","<b>ג' דברים אלו. . ג' דברים העולם עומד</b>: ראה מהרש\"א לברכות שם הובא בתוס' הגהות באוה\"ת שם ואילך. סה\"מ מלוקט ב' ס\"ע רד ואילך. וש\"נ."],["4686","7","<b>על ג' דברים העולם עומד</b>: אבות פ\"א, מ\"ב."],["4687","8","<b>דעבודה הוא קרבנות</b>: ראה מפרשי המשנה שם. סה\"מ תרל\"ח ע' לד הערה 79."],["4688","9","<b>תפילה כנגד תמידין תקנו</b>: ראה ברכות כו, ב."],["4689","10","<b>שוקיו עמודי שש ומיוסדים</b>: שה\"ש ה, טו [ושם: מיוסדים]."],["e318","*","ויש להוסיף הנחה זו לרשימת מאמרי דא\"ח של כ\"ק אדמו\"ר מהר\"ש ש. ז."]]],[2000480453,"זה עולם שנשתוקק הקב\"ה לבראותו<sup data-n=\"4690\">11</sup>, עמודי שש שנברא לששת ימים וכמ\"ש ששת ימים עשה<sup data-n=\"4691\">12</sup> ולא כתי' בששת אלא ששת דכל יומא ויומא עביד עבידתי'<sup data-n=\"4692\">13</sup> וכמ\"ש כי אמרתי עולם חסד יבנה<sup data-n=\"4693\">14</sup> ויש בזה ב' פי'<sup data-n=\"4694\">15</sup> א' שצריכים לבנות מדת החסד ב' שהחסד בונה כו' וכתי' זכור רחמיך וחסדיך כי מעולם המה<sup data-n=\"4695\">16</sup> רחמים וחסדים שייכים לעולמות דמקור הראשון ששייך שם מקור לעולם הם המדות<sup data-n=\"4696\">17</sup>, ומיוסדים על אדני פז שצריכים לעשות יסוד והוא מ\"ש ה' בחכ' יסד ארץ<sup data-n=\"4697\">18</sup> כונן שמים בתבונה בדעתו תהומות נבקעו<sup data-n=\"4698\">19</sup> שממשיכים מוחין למדות והם קיום המדות, דיסוד למעלה אינו דומה כמו למטה דלמטה היסוד למטה והבנין למעלה, ולמעלה היסוד למעלה והבנין למטה<sup data-n=\"4699\">20</sup>, וזהו\"ע ג' דברים שעליהם העולם עומד.\n<b>וצ\"ל</b> ענין המתפלל עם הציבור מהו המעלה דמתפלל בציבור, והענין דתפלה כנגד תמידין תקנו את הכבש האחד<sup data-n=\"4700\">21</sup> תעשה בבוקר ואת הכבש השני תעשה בין הערבים, והם היו באים מתרומת הלשכה<sup data-n=\"4701\">22</sup> שבאין משל ציבור דוקא ולא משל יחיד, דהנה כתי' כבשים בני שנה<sup data-n=\"4702\">23</sup> ואמרז\"ל למה שמם כבשים מפני שכובשין עוונותיהם של ישראל<sup data-n=\"4703\">24</sup>, והענין דכתי' והכשבים הפריד יעקב<sup data-n=\"4704\">25</sup>, שהפריד מצאן לבן שהוא בחי' מ\"ש לבושי' כתלג חיוורא שער ראשו כעמר נקי<sup data-n=\"4705\">27</sup>, והוא בחי' לובן",[["4690","11","<b>שוקיו זה עולם. . לבראותו</b>: ראה במד\"ר רפ\"י."],["4691","12","<b>ששת ימים עשה</b>: תשא לא, יז. ראה זהר ויחי רמז, א. אמור צד, ריש ע\"ב. האזינו חצר, ב. מאמרי אדה\"א דברים ח\"א ע' רז ואילך. וש\"נ."],["4692","13","<b>דכל יומא. . עבידתי'</b>: ראה זהר ויגש רה, סע\"א. אמור שם. השמטות לזח\"א רסד, ב."],["4693","14","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג."],["4694","15","<b>ב' פי'</b>: ראה סה\"מ תרכ\"ט ע' ט ועד\"ז ע' תו שמציין: ע' מזה בד\"ה ולקחתם אגודת אזוב (ך\"ח). לא נדפס לע\"ע וראה בהערת המו\"ל שם. סה\"מ תרכ\"ז ע' קמ. וש\"נ. תרל\"ח ע' מז ואילך."],["4695","16","<b>זכור רחמיך. . המה</b>: תהלים כה, ו [בדילוג השם]."],["4696","17","<b>מקור לעולם הם המדות</b>: ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה ושאבתם מים ובהערה 22."],["4697","18","<b>ה' בחכ' יסד ארץ</b>: משלי ג, יט."],["4698","19","<b>בדעתו תהומות נבקעו</b>: משלי שם, כ."],["4699","20","<b>ולמעלה היסוד למעלה והבנין למטה</b>: ראה גם דרך אמונה — לר' מאיר בן גבאי — ספ\"ט ד\"ה הט' (ע' ס במהדורת קה\"ת). וש\"נ. פרדס שעה\"כ שכ\"ג, פ\"י מערכת יסוד. אוה\"ת בראשית כרך ג ס\"ע 1122 ואילך. סה\"מ תר\"ל כאן. המשך והחרים תרל\"א ע' מח. סה\"מ תרל\"ג ח\"ב ע' שסד. תרל\"ד ע' ח. תרל\"ח ע' רלג. ע' תמב. סה\"מ מלוקט א' ע' סו ואילך."],["4700","21","<b>את הכבש האחד</b>: תצוה כט, לט."],["4701","22","<b>באים מתרומת הלשכה</b>: מנחות סה, א. רמב\"ם הל' שקלים רפ\"ד."],["4702","23","<b>כבשים בני שנה</b>: פינחס כח, ג."],["4703","24","<b>למה שמם כבשים מפני שכובשין עוונותיהם של ישראל</b>: ראה פסדר\"כ פסקא ו. פס\"ר פט\"ז. ילקוט שמעוני פינחס שם (רמז תשעז<sup data-n=\"e319\">א</sup>). וראה גם ערוך מערכת כבש הד'<sup data-n=\"e320\">ב</sup> בסופו. לקו\"ש תשא כרך ו' ע' 391 ואילך.\nבסה\"מ תר\"ל כאן וכן להלן שם: שמכבסים."],["4704","25","<b>והכשבים הפריד יעקב</b>: ויצא ל, מ."],["4705","27","<b>לבושי' כתלג חיוורא שער ראשו כעמר נקי</b>: דניאל ז, ט [ושם: חיור ושער ראשה — ראה גם בסמוך בפנים].\n\n<b>א</b>  בהדפוסים לא נרשם רמז זה.\n\n<b>ב</b>  לכאו' כצ\"ל גם בלקו\"ש שבפנים ההערה."]]],[2000480454,"העליון<sup data-n=\"4706\">26</sup> וזהו מ\"ש הידעתם את לבן בן נחור<sup data-n=\"4707\">28</sup> ואמרז\"ל הידעתם מי שמלבן עוונותיהם של ישראל<sup data-n=\"4708\">29</sup> ולא ששאל על לבן בגשמיות אלא מי שמלבין כו', והו\"ע לבושי' כתלג חיוורא שער רישא כעמר נקי, ועז\"נ אם יהיו חטאיכם כשנים<sup data-n=\"4709\">30</sup> כשלג ילבינו ואפי' אם יאדימו כתולע כצמר יהיו שאינו לבן כ\"כ מ\"מ נמשך משם מחילות וסליחות עוונות, ולכן הכבשים יש להם שערות לבנים שזהו\"ע שער רישא כעמר נקי דאמרז\"ל מ\"ט עיזא מסגי בראשו<sup data-n=\"4710\">31</sup> והדר אימרי כבריתו של עולם בראשו חשיכה והדר נהורא, ופירש\"י<sup data-n=\"4711\">32</sup> סתם עיזים שחורות וסתם אמרי שהם כבשים לבנים, ולכן התמידין היו מכפרין על עוונות של ישראל, תמיד של שחר<sup data-n=\"4712\">33</sup> על עבירות של לילה ותמיד של בין הערבים על עבירות של היום, צדק ילין בה<sup data-n=\"4713\">34</sup>, שזהו\"ע שמכבשין עוונותיהן של ישראל יכבשו עוונותינו.\n<b>אך</b> עדיין צ\"ל מהו המעלה דצבור, והענין דהנה אמרז\"ל רמי כתי'<sup data-n=\"4714\">35</sup> מי כה' אלקינו<sup data-n=\"4715\">36</sup> בכל קראינו אליו וכתי' דרשו ה' בהמצאו<sup data-n=\"4716\">37</sup> ל\"ק כאן בצבור כאן ביחיד ויחיד אימת בעשרה ימים שבין ר\"ה ליוהכ\"פ, דאז מאיר בחי' יגמה\"ר<sup data-n=\"4717\">38</sup> ורמ\"ח פקודין רמ\"ח איברים דמלכא<sup data-n=\"4718\">39</sup> ושס\"ה ל\"ת הם שס\"ה גידים<sup data-n=\"4719\">40</sup> ואפי' אם פגם במ\"ע או אפי' בל\"ת דתשו' תולה ויוהכ\"פ מכפר<sup data-n=\"4720\">41</sup> דאז מאיר יגמה\"ר ונמשך סליחות עוונות נושא עון ועובר על פשע<sup data-n=\"4721\">42</sup>, ובציבור בכל קראינו אליו, וצ\"ל דמה שביחיד הוא בעשי\"ת כמו\"כ הוא בציבור בכל השנה דאכל בי עשרה שכינתי' שריא<sup data-n=\"4722\">43</sup> וה\"ז בהמצאו, דמפני מה ביחיד בעשי\"ת נמשך להיות נושא עון ועובר על פשע מפני שאז זמן בהמצאו, כמו\"כ בצבור דאכל בי עשרה שכינתא שרי' ה\"ז בהמצאו.\n<b>והנה</b> המתפלל בציבור בלא תורה וגמ\"ח אין זה מספיק דכמו הקרבנות הי' צ\"ל במקדש או במשכן ואם לאו ה\"ז שחוטי חוץ ובכרת כ\"א במקדש כו' ושם היו",[["4706","26","<b>לבן. . לובן העליון</b>: ראה ע\"ח שער העקודים ש\"ו, פ\"א. מאמרי אדה\"א בראשית ע' רכב. וש\"נ. תו\"ח ויצא קסח, ד ובהערה 31."],["4707","28","<b>הידעתם את לבן בן נחור</b>: ויצא כט, ה."],["4708","29","<b>הידעתם מי שמלבן עוונותיהם של ישראל</b>: ב\"ר פ\"ע, י. ילקוט שמעוני שם (רמז קכג)."],["4709","30","<b>אם יהיו חטאיכם כשנים</b>: ישעי' א, יח. ראה גם סה\"מ תרכ\"ט ע' שסו וע' שסח."],["4710","31","<b>מ\"ט עיזא מסגי בראשו</b>: ראה שבת עז, ב."],["4711","32","<b>ופירש\"י</b>: ראה שם ד\"ה ברישא חשוכא (בשינוי)."],["4712","33","<b>תמיד של שחר</b>: ראה במדב\"ר פכ\"א, כא ובהנסמן במת\"כ שם. מאמרי אדה\"א שמות ח\"ב ע' תקעא. וש\"נ."],["4713","34","<b>צדק ילין בה</b>: ישעי' א, כא."],["4714","35","<b>אמרז\"ל רמי כתי'</b>: ראה גם אוה\"ת ש\"ש ריש ע' א'תעה: ”ובגמרא פ\"ג דר\"ה די\"ח ע\"א וביבמות פ' י\"ב [מצות חליצה] דק\"ה סע\"א רמי קראי אהדדי\". סה\"מ תר\"ל כאן."],["4715","36","<b>מי כה' אלקינו</b>: ואתחנן ד, ז [בדילוג]."],["4716","37","<b>דרשו ה' בהמצאו</b>: ישעי' נה, ו."],["4717","38","<b>בעשרה ימים. . מאיר בחי' יגמה\"ר</b>: ראה זהר ספדצ\"נ פ\"ב תרומה קעז, א (הובא באוה\"ת שם). לקו\"ת פ' ראה כד, ד. מאמרי אדה\"א דברים ח\"ב ע' תכב ואילך. וש\"נ."],["4718","39","<b>ורמ\"ח פקודין רמ\"ח איברים דמלכא</b>: ראה ת\"ז ת\"ל (עד, סע\"א). תניא רפכ\"ג. סידור שער החנוכה רפ, א. שע\"ת עב, ג הערה 17."],["4719","40","<b>ושס\"ה ל\"ת הם שס\"ה גידים</b>: ראה תרגום יוב\"ע בראשית א, כז. זהר וישלח קע, ב."],["4720","41","<b>בל\"ת דתשו' תולה ויוה\"כ מכפר</b>: ראה יומא פו, א. רמב\"ם הל' תשובה פ\"א, ה\"ד. אגה\"ת פ\"א."],["4721","42","<b>נושא עון ועובר על פשע</b>: מיכה ז, יח."],["4722","43","<b>דאכל בי עשרה שכינתי' שריא</b>: ראה סנהדרין לט, א. תניא ספי\"א ובמ\"מ הגהות והע\"ק לשם. מאמרי אדה\"א שמות ח\"א ע' יד. וש\"נ. ש\"א מה, א. ד\"ח עג, ג. לקו\"ש בהעלותך כרך לח ע' 43."]]],[2000480455,"ארון ויריעות שהם פנימים ומקיפים וכמ\"כ תורה הוא פנימי ולבושי המצות ובפרט מצות צדקה מקיפים<sup data-n=\"4723\">44</sup> וכמ\"ש ואשים דברי בפיך<sup data-n=\"4724\">45</sup> ובצל ידי כסיתיך, ואשים דברי בפיך תורה שהוא פנימי וכמ\"ש ותורתך בתוך מעי<sup data-n=\"4725\">46</sup> ובצל ידי כסיתיך קאי על מצות ובפרט גמ\"ח וכמ\"ש בצל החכ' צל הכסף<sup data-n=\"4726\">47</sup>, ולכן תפלה בצבור בלא תורה וגמ\"ח ה\"ז שחוטי חוץ רק תורה וגמ\"ח, וזהו א' הקב\"ה כל העוסק בתורה ובגמ\"ח ומתפלל עם הצבור מעלה אני עליו כאילו פדאני לי ולבני דמ\"ש פדה בשלום נפשי קאי על נפש דוד והו\"ע משארז\"ל גלו לבבל שכינה עמהם<sup data-n=\"4727\">48</sup> וזהו כאילו פדאני לי, ולבני הוא מ\"ש בני בכורי ישראל<sup data-n=\"4728\">49</sup> דהנה\"א נתלבש בהנה\"ב לברר בירורים דהנה\"א מצד עצמו א\"צ תיקון<sup data-n=\"4729\">50</sup> כ\"א מה שנתלבש בגוף ונה\"ב לברר בירורים דהנה\"ב ואמרז\"ל א' מהם גולה לברבריא<sup data-n=\"4730\">51</sup> נמשך לאגנאה עלייהו וא\"כ יש בו בחי' נפש דוד ג\"כ ולכן כל העוסק בתורה כו' מעלה אני כאילו פדאני לי ולבני כו'.",[["4723","44","<b>תורה הוא פנימי ולבושי המצות. . מקיפים</b>: ראה תניא פ\"ה. תו\"א יתרו סט, א. תצוה פג, ג. מאמרי אדה\"א ויקרא ס\"ע תקד ואילך."],["4724","45","<b>ואשים דברי בפיך</b>: ישעי' נא, טז."],["4725","46","<b>ותורתך בתוך מעי</b>: תהלים מ, ט. ראה תניא שם."],["4726","47","<b>בצל החכ' צל הכסף</b>: קהלת ז, יב [ושם: בצל הכסף]. ראה גם פסחים נג, ב<sup data-n=\"e321\">ג</sup>. סה\"מ תרל\"ו ח\"ב ע' רפא."],["4727","48","<b>גלו לבבל שכינה עמהם</b>: מכילתא בא יב, מב. ספרי בהעלותך י, לה. מסעי לה, לד. מגילה כט, א. ראה גם לקו\"ש ב' ניסן כרך ז ע' 210 הערה 29."],["4728","49","<b>בני בכורי ישראל</b>: שמות ד, כב."],["4729","50","<b>דהנה\"א. . א\"צ תיקון</b>: ראה תניא פל\"ז (מח, ב). ש\"א ט, א הערה 4."],["4730","51","<b>א' מהם גולה לברבריא</b>: שהש\"ר פ\"ב, ח (ב).\n\n<b>ג</b>  לכאו' כצ\"ל גם באוה\"ת קהלת כרך ב ריש ע' א'קכז."]]],[2000480456,"<h3>עטרת תפארת שיבה</h3>\n<b>ש\"פ וישב מ\"א לפ\"ק</b>\n<b>עטרת</b> תפארת שיבה<sup data-n=\"4731\">1</sup> בדרך צדקה תמצא<sup data-n=\"4732\">2</sup>, ופי' רבינו (בתו\"א פ' וישב ד\"ה בכ\"ה בכסלו<sup data-n=\"4733\">3</sup> ) (בפ\"א<sup data-n=\"4734\">4</sup> כדי שיהי' תפארת להעטרת) כדי שיומשך בחי' תפארת שיבה שהוא בחי' הדרת פנים וכמ\"ש יאר ה' פניו<sup data-n=\"4735\">5</sup> כו', ועל ל' החסידות, הו\"ע תעלומות לב<sup data-n=\"4736\">6</sup> פנימיות הלב שמתאחד עם המוחין דחיצוניות הלב אינו מתאחד עם המוחין דאף כשהמוח חושב מחשבות ומתבונן בגדולת א\"ס מ\"מ חיצוניות הלב אינו ברשותו (בפ\"א של מוח) אבל פנימיות הלב מתאחד עם המוחין וזהו בדרך צדקה",[["4731","1","<b>עטרת תפארת שיבה</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר ד\"ה זה שנדפס לעיל בחלק המאמרים. וש\"נ."],["4732","2","<b>עטרת תפארת שיבה בדרך צדקה תמצא</b>: משלי טז, לא."],["4733","3","<b>בתו\"א. . בכסלו</b>: כט, סע\"ג ואילך [ושם כט, א: בכסליו]."],["4734","4","<b>בפ\"א</b>: ראה גם לעיל הנחה ד\"ה ואהבת את ה' אלקיך הא' ובהערה 74."],["4735","5","<b>יאר ה' פניו</b>: נשא ו, כה."],["4736","6","<b>תעלומות לב</b>: תהלים מד, כב. ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה ושאבתם מים ובהערה 90."]]],[2000480457,"תמצא, ופי' שם<sup data-n=\"4737\">7</sup> שע\"י הריח הו\"ע העלאת מ\"ן דצדקה עי\"ז נמשך גילוי המוח בפנימיות הלב, ולכאו' אינו מובן מאחר שפנימיות הלב מתאחד עם המוח וא\"כ מה צריך לשית עצות לזה דבדרך צדקה תמצא, והנה צ\"ל תחילה ענין חיצוניות הלב ופנימיות הלב.\n<b>הנה</b> כתי' וצדקה כנחל איתן<sup data-n=\"4738\">8</sup>, כמו הנחל שהוא התפשטות המים מן המעין כמו ע\"י צדקה ממשיכים הארה והמשכה מבחי' איתן (בפ\"א שפי' בזהר) שהוא בחי' נקודא בהיכלי<sup data-n=\"4739\">9</sup> תרין ריעין דלא מתפרשין<sup data-n=\"4740\">10</sup>, ואותיות איתן משמשות לעתיד<sup data-n=\"4741\">11</sup> דלע\"ל יומשך בחי' זו, וכמ\"ש הנה ישכיל עבדי<sup data-n=\"4742\">12</sup> ירום ונשא וגבה מאד אותיות אדם<sup data-n=\"4743\">13</sup>, אך הוא בהיפוך אתוון אדם דע\"י הבירורים נמשך בחי' זו, והיינו ע\"י הסרת הערלה דדברים גשמים דע\"י העבודה דאיתן יומשך למעלה בחי' שרש ומקור מה שנק' למעלה בחי' איתן והוא כמ\"ש ומל ה' את לבבך<sup data-n=\"4744\">14</sup> ואת לבב זרעך, תי' ומל ל' גילוי<sup data-n=\"4745\">15</sup> וכמו וקטפת מלילות<sup data-n=\"4746\">16</sup> פי' שנוטלין העץ ומתגלה הגרעין, וזהו ומל ה' את לבבך ויומשך הגילוי מלמעלה בהקדם בחי' ומלתם את ערלת לבבכם<sup data-n=\"4747\">17</sup>, וע\"ד<sup data-n=\"4748\">18</sup> מילה בגשמיות דג' מדריגות יש<sup data-n=\"4749\">19</sup> מילה בגשמיות ומ\"ש ומלתם את ערלת לבבכם, ומל ה' אלקיך את לבבך וכאן לא כתי' ערלה דבבחי' פנימיות הלב אינו שייך ערלה רק בבחי' חיצוניות הלב והוא מ\"ש ומלתם את ערלת לבבכם. אך בהקדם בחי' מילה בגשמיות ובחי' ומלתם את ערלת לבבכם אז אח\"כ ומל ה' אלקיך את לבבך שנמשך הגילוי מלמעלה, וכמו בחי' איתן שמתגלה בהקדים הסרת הערלה תחילה, כמו\"כ בחי' ומל הוא ג\"כ בהקדם תחילה בחי' ומלתם את ערלת לבבכם וזהו ומל ל' עתיד כמו אותיות איתן שמשמשות לעתיד, וביאור ענין ומל ה' אלקיך את לבבך, דהנה את לבבך ואת לבב ר\"ת אלול<sup data-n=\"4750\">20</sup> וכתי' דרשו ה' בהמצאו<sup data-n=\"4751\">21</sup> ואמרז\"ל אימתי בהמצאו בעשרה ימים שבין ר\"ה ליוהכ\"פ וחדש אלול הוא הכנה לזה, ובעשי\"ת אומרים",[["4737","7","<b>ופי' שם</b>: כט, רע\"ד."],["4738","8","<b>וצדקה כנחל איתן</b>: עמוס ה, כד."],["4739","9","<b>נקודא בהיכלי</b>: כ\"ה בגוכתי\"ק. ראה זהר בהקדמה ו, רע\"א. תצוה קפ, א. (לעיל בחלק המאמרים) במאמר כאן הערה 9."],["4740","10","<b>תרין ריעין דלא מתפרשין</b>: ראה זהר בשלח נו, א. ויקרא ד, א. מאמרי אדה\"א דברים ח\"ב ע' שסו. וש\"נ. תו\"ח בראשית כא, ב ובהערה 8."],["4741","11","<b>ואותיות איתן משמשות לעתיד</b>: שהן באין בריש התיבה להורות על שימוש הפעולה להבא אפע\"ל יפע\"ל תפע\"ל נפע\"ל — לקו\"ת פ' ראה יח, א."],["4742","12","<b>הנה ישכיל עבדי</b>: ישעי' נב, יג."],["4743","13","<b>מאד אותיות אדם</b>: ראה זהר רע\"מ פינחס רמו, ב. ב\"ר פ\"ח, ה. פ\"ט, יב."],["4744","14","<b>ומל ה' את לבבך</b>: נצבים ל, ו [בדילוג]."],["4745","15","<b>ומל ל' גילוי</b>: ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 1628."],["4746","16","<b>וקטפת מלילות</b>: תצא כג, כו."],["4747","17","<b>ומלתם את ערלת לבבכם</b>: עקב י, טז."],["4748","18","<b>וע\"ד</b>: אולי כתוב ועוד."],["4749","19","<b>דג' מדריגות יש</b>: ראה גם (לעיל בחלק המאמרים) במאמר כאן ובהערה 25."],["4750","20","<b>את לבבך ואת לבב ר\"ת אלול</b>: ראה אבודרהם ס' תפלת ר\"ה (ירושלים תשכ\"ג ס\"ע רס). בעה\"ט־ פרושי ר' חיים פלטיאל<sup data-n=\"e322\">א</sup> נצבים ל, ו. ב\"ח לטוא\"ח סתקפ\"א ד\"ה והעבירו. ר\"ח שער התשובה פ\"ד ד\"ה עוד יש (קטו, ב). של\"ה ריש מס' ר\"ה ריג, א. לקו\"ת פ' ראה יט, א. לג, ד."],["4751","21","<b>דרשו ה' בהמצאו</b>: ישעי' נה, ו. ראה ר\"ה יח, א.\n\n<b>א</b>  ובהערת המו\"ל שם מציין שכ\"ה בפענח רזא כ\"י מינכן בשם ר' אלעזר."]]],[2000480458,"מזמור ממעמקים<sup data-n=\"4752\">22</sup> קראתיך ה'<sup data-n=\"4753\">23</sup> ולכאו' הול\"ל מעומק מהו ממעמקים, והענין שיש ב' עומקי'<sup data-n=\"4754\">24</sup> עומק ועומק לפנים מעומק, ועל ל' החסידות הו\"ע תשובה תשוב ה'<sup data-n=\"4755\">25</sup> עילאה לגבי יו\"ד והה' הוא במילוי יוד ותשוב ה' הוא בחי' בינה<sup data-n=\"4756\">26</sup> ליבא<sup data-n=\"4757\">27</sup> בחי' פנימיות הלב, והיו\"ד שבהעלם בה' הוא בחי' תעלומות לב שבהעלם פנימיות הלב, ועל ל' הקבלה ממעמקים הם ב' יסודות דאו\"א יסוד אי' הוא בחי' פנימיות ויסוד שגניז בפנימיות הלב הוא בחי' תעלומות לב והוא עומק הב' שלפנים מבחי' פנימיות הלב.\n<b>ולהבין</b> ענין פנימיות הלב ותעלומות הלב יובן מפעולה שלהם, דהנה אמרז\"ל חמשים שערי בינה<sup data-n=\"4758\">28</sup> נברא בעולם הרי נק' שערים ועל בחי' חכ' אי' בס\"י בל\"ב נתיבות<sup data-n=\"4759\">29</sup> פליאות חכ' הרי נק' נתיבות, דהנה שער משמש כניסה ויציאה והשער הוא שער רחב אך הוא במקום קרוב כמו היציאה מחצר לרה\"ר הוא בקרוב וכמו\"כ הכניסה מר\"ה לחצר הוא במקום קרוב, וכמו\"כ יובן הנמשל למעלה דנק' שערי בינה שהשער הוא רחב ומשמש כניסה ויציאה היינו לידת המדות הם מהבינה דבינה נק' אם הבנים<sup data-n=\"4760\">31</sup>, דע\"י ההתבוננות בגדולת הא\"ס נולד אהבה לאלקות, וכמו\"כ משמש כניסה הוא ביטל המדות וכמ\"ש לך ה' הגדולה<sup data-n=\"4761\">32</sup> כו' הוא ג\"כ ע\"י הבינה, אך הוא במקום קרוב דהנה ארז\"ל<sup data-n=\"4762\">33</sup> יוסף יתום מאמו<sup data-n=\"4763\">34</sup>, דכתי' אלה תולדות יעקב יוסף<sup data-n=\"4764\">35</sup>, פי' הגילוים דיעקב הוא יוסף שהוא הי' מרכבה<sup data-n=\"4765\">36</sup> לבחי' מדרי' צ\"ע<sup data-n=\"4766\">37</sup> לכן כתי'",[["4752","22","<b>ובעשי\"ת אומרים מזמור ממעמקים</b>: ראה סידור אדה\"ז לפני ברכו. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תתמא ובהנסמן במ\"מ לשם. מאמרי אדה\"א דברים ח\"ג ע' תתסט. וש\"נ. תו\"ח בשלח ח\"א רכט, ב. וש\"נ. סה\"מ תרל\"ח ע' שיט. וש\"נ."],["4753","23","<b>ממעמקים קראתיך ה'</b>: תהלים קל, א."],["4754","24","<b>ב' עומקי'</b>: ראה לקו\"ת נצבים מה, ד (ושם מציין גם ללקו\"ת שמ\"ע פו, ד). פ' ראה יח, ג. לקמן ובהערה 66."],["4755","25","<b>תשובה תשוב ה'</b>: ראה זהר רע\"מ נשא קכב, א."],["4756","26","<b>ה'. . בינה</b>: ראה אגה\"ת פ\"ד."],["4757","27","<b>בינה ליבא</b>: ת\"ז בהקדמה יז, א."],["4758","28","<b>חמשים שערי בינה</b>: ר\"ה כא, ב. ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה נעשה אדם פ\"ב ובהערה 17."],["4759","29","<b>אי' בס\"י בל\"ב נתיבות</b>: פ\"א, מ\"א. ראה גם הנסמן במאמרי אדה\"א בראשית ע' ג."],["4760","31","<b>דבינה נק' אם הבנים</b>: ראה זהר ויחי ריט, א. יתרו פד, א. פה, ב. פרדס שעה\"כ שכ\"ג, פ\"א מערכת אם הבנים. לקו\"ת שמ\"ע פח, ד. שעה\"י קי, ב ובהערה 19."],["4761","32","<b>לך ה' הגדולה</b>: דבהי\"א כט, יא. ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה נעשה אדם פ\"ב בתחילתו."],["4762","33","<b>ארז\"ל</b>: אמר רבינו ז\"ל והכוונה שהביאור דבסמוך אמרו אדה\"ז."],["4763","34","<b>יוסף יתום מאמו</b>: ראה ע\"ח שער הצלם שכ\"ו, פ\"ג. מאמרי אדה\"א נ\"ך ע' קיח. וש\"נ. שעה\"י קלד, ב ובהערה 55."],["4764","35","<b>אלה תולדות יעקב יוסף</b>: וישב לז, ב. ראה גם לעיל (בחלק המאמרים) מאמר ד\"ה רני ושמחי ובהערה 75. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה בן פורת יוסף הא' ובהערה 40."],["4765","36","<b>יוסף שהוא הי' מרכבה</b>: ראה גם תו\"ח משפטים ח\"ב רפד, ג."],["4766","37","<b>יוסף. . מדרי' צ\"ע</b>: ראה זהר ויצא קנג, ב. ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה רני ושמחי ובהערה 42."]]],[2000480459,"ויוסף הוא המשביר<sup data-n=\"4767\">39</sup> לכל עם הארץ שהוא מקור המשפיע לבחי' צדיק תחתון<sup data-n=\"4768\">38</sup> והי' יתום מאמו דבינה עד הוד אתפשטות<sup data-n=\"4769\">40</sup> וא\"כ השפעת יוסף הי' לא מבחי' בינה כ\"א מבחי' יסוד אבא ארוך<sup data-n=\"4770\">41</sup> וזהו מקום קרוב רק עד בחי' הוד, והמשל דנתיב<sup data-n=\"4771\">30</sup> הוא דהנתיב הוא קצר לא כמו הדרך שהוא דרך רחב משא\"כ הנתיב הוא נתיב קצר אך הולך למרחוק בשדות אפי' במדבריות, וכמו\"כ יובן הנמשל למעלה שנק' נתיב שהוא קצר היינו שהוא בהעלם אך הולך למרחוק כמו חכ' התורה שנתלבשה בדברים גשמים ציצית בצמר גשמי תפילין בקלף גשמי ד\"מ שבלולב בצמחים גשמים סוכה בסכך הגשמי שופר בדבר גשמי, וכמו\"כ תרומות ומעשרות הם צמחים מהארץ שהם דברים גשמים, וגם כל המצות יש להם הגבלה כמו סוכה צ\"ל לא פחות מז\"ט ומשהו<sup data-n=\"4772\">42</sup> ולא יותר מכ' אמה דלא שלטא בי' עיני'<sup data-n=\"4773\">43</sup> לכן נק' נתיב (בפ\"א ושרשם מהחכ' שהרי כל המצות הם בהגבלה כו').\n<b>והנה</b> על לע\"ל כתי' וכל גבולך לאבני חפץ ותחילה כתי' ושעריך לאבני אקדח<sup data-n=\"4774\">44</sup> וכל גבולך כו' פי' מבחי' שערים נעשה בחי' אבני אקדח, אבל מבחי' נתיב כל גבולך יהי' אבני חפץ דאהבה זו הוא למעלה מבחי' אהבה ברשפי אש שהוא בחי' אבני אקדח שהוא אבן בוער בל\"א<sup data-n=\"4775\">45</sup> פינקולט והוא בחי' אהבה ברשפי אש בהתגלות לבו ונמשך מבחי' שערים שהם כנגד ז' מדות וכל מדה כלול מז' הרי מ\"ט ושער החמשים הוא עצם הבינה<sup data-n=\"4776\">46</sup>, נמצא יש שער לכל מדה ומדה לכן נולד מזה האהבה ברשפי אש בגילוי לעין כל, אבל בחי' אבני חפץ הוא אהבה שהיא מוסתרת ונעלמת אך היא אהבה עזה מאד (בפ\"א עד שיוכל להיות שיופרד הנפש לגמרי מהגוף) יותר אין ערוך מבחי' אהבה ברשפי אש, ויובן זה מלעו\"ז<sup data-n=\"4777\">47</sup> דאי' בגמ' מעשה באחד שהעלה בלבו טינא<sup data-n=\"4778\">48</sup> ושאלו לרופאים כו' וחכמים העמידו דבריהם ואמרו ימות כו' הרי יוכל להיות אהבה עזה כ\"כ עד שיופרד הנפש מהגוף אפי' בסט\"א, וכ\"ש בקדושה שיוכל אהבה<sup data-n=\"4779\">49</sup> אשר מחמתה יתבטלו כל כחות נפשו לבד כח זה, וזהו נק'",[["4767","39","<b>ויוסף הוא המשביר</b>: מקץ מב, ו (בדילוג — ראה לעיל הנחה ד\"ה יונתי בחגוי הסלע ובהערה 32)."],["4768","38","<b>צ\"ע. . צדיק תחתון</b>: ראה הערה שלפנ\"ז."],["4769","40","<b>דבינה עד הוד אתפשטות</b>: ראה זהר רע\"מ פינחס רכג, ב. אמרי בינה שער התפילין קכ, ד. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תקפה."],["4770","41","<b>יסוד אבא ארוך</b>: ראה ע\"ח שער הכללים פ\"י. מאמרי אדה\"א דברים ח\"ב ע' שעח. וש\"נ. תו\"ח תצוה ח\"ב של, א. וש\"נ."],["4771","30","<b>דהנה שער. . והמשל דנתיב</b>: ראה גם לקו\"ת פ' ראה כו, ב. אמ\"ב שער התפילין קכא, א ואילך."],["4772","42","<b>סוכה. . מז\"ט ומשהו</b>: באגה\"ק ס\"י: ז\"ט. ראה סה\"מ תרל\"ב ח\"א ע' פד ובהערה שם. (לעיל בחלק המאמרים) המשך יונתי ובהערה 270."],["4773","43","<b>ולא יותר מכ' אמה. . עיני'</b>: סוכה ב, א."],["4774","44","<b>וכל גבולך לאבני חפץ. . לאבני אקדח</b>: ישעי' נד, יב."],["4775","45","<b>בל\"א</b>: בלשון אידיש. ראה שיחת ליל הושע\"ר תשנ\"ב אות ג (שיחות קודש ע' 165 ואילך). ליל שמח\"ת קודם הקפות תשנ\"ב — סה\"ש תשנ\"ב ח\"א ע' 38 בשולי הגליון להערה 20. לקו\"ש משפטים כרך כא ע' 448 הערה 15."],["4776","46","<b>שערים. . ז' מדות. . מ\"ט. . עצם הבינה</b>: ראה לקו\"ת במדבר י, ד. מטות פה, ב. לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה נעשה אדם פ\"ב."],["4777","47","<b>מלעו\"ז</b>: קהלת ז, יד. ראה גם סה\"מ תרל\"ח ע' קלד."],["4778","48","<b>מעשה באחד שהעלה בלבו טינא</b>: ראה סנהדרין עה, א."],["4779","49","<b>שיוכל אהבה</b>: אוצ\"ל: שיוכל להיות אהבה."]]]]});
